INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13764, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "补充性", "is_correct": true, "explanation": "正确：“只起补充性作用”指数据只起辅助参考的作用，与“只”的限定语气相符。"}, {"text": "决定性", "is_correct": false, "explanation": "语义：“决定性作用”指起关键作用，与“只”的限定语气矛盾，数据不能“只起决定性作用”。"}, {"text": "阻碍性", "is_correct": false, "explanation": "语义：数据是补充论证的资料，只起阻碍作用与句意相反。"}, {"text": "无关性", "is_correct": false, "explanation": "语义：“无关性”指毫不相干，与数据应起的作用相反，句意不通。"}], "explanations": {"补充性": "正确：“只起补充性作用”指数据只起辅助参考的作用，与“只”的限定语气相符。", "决定性": "语义：“决定性作用”指起关键作用，与“只”的限定语气矛盾，数据不能“只起决定性作用”。", "阻碍性": "语义：数据是补充论证的资料，只起阻碍作用与句意相反。", "无关性": "语义：“无关性”指毫不相干，与数据应起的作用相反，句意不通。"}, "sentence_index": 6, "correct_answer": "补充性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这门课有补充性作用，是学好数学的前提。", "explanation": "这里应该用〈基础性〉。补充性指辅助、补充，不是根基；说“前提”要用〈基础性〉。"}, {"text": "这个方案的补充性很强，它完全取代了原来的全部计划。", "explanation": "词义错误：这里说的是取代，应该用〈替代性〉。补充性指增加内容使整体更完善，不表示替换。"}, {"text": "这次相遇的补充性很强，完全是偶然的。", "explanation": "这里应该用〈偶然性〉。补充性指增加内容使整体更完善，与事情出于意外无关；描述相遇的意外性质要用〈偶然性〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '450d132b-4bd7-4a84-8933-49fea60b7584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13764, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这套题的补充性强很，学生可以用来查漏补缺。", "corrected_sentence": "这套题的补充性很强，学生可以用来查漏补缺。", "error_description": "语序错误：程度副词“很”应放在形容词“强”之前，“补充性很强”是正确说法，不说“补充性强很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '450d132b-4bd7-4a84-8933-49fea60b7584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13764, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本书的补充性强很，能帮助学生理解课文。", "corrected_sentence": "这本书的补充性很强，能帮助学生理解课文。", "error_description": "语序错误：程度副词“很”应放在形容词“强”之前，应说“补充性很强”，不说“补充性强很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '450d132b-4bd7-4a84-8933-49fea60b7584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
