INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13768, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "自然规律指自然界中事物运动、变化和发展所遵循的、不以人的意志为转移的客观法则。", "primary_collocate": null, "pronunciation": "zì rán guī lǜ", "ipa": "tsɻ̩˥˩ ʐan˧˥ kweɪ˥ ly˥˩", "syllable_count": 4, "sentences": [{"text": "回望历史，从木质风车到纳米级光伏材料，能源技术的演化本质是人类对自然规律认知深度的具象化。", "target_word": "自然规律", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "科学家一直在研究自然规律。", "target_word": "自然规律", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人不能改变自然规律，只能认识它。", "target_word": "自然规律", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春去秋来是自然规律，谁也改变不了。", "target_word": "自然规律", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民按照自然规律种地，才能有好收成。", "target_word": "自然规律", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "牛顿发现了许多重要的自然规律。", "target_word": "自然规律", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "违反自然规律的做法，最后一定会失败。", "target_word": "自然规律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师常带学生观察和了解自然规律。", "target_word": "自然规律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们必须尊重自然规律，不能乱砍树木。", "target_word": "自然规律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上说，日出日落是一种自然规律。", "target_word": "自然规律", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "自然界客观法则，不以人的意志为转移", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbdf5e2f-210f-4716-b9b6-47323c31ed04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13768, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "美食", "is_correct": false, "explanation": "语义：句中讲的是人对自然规律的认知，美食与之无关，放进空格后语义不通。"}, {"text": "自然规律", "is_correct": true, "explanation": "正确：“人类对自然规律认知深度的具象化”指对自然界客观法则的认识，与句中的能源技术演化语境吻合。"}, {"text": "八卦", "is_correct": false, "explanation": "语域：“八卦”是口语词，与这句书面语的语体不协调。"}, {"text": "足球", "is_correct": false, "explanation": "语义：句中讲的是人对自然界法则的认知，足球与之无关。"}], "explanations": {"美食": "语义：句中讲的是人对自然规律的认知，美食与之无关，放进空格后语义不通。", "自然规律": "正确：“人类对自然规律认知深度的具象化”指对自然界客观法则的认识，与句中的能源技术演化语境吻合。", "八卦": "语域：“八卦”是口语词，与这句书面语的语体不协调。", "足球": "语义：句中讲的是人对自然界法则的认知，足球与之无关。"}, "sentence_index": 0, "correct_answer": "自然规律"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校的自然规律规定我们每天七点到校。", "explanation": "这里应该用〈规则〉。自然规律指自然界不以人的意志为转移的法则，不能用来指学校这类人为的规定。"}, {"text": "我们班的自然规律是每周五打扫教室。", "explanation": "这里应该用〈约定〉。自然规律是不随人意改变的法则，不能用来指班里商定的事。"}, {"text": "妈妈把菜端上桌，自然规律很香。", "explanation": "这里不能用〈自然规律〉形容食物。它指自然界的法则，不能描述气味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e98ee5d-27a7-4a7a-841a-afebe2286d71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13768, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕不是可以“违反”的对象，句中说的是违背自然界法则的做法。"}, {"text": "自然规律", "is_correct": true, "explanation": "正确：“违反自然规律的做法”指违背自然界的客观法则，与“最后一定会失败”的语境吻合。"}, {"text": "饭碗", "is_correct": false, "explanation": "语义：饭碗是器物，不是可以“违反”的法则，放进句中说不通。"}, {"text": "诗歌", "is_correct": false, "explanation": "语义：诗歌不是可以“违反”的法则，“违反诗歌的做法”说不通。"}], "explanations": {"蛋糕": "语义：蛋糕不是可以“违反”的对象，句中说的是违背自然界法则的做法。", "自然规律": "正确：“违反自然规律的做法”指违背自然界的客观法则，与“最后一定会失败”的语境吻合。", "饭碗": "语义：饭碗是器物，不是可以“违反”的法则，放进句中说不通。", "诗歌": "语义：诗歌不是可以“违反”的法则，“违反诗歌的做法”说不通。"}, "sentence_index": 6, "correct_answer": "自然规律"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌的自然规律很好听。", "explanation": "这里应该用〈旋律〉。自然规律指自然界的法则，不能用来评价歌曲的好听与否。"}, {"text": "这件衣服的自然规律很合身。", "explanation": "这里应该用〈版型〉。自然规律指自然界的法则，不能用来形容衣服的剪裁。"}, {"text": "这个节目的自然规律很精彩，观众都很喜欢。", "explanation": "这里应该用〈内容〉或〈表演〉。自然规律指自然界的法则，不能用来评价节目。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e98ee5d-27a7-4a7a-841a-afebe2286d71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13768, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "科学家发现了一只自然规律。", "corrected_sentence": "科学家发现了一个自然规律。", "error_description": "量词错误：“自然规律”的常用量词是“个”，“只”只用于动物等。应说“一个自然规律”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e98ee5d-27a7-4a7a-841a-afebe2286d71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13768, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们要学会顺应把自然规律。", "corrected_sentence": "我们要学会顺应自然规律。", "error_description": "把字句误用：“顺应”后直接接宾语，前面不能加“把”，应说“顺应自然规律”，不说“顺应把自然规律”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e98ee5d-27a7-4a7a-841a-afebe2286d71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
