INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13769, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，用在动词、形容词或名词前，表示否定。", "primary_collocate": null, "pronunciation": "fēi", "ipa": "fei˥", "syllable_count": 1, "sentences": [{"text": "每一次突破都非孤立发明，而是基础科学、工程实践与社会需求共振的产物。", "target_word": "非", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "这笔钱非我所有，我不能用。", "target_word": "非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他非本地人，不太懂这里的习惯。", "target_word": "非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "成功非一日之功，要慢慢努力。", "target_word": "非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事非你的错，别太难过。", "target_word": "非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "答案非对即错，没有中间的选择。", "target_word": "非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里非公共场所，请不要随便进入。", "target_word": "非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的话非事实，大家不要相信。", "target_word": "非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这非我本意，请你相信我。", "target_word": "非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学习非易事，但他从不放弃。", "target_word": "非", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "用在动词、形容词或名词前表示否定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65bf7ffb-9382-49a3-a249-55e085870a35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13769, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "非", "is_correct": true, "explanation": "正确答案：非，fēi（第一声），副词，表示否定“不是”。"}, {"text": "肥", "is_correct": false, "explanation": "肥 féi（第二声）与 fēi（第一声）声调不同，意思是胖。"}, {"text": "分", "is_correct": false, "explanation": "分 fēn 韵母不同（en 与 ei），意思是分开、分数。"}, {"text": "匪", "is_correct": false, "explanation": "匪 fěi（第三声）与 fēi（第一声）声调不同，意思是盗匪。"}, {"text": "费", "is_correct": false, "explanation": "费 fèi（第四声）与 fēi（第一声）声调不同，意思是花费。"}], "explanations": {"非": "正确答案：非，fēi（第一声），副词，表示否定“不是”。", "肥": "肥 féi（第二声）与 fēi（第一声）声调不同，意思是胖。", "分": "分 fēn 韵母不同（en 与 ei），意思是分开、分数。", "匪": "匪 fěi（第三声）与 fēi（第一声）声调不同，意思是盗匪。", "费": "费 fèi（第四声）与 fēi（第一声）声调不同，意思是花费。"}, "sentence_index": null, "correct_answer": "非"}, "level_3": {"options": [{"text": "非", "is_correct": true, "explanation": "正确：“非”表示否定，与后面的“而是”呼应，构成“非……而是……”的格式。"}, {"text": "很", "is_correct": false, "explanation": "搭配：“很”是程度副词，不能直接修饰“孤立发明”这样的名词短语，句子不通。"}, {"text": "并", "is_correct": false, "explanation": "搭配：“并”一般要与“不”“没”连用才表示否定，单用后接“孤立发明”不成立。"}, {"text": "正", "is_correct": false, "explanation": "语法：“正”不能直接放在名词短语“孤立发明”前，且句子缺少与“而是”呼应的否定，句子不通。"}], "explanations": {"非": "正确：“非”表示否定，与后面的“而是”呼应，构成“非……而是……”的格式。", "很": "搭配：“很”是程度副词，不能直接修饰“孤立发明”这样的名词短语，句子不通。", "并": "搭配：“并”一般要与“不”“没”连用才表示否定，单用后接“孤立发明”不成立。", "正": "语法：“正”不能直接放在名词短语“孤立发明”前，且句子缺少与“而是”呼应的否定，句子不通。"}, "sentence_index": 0, "correct_answer": "非"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他非我的亲戚，他是我的亲哥哥。", "explanation": "这里应该用〈是〉。非表示否定判断，说“他不是我的亲戚”，下句却说“是我的亲哥哥”，自相矛盾；肯定判断要用“是”。"}, {"text": "我的爸爸非我的亲人，他从小一直照顾我。", "explanation": "这里应该用〈是〉。非表示否定判断，说“爸爸不是我的亲人”，与“从小一直照顾我”矛盾；肯定判断要用“是”。"}, {"text": "这把伞非我的，那是我从小一直用的家传伞。", "explanation": "这里应该用〈是〉。非表示否定判断，说“这把伞不是我的”，与“我从小一直用的家传伞”矛盾；肯定判断要用“是”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '450d132b-4bd7-4a84-8933-49fea60b7584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13769, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "非", "is_correct": true, "explanation": "正确答案：非，fēi（第一声），副词，表示否定“不是”。"}, {"text": "废", "is_correct": false, "explanation": "废 fèi（第四声）与 fēi（第一声）声调不同，意思是废弃。"}, {"text": "匪", "is_correct": false, "explanation": "匪 fěi（第三声）与 fēi（第一声）声调不同，意思是盗匪。"}, {"text": "杯", "is_correct": false, "explanation": "杯 bēi 声母不同（b 与 f），意思是杯子。"}, {"text": "黑", "is_correct": false, "explanation": "黑 hēi 声母不同（h 与 f），意思是黑色。"}], "explanations": {"非": "正确答案：非，fēi（第一声），副词，表示否定“不是”。", "废": "废 fèi（第四声）与 fēi（第一声）声调不同，意思是废弃。", "匪": "匪 fěi（第三声）与 fēi（第一声）声调不同，意思是盗匪。", "杯": "杯 bēi 声母不同（b 与 f），意思是杯子。", "黑": "黑 hēi 声母不同（h 与 f），意思是黑色。"}, "sentence_index": null, "correct_answer": "非"}, "level_3": {"options": [{"text": "非", "is_correct": true, "explanation": "正确：“非”表示否定，“非公共场所”即“不是公共场所”，与后句“请不要随便进入”的理由一致。"}, {"text": "也", "is_correct": false, "explanation": "搭配：“也”要与“是”或谓语连用，不能直接修饰“公共场所”这样的名词短语。"}, {"text": "确", "is_correct": false, "explanation": "语义：“确”表示确实，说“确是公共场所”，就与后句“请不要随便进入”的理由相矛盾。"}, {"text": "却", "is_correct": false, "explanation": "搭配：“却”表示转折，需要前文有相对的语境，且不能直接修饰名词短语“公共场所”。"}], "explanations": {"非": "正确：“非”表示否定，“非公共场所”即“不是公共场所”，与后句“请不要随便进入”的理由一致。", "也": "搭配：“也”要与“是”或谓语连用，不能直接修饰“公共场所”这样的名词短语。", "确": "语义：“确”表示确实，说“确是公共场所”，就与后句“请不要随便进入”的理由相矛盾。", "却": "搭配：“却”表示转折，需要前文有相对的语境，且不能直接修饰名词短语“公共场所”。"}, "sentence_index": 6, "correct_answer": "非"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的班长非我，大家都选了我做班长。", "explanation": "这里应该用〈是〉。非表示否定，说“班长不是我”，与“大家都选了我做班长”矛盾；肯定判断要用“是”。"}, {"text": "这块蛋糕非我做的，我从头到尾都亲手做了。", "explanation": "这里应该用〈是〉。非表示否定，说“蛋糕不是我做的”，与“我从头到尾都亲手做了”矛盾；肯定判断要用“是”。"}, {"text": "他非参加比赛的人，比赛时拿了冠军。", "explanation": "这里应该用〈是〉。非表示否定，说“他不是参加比赛的人”，与“比赛时却拿了冠军”矛盾；肯定判断要用“是”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '450d132b-4bd7-4a84-8933-49fea60b7584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13769, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份报告很非他写的，是同事写的。", "corrected_sentence": "这份报告非他写的，是同事写的。", "error_description": "程度副词误用：“非”作否定判断，不能受“很”修饰，应删去“很”，即“非他写的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '450d132b-4bd7-4a84-8933-49fea60b7584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13769, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这间屋子我非的，是朋友的。", "corrected_sentence": "这间屋子非我的，是朋友的。", "error_description": "错误形式：我非的；正确形式：非我的。“非”应放在被判断的名词性短语之前，放在“我”后语序不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '450d132b-4bd7-4a84-8933-49fea60b7584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13770, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "团结", "is_correct": true, "explanation": "正确。“团结”与“孤立”相反，指彼此支持、联合在一起。"}, {"text": "迅速", "is_correct": false, "explanation": "“迅速”形容速度，与“孤立”的状态不构成对立，不是反义。"}, {"text": "活泼", "is_correct": false, "explanation": "活泼形容性格或动作生动，与“孤立”的状态不构成对立。"}, {"text": "安静", "is_correct": false, "explanation": "安静是“吵闹”的反义，与“孤立”的状态不构成对立。"}], "correct_answer": "团结", "explanations": {"团结": "正确。“团结”与“孤立”相反，指彼此支持、联合在一起。", "迅速": "“迅速”形容速度，与“孤立”的状态不构成对立，不是反义。", "活泼": "活泼形容性格或动作生动，与“孤立”的状态不构成对立。", "安静": "安静是“吵闹”的反义，与“孤立”的状态不构成对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e98ee5d-27a7-4a7a-841a-afebe2286d71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13770, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "团结", "is_correct": true, "explanation": "正确。“团结”与“孤立”相反，指联合在一起、互相支持。"}, {"text": "繁忙", "is_correct": false, "explanation": "繁忙形容事务多、忙碌，与“孤立”没有对立关系。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮形容光线充足或亮堂，与“孤立”没有对立关系。"}, {"text": "轻松", "is_correct": false, "explanation": "轻松形容心情或负担少，与“孤立”的对立关系不成立。"}], "correct_answer": "团结", "explanations": {"团结": "正确。“团结”与“孤立”相反，指联合在一起、互相支持。", "繁忙": "繁忙形容事务多、忙碌，与“孤立”没有对立关系。", "明亮": "明亮形容光线充足或亮堂，与“孤立”没有对立关系。", "轻松": "轻松形容心情或负担少，与“孤立”的对立关系不成立。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e98ee5d-27a7-4a7a-841a-afebe2286d71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13770, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指一个人或事物失去他人的支持或联系，处于独自无援的状态。", "primary_collocate": null, "pronunciation": "gū lì", "ipa": "ku˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "每一次突破都非孤立发明，而是基础科学、工程实践与社会需求共振的产物。", "target_word": "孤立", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个小国在国际上很孤立。", "target_word": "孤立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在公司里很孤立，没人帮他。", "target_word": "孤立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种做法使该国陷入孤立。", "target_word": "孤立", "complexity_tier": "T3", "furigana": "zhè zhǒng zuòfǎ shǐ gāi guó xiànrù gūlì.", "sentence_source": "generated"}, {"text": "没有朋友的帮助，他的处境很孤立。", "target_word": "孤立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座山村路不通，显得很孤立。", "target_word": "孤立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一种事物不会孤立存在，总是和别的事物有联系。", "target_word": "孤立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板的决定让他在团队里更加孤立。", "target_word": "孤立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的意见没人支持，他显得很孤立。", "target_word": "孤立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个团体长期遭到排挤，变得十分孤立。", "target_word": "孤立", "complexity_tier": "T3", "furigana": "zhè ge tuántǐ chángqī zāodào páijǐ, biàn de shífēn gūlì.", "sentence_source": "generated"}], "morphological_forms": [{"form": "孤立地", "label": "副词形式"}], "register": "书面", "sense_fingerprint": "失去支持或联系，独自无援的状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbdf5e2f-210f-4716-b9b6-47323c31ed04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13770, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "孤立", "is_correct": true, "explanation": "正确。“非孤立发明”指发明不是孤零零完成的，与后文“共振的产物”相呼应。"}, {"text": "免费", "is_correct": false, "explanation": "语义：“非免费发明”与前后语境不符，突破的产生与是否免费无关。"}, {"text": "静止", "is_correct": false, "explanation": "搭配：“静止”形容状态，不修饰“发明”，而且句中“共振”是动态的，与“静止”矛盾。"}, {"text": "固定", "is_correct": false, "explanation": "搭配：“固定”不能修饰“发明”，“非固定发明”读来不通。"}], "explanations": {"孤立": "正确。“非孤立发明”指发明不是孤零零完成的，与后文“共振的产物”相呼应。", "免费": "语义：“非免费发明”与前后语境不符，突破的产生与是否免费无关。", "静止": "搭配：“静止”形容状态，不修饰“发明”，而且句中“共振”是动态的，与“静止”矛盾。", "固定": "搭配：“固定”不能修饰“发明”，“非固定发明”读来不通。"}, "sentence_index": 0, "correct_answer": "孤立"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家餐厅的菜很孤立，味道很好。", "explanation": "这里应该用〈特色〉。孤立指失去他人的支持或联系，不能用来形容菜的特点。"}, {"text": "我们要培养孩子的孤立能力，不要太依赖别人。", "explanation": "这里应该用〈独立〉。独立指自己做事、不依赖别人，孤立指失去支持，不能用来说培养能力。"}, {"text": "这幅画的色彩很孤立，看起来很舒服。", "explanation": "这里应该用〈柔和〉或〈鲜艳〉。孤立指失去支持或联系，不能用来形容色彩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e98ee5d-27a7-4a7a-841a-afebe2286d71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13770, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "孤立", "is_correct": true, "explanation": "正确。“不会孤立存在”说明事物总与别的事物相连，与后句呼应。"}, {"text": "漂亮", "is_correct": false, "explanation": "搭配：“漂亮”形容外貌，不修饰“存在”，与句中的语义无关。"}, {"text": "整齐", "is_correct": false, "explanation": "搭配：“整齐”形容排列，不修饰“存在”，“整齐存在”读来不通。"}, {"text": "平淡", "is_correct": false, "explanation": "搭配：“平淡”形容风格或状态，不能用来修饰“存在”。"}], "explanations": {"孤立": "正确。“不会孤立存在”说明事物总与别的事物相连，与后句呼应。", "漂亮": "搭配：“漂亮”形容外貌，不修饰“存在”，与句中的语义无关。", "整齐": "搭配：“整齐”形容排列，不修饰“存在”，“整齐存在”读来不通。", "平淡": "搭配：“平淡”形容风格或状态，不能用来修饰“存在”。"}, "sentence_index": 6, "correct_answer": "孤立"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌的节奏很孤立，听起来很舒服。", "explanation": "这里应该用〈和谐〉或〈流畅〉。孤立指失去他人的支持或联系，不能用来形容节奏。"}, {"text": "这家店的服务很孤立，客人都很满意。", "explanation": "这里应该用〈周到〉。孤立指失去他人的支持或联系，不能用来形容服务的态度。"}, {"text": "他一口气把蛋糕孤立了，全部吃光了。", "explanation": "这里应该用〈吃掉〉。孤立指失去他人的支持或联系，不能用来形容吃东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e98ee5d-27a7-4a7a-841a-afebe2286d71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13770, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在新班级里非常孤立着，没人帮他。", "corrected_sentence": "他在新班级里非常孤立，没人帮他。", "error_description": "体标误用：“孤立”在这里是形容词作谓语，表示状态，后面不能加“着”。应删去“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e98ee5d-27a7-4a7a-841a-afebe2286d71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13770, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "失去了盟友，这个国家的处境很孤立地。", "corrected_sentence": "失去了盟友，这个国家的处境很孤立。", "error_description": "“孤立”在句中作谓语，后面不能加“地”；“孤立地”只用来修饰动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e98ee5d-27a7-4a7a-841a-afebe2286d71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13771, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dff0ae95-8d23-42c5-a1f9-dc49589f7ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13771, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dff0ae95-8d23-42c5-a1f9-dc49589f7ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13771, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "基础科学指研究自然界基本规律和原理的科学，为应用科学提供理论支撑。", "primary_collocate": null, "pronunciation": "jī chǔ kē xué", "ipa": "tɕi˥ ʈʂʰu˨˩˦ kʰɤ˥ ɕɥe˧˥", "syllable_count": 4, "sentences": [{"text": "每一次突破都非孤立发明，而是基础科学、工程实践与社会需求共振的产物。", "target_word": "基础科学", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "基础科学为应用科学提供理论支持。", "target_word": "基础科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "物理和化学都属于基础科学。", "target_word": "基础科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家每年投入很多钱支持基础科学。", "target_word": "基础科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "基础科学不一定马上有用，但很重要。", "target_word": "基础科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小喜欢基础科学，后来成了研究员。", "target_word": "基础科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有基础科学，就没有新技术。", "target_word": "基础科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学里的基础科学课很难，但很有意思。", "target_word": "基础科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "基础科学的发现要很多年才能用到生活中。", "target_word": "基础科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师一辈子都在研究基础科学。", "target_word": "基础科学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "基础科学研究", "label": "复合"}], "register": "书面语", "sense_fingerprint": "研究自然界基本规律、为应用科学提供理论的学科门类", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33b2cc55-a89d-45a8-b3eb-d0c547cd39fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13771, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "日常琐事", "is_correct": false, "explanation": "语义：日常琐事与“突破”以及工程实践、社会需求的“共振”不相称，不能作为突破的来源。"}, {"text": "基础科学", "is_correct": true, "explanation": "基础科学指研究自然界基本规律的学科，与工程实践、社会需求并列，句意通顺。"}, {"text": "宠物", "is_correct": false, "explanation": "语义：宠物不是突破的来源，与“工程实践”“社会需求”并列也不成立。"}, {"text": "个人情绪", "is_correct": false, "explanation": "搭配：“共振”一般指需求、思想、力量之间的呼应，不与个人情绪搭配。"}], "explanations": {"日常琐事": "语义：日常琐事与“突破”以及工程实践、社会需求的“共振”不相称，不能作为突破的来源。", "基础科学": "基础科学指研究自然界基本规律的学科，与工程实践、社会需求并列，句意通顺。", "宠物": "语义：宠物不是突破的来源，与“工程实践”“社会需求”并列也不成立。", "个人情绪": "搭配：“共振”一般指需求、思想、力量之间的呼应，不与个人情绪搭配。"}, "sentence_index": 0, "correct_answer": "基础科学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂直接把基础科学投入生产线，马上就能赚钱。", "explanation": "这里应该用〈应用科学〉。基础科学重在探索自然的基本规律，不直接用于生产；直接投入生产线的是应用科学。"}, {"text": "他在工地上检查基础科学，确保楼房不会下沉。", "explanation": "这里应该用〈地基〉。基础科学是学科，不是建筑的地基，不能被检查，也不能用来支撑楼房。"}, {"text": "他每天把基础科学放进冰箱，怕它坏掉。", "explanation": "这里应该用〈牛奶〉。基础科学是学科，不是食品，不能放进冰箱防止变质。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dff0ae95-8d23-42c5-a1f9-dc49589f7ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13771, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小道消息", "is_correct": false, "explanation": "语义：小道消息不能作为新技术的前提，这一句式的因果逻辑不成立。"}, {"text": "基础科学", "is_correct": true, "explanation": "基础科学是新技术的理论前提，放在「没有……就没有……」句式里合乎句意。"}, {"text": "二手货", "is_correct": false, "explanation": "语域：“二手货”是口语说法，且不指向科技前提，放在这句里不协调。"}, {"text": "地毯", "is_correct": false, "explanation": "语义：地毯与新技术没有前提关系，句子的因果逻辑不成立。"}], "explanations": {"小道消息": "语义：小道消息不能作为新技术的前提，这一句式的因果逻辑不成立。", "基础科学": "基础科学是新技术的理论前提，放在「没有……就没有……」句式里合乎句意。", "二手货": "语域：“二手货”是口语说法，且不指向科技前提，放在这句里不协调。", "地毯": "语义：地毯与新技术没有前提关系，句子的因果逻辑不成立。"}, "sentence_index": 6, "correct_answer": "基础科学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位老师是一位著名的基础科学。", "explanation": "这里应该用〈科学家〉。基础科学指学科领域，不指人，不能用“一位”来称呼老师。"}, {"text": "这位老师每天都在打扫基础科学，很辛苦。", "explanation": "这里应该用〈教室〉。“打扫”针对教室、地面等具体的空间，基础科学是学科，不能被打扫。"}, {"text": "这位老师一辈子都在写基础科学。", "explanation": "这里应该用〈论文〉。“写”的对象是论文、文章，基础科学是学科，不能被“写”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dff0ae95-8d23-42c5-a1f9-dc49589f7ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13771, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们学了一只基础科学。", "corrected_sentence": "我们学了一门基础科学。", "error_description": "量词错误：学科名词“基础科学”应用“门”计量，不能用“只”（“只”多用于动物或成对的东西）。正确说法：我们学了一门基础科学。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dff0ae95-8d23-42c5-a1f9-dc49589f7ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13771, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我很喜欢基础科学们。", "corrected_sentence": "我很喜欢基础科学。", "error_description": "词尾错误：“们”只用于指人的名词之后，“基础科学”是学科名，不能加“们”。正确说法：我很喜欢基础科学。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dff0ae95-8d23-42c5-a1f9-dc49589f7ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
