INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13772, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "多个因素相互配合，共同引发强烈反应或显著效果", "primary_collocate": null, "pronunciation": "gòng zhèn", "ipa": "kʊŋ˥˩ ʈʂən˥˩", "syllable_count": 2, "sentences": [{"text": "每一次突破都非孤立发明，而是基础科学、工程实践与社会需求共振的产物。", "target_word": "共振", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "旺季与优惠政策共振，景区挤满了游客。", "target_word": "共振", "complexity_tier": "T3", "furigana": "gòng zhèn", "sentence_source": "generated"}, {"text": "价格下降和新产品共振，销量一下子上去了。", "target_word": "共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐、灯光和故事共振，观众都哭了。", "target_word": "共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的鼓励和他的努力共振，成绩进步很大。", "target_word": "共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "技术进步与市场需求共振，推动了行业发展。", "target_word": "共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广告和口碑共振，这家店一夜成名。", "target_word": "共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家人的支持和朋友的帮助共振，给了他勇气。", "target_word": "共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "节日气氛与促销活动共振，商场生意特别好。", "target_word": "共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市更新和旅游热共振，老街又热闹起来了。", "target_word": "共振", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "多种因素彼此配合，共同产生强烈效果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57b9e127-76e2-48c8-a316-ec41d410e34d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13772, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "共振", "is_correct": true, "explanation": "正确：此处指基础科学、工程实践与社会需求相互配合，共同产生突破，“共振”正合句意。"}, {"text": "割裂", "is_correct": false, "explanation": "语义：“割裂”指切断、分开，与“突破是多方配合的产物”的句意相反。"}, {"text": "抵消", "is_correct": false, "explanation": "语义：“抵消”指相互削减，不会形成“突破”这样的产物，与前文“非孤立发明”矛盾。"}, {"text": "隔绝", "is_correct": false, "explanation": "搭配：“隔绝”一般说“与……隔绝”，宾语多为空间或联系，不与“需求”组合成“产物”。"}], "explanations": {"共振": "正确：此处指基础科学、工程实践与社会需求相互配合，共同产生突破，“共振”正合句意。", "割裂": "语义：“割裂”指切断、分开，与“突破是多方配合的产物”的句意相反。", "抵消": "语义：“抵消”指相互削减，不会形成“突破”这样的产物，与前文“非孤立发明”矛盾。", "隔绝": "搭配：“隔绝”一般说“与……隔绝”，宾语多为空间或联系，不与“需求”组合成“产物”。"}, "sentence_index": 0, "correct_answer": "共振"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "降价的效果和涨价的影响相互共振，销量没有变化。", "explanation": "这里应该用〈抵消〉。抵消指两种力量相互削减；共振指多种因素相互配合、共同增强效果，两者方向相反，句中用“共振”不对。"}, {"text": "他们两人相互共振，之后谁也不理谁。", "explanation": "这里应该用〈争吵〉。争吵指彼此激烈争执；共振指多种因素相互配合、共同增强效果，不表示言语冲突，句中用错了。"}, {"text": "这台机器需要定期共振，否则容易出故障。", "explanation": "这里应该用〈保养〉。保养指经常维护机器、使其正常运转；共振指多种因素相互配合、共同增强效果，不能用来指维护设备。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc825534-adc9-48cb-9526-1e54bcd38e11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13772, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "共振", "is_correct": true, "explanation": "正确：此处指广告与口碑相互配合，共同产生强烈效果，“共振”正合句意。"}, {"text": "排斥", "is_correct": false, "explanation": "语义：“排斥”指互相拒绝、不相容，与“一夜成名”的结果矛盾。"}, {"text": "背离", "is_correct": false, "explanation": "语义：“背离”指方向相反、各自离开，与“一夜成名”的因果关系不符。"}, {"text": "割舍", "is_correct": false, "explanation": "搭配：“割舍”的对象一般是感情或事物，不与“广告和口碑”组合作主语。"}], "explanations": {"共振": "正确：此处指广告与口碑相互配合，共同产生强烈效果，“共振”正合句意。", "排斥": "语义：“排斥”指互相拒绝、不相容，与“一夜成名”的结果矛盾。", "背离": "语义：“背离”指方向相反、各自离开，与“一夜成名”的因果关系不符。", "割舍": "搭配：“割舍”的对象一般是感情或事物，不与“广告和口碑”组合作主语。"}, "sentence_index": 6, "correct_answer": "共振"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "居民区与工厂区相互共振，各自安静地生活。", "explanation": "这里应该用〈隔离〉。隔离指分开、互不接触；共振指多种因素相互配合、共同增强效果，与“各自安静生活”的语义冲突。"}, {"text": "随着时间推移，热度与关注度相互共振，慢慢消退了。", "explanation": "这里应该用〈衰减〉。衰减指热度或影响逐渐变弱；共振指多种因素相互配合、共同引发强烈反应，方向相反，不表示逐渐消失。"}, {"text": "孩子每天认真共振，从不偷懒。", "explanation": "这里应该用〈写作业〉。写作业指完成学习任务；共振指多种因素相互配合、共同增强效果，不能用来形容孩子做事认真。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc825534-adc9-48cb-9526-1e54bcd38e11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13772, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "资金与人才共振了小镇，这里的变化很大。", "corrected_sentence": "资金与人才共振，这里的变化很大。", "error_description": "带宾语错误：「共振」是不及物动词，不能带宾语「小镇」，应删去「了小镇」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc825534-adc9-48cb-9526-1e54bcd38e11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13772, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "节目和网络宣传很共振，这部剧一下子火了。", "corrected_sentence": "节目和网络宣传共振，这部剧一下子火了。", "error_description": "副词用错：「很」多修饰形容词或心理动词，不修饰「共振」这类表示相互配合的动作，应删去「很」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc825534-adc9-48cb-9526-1e54bcd38e11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
