INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13776, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种用于收集、存放或聚集物品的装置或容器。", "primary_collocate": null, "pronunciation": "shōu jí qì", "ipa": "ʂou̯˥ tɕi˧˥ tɕʰi˥˩", "syllable_count": 3, "sentences": [{"text": "未来能源图景或将超越“发电”本身——建筑幕墙成为透明太阳能收集器，道路涂层集成压电发电单元，甚至人工光合作用系统直接将二氧化碳转化为燃料。", "target_word": "收集器", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这台收集器可以把空气中的灰尘存起来。", "target_word": "收集器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋顶上装着一个太阳能收集器。", "target_word": "收集器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个收集器的盖子坏了，要换一个新的。", "target_word": "收集器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "收集器满了，请把里面的东西倒掉。", "target_word": "收集器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个收集器是用塑料做的，很轻。", "target_word": "收集器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "实验室里的气体收集器连着一根细管。", "target_word": "收集器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明把掉下来的树叶都放进了收集器。", "target_word": "收集器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校门口的收集器专门收旧电池。", "target_word": "收集器", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种收集器能把雨水存起来，用来浇花。", "target_word": "收集器", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "太阳能收集器", "label": "复合"}], "register": "中性", "sense_fingerprint": "收集器：用来收集、存放或聚集物品的装置或容器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33b2cc55-a89d-45a8-b3eb-d0c547cd39fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13776, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "收集器", "is_correct": true, "explanation": "“太阳能收集器”指收集光能的装置，与句中“超越发电”的语境相合。"}, {"text": "枕头", "is_correct": false, "explanation": "语义：枕头不是能源装置，不能成为太阳能收集器。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：饮料不是能源装置，也不是建筑构件，句意不通。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干不是能源装置，也不能作建筑幕墙的变体，句意不通。"}], "explanations": {"收集器": "“太阳能收集器”指收集光能的装置，与句中“超越发电”的语境相合。", "枕头": "语义：枕头不是能源装置，不能成为太阳能收集器。", "饮料": "语义：饮料不是能源装置，也不是建筑构件，句意不通。", "饼干": "语义：饼干不是能源装置，也不能作建筑幕墙的变体，句意不通。"}, "sentence_index": 0, "correct_answer": "收集器"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "下雨了，我撑着一个收集器出门。", "explanation": "这里应该用〈雨伞〉。“收集器”是收集或存放物品的装置，挡雨要用雨伞，撑着出门的不能是收集器。"}, {"text": "他是一位邮票收集器。", "explanation": "这里应该用〈收集者〉。“收集器”指装置或容器，指收集东西的人要用〈收集者〉。"}, {"text": "这台收集器能播放电视节目。", "explanation": "这里应该用〈电视机〉。收集器是收集或存放物品的装置，不能播放节目，播放节目要用电视机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dff0ae95-8d23-42c5-a1f9-dc49589f7ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13776, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "收集器", "is_correct": true, "explanation": "“气体收集器”是连接细管收集气体的装置，与句意相合。"}, {"text": "放大镜", "is_correct": false, "explanation": "语义：放大镜用来放大物体，不用来收集气体，也不连接细管。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴是乐器，与实验室里收集气体的装置无关。"}, {"text": "台灯", "is_correct": false, "explanation": "搭配：“气体”后不能接“台灯”这类照明用具。"}], "explanations": {"收集器": "“气体收集器”是连接细管收集气体的装置，与句意相合。", "放大镜": "语义：放大镜用来放大物体，不用来收集气体，也不连接细管。", "钢琴": "语义：钢琴是乐器，与实验室里收集气体的装置无关。", "台灯": "搭配：“气体”后不能接“台灯”这类照明用具。"}, "sentence_index": 6, "correct_answer": "收集器"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台收集器能把衣服洗干净。", "explanation": "这里应该用〈洗衣机〉。收集器用来收集或存放物品，不能洗衣服，洗衣服要用洗衣机。"}, {"text": "这个收集器每天早上七点响。", "explanation": "这里应该用〈闹钟〉。收集器只是装置或容器，不会响，定时响铃的要用闹钟。"}, {"text": "这个收集器能控制灯。", "explanation": "这里应该用〈开关〉。收集器不能控制电路，控制灯的要用开关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dff0ae95-8d23-42c5-a1f9-dc49589f7ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13776, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "院子里放着一位雨水收集器。", "corrected_sentence": "院子里放着一个雨水收集器。", "error_description": "量词错误：“位”只用于人（表示尊敬），“收集器”是装置，应用“个”。正确说法：院子里放着一个雨水收集器。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dff0ae95-8d23-42c5-a1f9-dc49589f7ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13776, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "哥哥买了一个新的收集器的。", "corrected_sentence": "哥哥买了一个新的收集器。", "error_description": "结构助词误用：名词短语末尾不能再加“的”，“收集器的”不成句，应删去句末的“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dff0ae95-8d23-42c5-a1f9-dc49589f7ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
