INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13778, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dff0ae95-8d23-42c5-a1f9-dc49589f7ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13778, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "压电是指某些材料在受到外力作用发生形变时，其内部会产生电极化现象，从而在材料两端产生电压的特性。", "primary_collocate": null, "pronunciation": "yā diàn", "ipa": "ja˥ tjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "未来能源图景或将超越“发电”本身——建筑幕墙成为透明太阳能收集器，道路涂层集成压电发电单元，甚至人工光合作用系统直接将二氧化碳转化为燃料。", "target_word": "压电", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "压电是指受压时产生电的现象。", "target_word": "压电", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "石英有压电的特性。", "target_word": "压电", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "压电材料受压时会产生电。", "target_word": "压电", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "利用压电的原理，我们走路时也能发电。", "target_word": "压电", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个打火机是靠压电点火的。", "target_word": "压电", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地板里装了压电材料，人走过就能发电。", "target_word": "压电", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "压电的原理是压力会变成电压。", "target_word": "压电", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "压电技术可以让街上的地砖发电。", "target_word": "压电", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "压电传感器能把压力变成电信号。", "target_word": "压电", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "壓電", "label": "繁体"}, {"form": "压电材料", "label": "复合"}, {"form": "压电效应", "label": "复合"}], "register": "科技", "sense_fingerprint": "压电：某些材料受力形变时产生电压的物理特性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33b2cc55-a89d-45a8-b3eb-d0c547cd39fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13778, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "压电", "is_correct": true, "explanation": "压电是受压时产生电的特性，“压电发电单元”指利用这一特性发电的装置，与句意相符。"}, {"text": "光合作用", "is_correct": false, "explanation": "语义：光合作用是植物的生理过程，不是可以集成到道路上的发电装置，句中已另有“人工光合作用系统”。"}, {"text": "二氧化碳", "is_correct": false, "explanation": "语义：二氧化碳是气体，不能作为发电单元的类别，且句末说它被转化为燃料，与发电装置不符。"}, {"text": "数据", "is_correct": false, "explanation": "搭配：“发电单元”前应接能源或装置类词语，“数据发电单元”搭配不当。"}], "explanations": {"压电": "压电是受压时产生电的特性，“压电发电单元”指利用这一特性发电的装置，与句意相符。", "光合作用": "语义：光合作用是植物的生理过程，不是可以集成到道路上的发电装置，句中已另有“人工光合作用系统”。", "二氧化碳": "语义：二氧化碳是气体，不能作为发电单元的类别，且句末说它被转化为燃料，与发电装置不符。", "数据": "搭配：“发电单元”前应接能源或装置类词语，“数据发电单元”搭配不当。"}, "sentence_index": 0, "correct_answer": "压电"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "导体在磁场里运动时产生电流，这叫压电。", "explanation": "这里应该用〈电磁感应〉。导体在磁场中运动产生电流叫电磁感应；压电指材料受压时产生电压的现象。"}, {"text": "压电材料在磁场里转动时会产生电流。", "explanation": "这里应该用〈电磁感应〉。导体在磁场中运动时产生电流叫电磁感应；压电指受压时产生电的现象，不能用来指这种发电。"}, {"text": "这个弹簧承受的压电很大。", "explanation": "这里应该用〈压力〉。压电指受压时产生电的现象，弹簧承受的力要用压力，不能说压电。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dff0ae95-8d23-42c5-a1f9-dc49589f7ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13778, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "压电", "is_correct": true, "explanation": "压电材料受压时会产生电，与“人走过就能发电”相符。"}, {"text": "石膏", "is_correct": false, "explanation": "语义：石膏不会因受压而产生电，“人走过就能发电”与之矛盾。"}, {"text": "木头", "is_correct": false, "explanation": "语义：木头不具备受压发电的特性，与后半句“就能发电”矛盾。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“装了”后接“空气材料”搭配不当，空气不能装进地板。"}], "explanations": {"压电": "压电材料受压时会产生电，与“人走过就能发电”相符。", "石膏": "语义：石膏不会因受压而产生电，“人走过就能发电”与之矛盾。", "木头": "语义：木头不具备受压发电的特性，与后半句“就能发电”矛盾。", "空气": "搭配：“装了”后接“空气材料”搭配不当，空气不能装进地板。"}, "sentence_index": 6, "correct_answer": "压电"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "冬天脱毛衣时会产生压电。", "explanation": "这里应该用〈静电〉。脱毛衣时产生的电来自摩擦，叫静电；压电指受压时产生电的现象，不能用来指这种电。"}, {"text": "压电能储存电荷。", "explanation": "这里应该用〈电容〉。电容是能储存电荷的元件；压电指受压时产生电的现象，不能用来指储存电荷的元件。"}, {"text": "压电是磁场变化时产生电流的现象。", "explanation": "这里应该用〈电磁感应〉。磁场变化产生电流叫电磁感应；压电指受压时产生电的现象，两者不能互换。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dff0ae95-8d23-42c5-a1f9-dc49589f7ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13778, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这款鞋底用了很压电材料，走路时能发电。", "corrected_sentence": "这款鞋底用了压电材料，走路时能发电。", "error_description": "副词误用：“压电材料”中的“压电”是名词性修饰语，前面不能加“很”，应删去“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dff0ae95-8d23-42c5-a1f9-dc49589f7ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13778, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只压电材料可以把踩踏的力变成电。", "corrected_sentence": "这块压电材料可以把踩踏的力变成电。", "error_description": "材料的量词应为“块”“片”等，“只”用于动物或成对物件中的一个，用在“材料”上不对，应为“这块压电材料”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dff0ae95-8d23-42c5-a1f9-dc49589f7ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13779, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "天然", "is_correct": true, "explanation": "天然：与“人工”（人造的）相反，指自然形成的"}, {"text": "漂亮", "is_correct": false, "explanation": "漂亮：与“人工”没有反义关系"}, {"text": "巨大", "is_correct": false, "explanation": "巨大：与“人工”没有反义关系"}, {"text": "轻松", "is_correct": false, "explanation": "轻松：与“人工”没有反义关系"}], "correct_answer": "天然", "explanations": {"天然": "天然：与“人工”（人造的）相反，指自然形成的", "漂亮": "漂亮：与“人工”没有反义关系", "巨大": "巨大：与“人工”没有反义关系", "轻松": "轻松：与“人工”没有反义关系"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004127e3-e087-4eef-b3a0-2697a32aa1c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13779, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "野生", "is_correct": true, "explanation": "野生：与“人工”（人工种养）相对，指自然生长的"}, {"text": "清楚", "is_correct": false, "explanation": "清楚：与“人工”没有反义关系"}, {"text": "明亮", "is_correct": false, "explanation": "明亮：与“人工”没有反义关系"}, {"text": "轻快", "is_correct": false, "explanation": "轻快：与“人工”没有反义关系"}], "correct_answer": "野生", "explanations": {"野生": "野生：与“人工”（人工种养）相对，指自然生长的", "清楚": "清楚：与“人工”没有反义关系", "明亮": "明亮：与“人工”没有反义关系", "轻快": "轻快：与“人工”没有反义关系"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004127e3-e087-4eef-b3a0-2697a32aa1c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13779, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "由人制造或进行的，与自然相对。", "primary_collocate": null, "pronunciation": "rén gōng", "ipa": "ʐən³⁵ kʊŋ⁵⁵", "syllable_count": 2, "sentences": [{"text": "未来能源图景或将超越“发电”本身——建筑幕墙成为透明太阳能收集器，道路涂层集成压电发电单元，甚至人工光合作用系统直接将二氧化碳转化为燃料。", "target_word": "人工", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "公园里的小河是人工的。", "target_word": "人工", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条河是人工开的，不是天然河。", "target_word": "人工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些花是人工种的，不是野花。", "target_word": "人工", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种药是人工合成的，不是从植物里提取的。", "target_word": "人工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种珍珠是人工养的。", "target_word": "人工", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "沙滩上的石头是人工放的。", "target_word": "人工", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "滑雪场的雪是人工做的。", "target_word": "人工", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山里的洞是人工打的。", "target_word": "人工", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个岛是人工做的，不是天然的。", "target_word": "人工", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "人工湖", "label": "复合"}, {"form": "人工智能", "label": "复合"}], "register": "中性", "sense_fingerprint": "由人制造或进行的，不是天然的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '346c9218-cb43-4e91-8a90-710077c45e12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13779, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人工", "is_correct": true, "explanation": "人工：人造的，修饰“光合作用系统”，符合句意"}, {"text": "情绪", "is_correct": false, "explanation": "语义：“情绪”与“光合作用系统”无关，句意荒唐"}, {"text": "金属", "is_correct": false, "explanation": "语义：“金属”不能修饰光合作用系统，句意不通"}, {"text": "免费", "is_correct": false, "explanation": "搭配：“免费”修饰服务或商品，不能修饰“光合作用系统”"}], "explanations": {"人工": "人工：人造的，修饰“光合作用系统”，符合句意", "情绪": "语义：“情绪”与“光合作用系统”无关，句意荒唐", "金属": "语义：“金属”不能修饰光合作用系统，句意不通", "免费": "搭配：“免费”修饰服务或商品，不能修饰“光合作用系统”"}, "sentence_index": 0, "correct_answer": "人工"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座大山是人工形成的，是几亿年地壳运动的结果。", "explanation": "这里应该用〈天然〉。“人工”指人造的，大山是地壳运动自然形成的，不能说“人工形成”"}, {"text": "这块石头是人工的，它是几亿年前从火山里喷出来的。", "explanation": "这里应该用〈天然〉。石头由火山喷发形成，属于天然物，不能说“人工的”"}, {"text": "这片树林是人工种的，是几万年前就有的原始森林。", "explanation": "这里应该用〈天然〉。原始森林是自然生长的，不能说“人工种的”"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004127e3-e087-4eef-b3a0-2697a32aa1c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13779, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人工", "is_correct": true, "explanation": "人工：人造的，符合“沙滩上的石头是……放的”的语境"}, {"text": "老虎", "is_correct": false, "explanation": "语义：老虎不能把石头放在沙滩上，句意荒唐"}, {"text": "梦", "is_correct": false, "explanation": "语义：“梦”不能施行“放”的动作，句意荒唐"}, {"text": "电视", "is_correct": false, "explanation": "搭配：“电视”不能施行“放”的动作，搭配不当"}], "explanations": {"人工": "人工：人造的，符合“沙滩上的石头是……放的”的语境", "老虎": "语义：老虎不能把石头放在沙滩上，句意荒唐", "梦": "语义：“梦”不能施行“放”的动作，句意荒唐", "电视": "搭配：“电视”不能施行“放”的动作，搭配不当"}, "sentence_index": 6, "correct_answer": "人工"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这束阳光是人工的，它是太阳直接照下来的。", "explanation": "这里应该用〈天然〉。阳光来自太阳，是天然的，不是人造的"}, {"text": "这场暴风雨是人工的，是老天自己刮起来的。", "explanation": "这里应该用〈天然〉。暴风雨是天气现象，是天然形成的，不能说“人工的”"}, {"text": "这个温泉是人工的，水是从地下自己冒出来的。", "explanation": "这里应该用〈天然〉。从地下自己冒出来的温泉是天然的，不是人造的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004127e3-e087-4eef-b3a0-2697a32aa1c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13779, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个湖是人工挖。", "corrected_sentence": "这个湖是人工挖的。", "error_description": "错误：漏了“的”。“是……的”句式的结尾要用“的”，应说“这个湖是人工挖的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004127e3-e087-4eef-b3a0-2697a32aa1c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13779, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些树苗是不人工培育的。", "corrected_sentence": "这些树苗不是人工培育的。", "error_description": "错误：否定词位置不对。“不”应放在“是”前，说“不是人工培育的”，不说“是不人工培育的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004127e3-e087-4eef-b3a0-2697a32aa1c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
