INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13781, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "表示最终、最后阶段，没有比这更后面的了。", "primary_collocate": null, "pronunciation": "zhōng jí", "ipa": "ʈʂʊŋ˥ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "这些前沿探索预示着：清洁能源的终极形态，或是将整个建成环境转化为无感而持续的能量代谢网络。", "target_word": "终极", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他的终极目标是当一名医生。", "target_word": "终极", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这场比赛的终极大奖是一辆汽车。", "target_word": "终极", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个游戏有一个终极挑战。", "target_word": "终极", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家想找到宇宙的终极答案。", "target_word": "终极", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的终极梦想是环游世界。", "target_word": "终极", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是一次终极考验，大家都很紧张。", "target_word": "终极", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们学习的终极目的是用好它。", "target_word": "终极", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哲学家一直在想人生的终极问题。", "target_word": "终极", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司的终极目标没有变过。", "target_word": "终极", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "终极·形容词·最终的、最后阶段的(终极目标)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bc74ad3-fce1-4a1c-a4e5-5f5ab986044a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13781, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "终极", "is_correct": true, "explanation": "终极 zhōngjí：表示最后、最终，是正确答案。"}, {"text": "中继", "is_correct": false, "explanation": "zhōngjì 与 zhōngjí 的末字声调不同（第四声与第二声），意思是中继（中间转接）。"}, {"text": "终局", "is_correct": false, "explanation": "zhōngjú 与 zhōngjí 的韵母不同（ü 与 i），意思是终局（最后的结局）。"}, {"text": "终结", "is_correct": false, "explanation": "zhōngjié 与 zhōngjí 的韵母不同（ie 与 i），意思是终结（结束）。"}, {"text": "中计", "is_correct": false, "explanation": "zhòngjì 与 zhōngjí 的两个音节声调都不同，意思是中计（上当）。"}], "explanations": {"终极": "终极 zhōngjí：表示最后、最终，是正确答案。", "中继": "zhōngjì 与 zhōngjí 的末字声调不同（第四声与第二声），意思是中继（中间转接）。", "终局": "zhōngjú 与 zhōngjí 的韵母不同（ü 与 i），意思是终局（最后的结局）。", "终结": "zhōngjié 与 zhōngjí 的韵母不同（ie 与 i），意思是终结（结束）。", "中计": "zhòngjì 与 zhōngjí 的两个音节声调都不同，意思是中计（上当）。"}, "sentence_index": null, "correct_answer": "终极"}, "level_3": {"options": [{"text": "终极", "is_correct": true, "explanation": "终极：修饰“形态”，表示最终状态，符合句意。"}, {"text": "沉重", "is_correct": false, "explanation": "语义：清洁能源的形态不能用“沉重”来形容，与句意不合。"}, {"text": "嘈杂", "is_correct": false, "explanation": "语义：“嘈杂”形容声音杂乱，不能修饰清洁能源的形态。"}, {"text": "潮湿", "is_correct": false, "explanation": "搭配：“潮湿”形容物体含水多，不能修饰清洁能源的形态。"}], "explanations": {"终极": "终极：修饰“形态”，表示最终状态，符合句意。", "沉重": "语义：清洁能源的形态不能用“沉重”来形容，与句意不合。", "嘈杂": "语义：“嘈杂”形容声音杂乱，不能修饰清洁能源的形态。", "潮湿": "搭配：“潮湿”形容物体含水多，不能修饰清洁能源的形态。"}, "sentence_index": 0, "correct_answer": "终极"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次实验的终极数据是第一批测出来的。", "explanation": "这里应该用〈最初〉。终极表示最后阶段，与“第一批”的先后次序矛盾；先测出的数据要说〈最初〉。"}, {"text": "我这学期的终极一门考试在星期五。", "explanation": "这里应该用〈最后〉。终极指事物发展到尽头、不能再有后续，不用于“一门考试”这类按次序排列的计量。"}, {"text": "这是我们终极的第一课。", "explanation": "这里应该用〈入门〉。终极表示最后阶段，与“第一课”的先后次序矛盾；第一课要说〈入门〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740a8dd6-612a-4984-b445-3f0ac1250d8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13781, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "终极", "is_correct": true, "explanation": "终极：修饰“考验”，表示最后、最难的一关，符合句意。"}, {"text": "轻松", "is_correct": false, "explanation": "语义：“轻松”与后句“大家都很紧张”的意思矛盾。"}, {"text": "潮湿", "is_correct": false, "explanation": "搭配：“潮湿”形容物体含水多，不能修饰“考验”，句子不成立。"}, {"text": "无关", "is_correct": false, "explanation": "搭配：“无关”表示不相干，不能修饰“考验”，句子不成立。"}], "explanations": {"终极": "终极：修饰“考验”，表示最后、最难的一关，符合句意。", "轻松": "语义：“轻松”与后句“大家都很紧张”的意思矛盾。", "潮湿": "搭配：“潮湿”形容物体含水多，不能修饰“考验”，句子不成立。", "无关": "搭配：“无关”表示不相干，不能修饰“考验”，句子不成立。"}, "sentence_index": 6, "correct_answer": "终极"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他迈出了终极的第一步。", "explanation": "这里应该用〈最初〉。终极表示最后阶段，与“第一步”的先后次序矛盾；最开始的一步要说〈最初〉。"}, {"text": "我们在终极的开头就讨论了这个问题。", "explanation": "这里应该用〈开始〉。终极表示最后阶段，不能修饰“开头”这类表示起始的名词；事情的起始要说〈开始〉。"}, {"text": "这是他终极的第一次登台。", "explanation": "这里应该用〈首次〉。终极表示最后阶段，与“第一次”的先后次序矛盾；第一次登台要说〈首次〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740a8dd6-612a-4984-b445-3f0ac1250d8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13781, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一项终极得挑战。", "corrected_sentence": "这是一项终极的挑战。", "error_description": "错误：“得”用于补语，不能连接定语与中心语；“终极”修饰“挑战”时应用“的”。正确：“这是一项终极的挑战。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740a8dd6-612a-4984-b445-3f0ac1250d8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13781, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们讨论的是问题的终极了原因。", "corrected_sentence": "我们讨论的是问题的终极原因。", "error_description": "错误在于“了”：终极作定语修饰名词，后面不能加“了”表示完成。应去掉“了”，说“终极原因”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740a8dd6-612a-4984-b445-3f0ac1250d8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
