INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13782, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指完成建造，例如房子、桥梁等建筑物或设施已经完工。", "primary_collocate": null, "pronunciation": "jiàn chéng", "ipa": "tɕjɛn˥˩ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这座大桥将于明年建成通车。", "target_word": "建成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座桥去年已经建成了。", "target_word": "建成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新学校明年夏天就能建成。", "target_word": "建成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条高速公路用了三年才建成。", "target_word": "建成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座塔建成以后，成了城市的标志。", "target_word": "建成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山上的小房子终于建成了。", "target_word": "建成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "体育馆还没有建成，比赛要等一等。", "target_word": "建成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个公园建成后，很多人来玩。", "target_word": "建成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里的图书馆是十年前建成的。", "target_word": "建成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一座新机场在海边建成了。", "target_word": "建成", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "建成了", "label": "完成体"}], "register": "书面", "sense_fingerprint": "建成·动词·建筑物或设施完工", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bc74ad3-fce1-4a1c-a4e5-5f5ab986044a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13782, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "建成", "is_correct": true, "explanation": "建成 jiàn chéng：指建筑物或设施完工，是正确答案。"}, {"text": "坚称", "is_correct": false, "explanation": "jiānchēng 与 jiànchéng 两个字的声调都不同（第一声对第四声，第一声对第二声），意思是坚决地说。"}, {"text": "简称", "is_correct": false, "explanation": "jiǎnchēng 与 jiànchéng 两个字的声调都不同（第三声对第四声，第一声对第二声），意思是简略的名称。"}, {"text": "现成", "is_correct": false, "explanation": "xiànchéng 与 jiànchéng 的声母不同（x 与 j），意思是现成（现有的、不用加工的）。"}], "explanations": {"建成": "建成 jiàn chéng：指建筑物或设施完工，是正确答案。", "坚称": "jiānchēng 与 jiànchéng 两个字的声调都不同（第一声对第四声，第一声对第二声），意思是坚决地说。", "简称": "jiǎnchēng 与 jiànchéng 两个字的声调都不同（第三声对第四声，第一声对第二声），意思是简略的名称。", "现成": "xiànchéng 与 jiànchéng 的声母不同（x 与 j），意思是现成（现有的、不用加工的）。"}, "sentence_index": null, "correct_answer": "建成"}, "level_3": {"options": [{"text": "建成", "is_correct": true, "explanation": "建成：大桥完工后才能通车，符合句意。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：大桥拆除后就不能“通车”，前后矛盾。"}, {"text": "设计", "is_correct": false, "explanation": "语义：只是设计好的桥还不能“通车”。"}, {"text": "关闭", "is_correct": false, "explanation": "语义：“关闭”与“通车”意思相反，不能连用。"}], "explanations": {"建成": "建成：大桥完工后才能通车，符合句意。", "拆除": "语义：大桥拆除后就不能“通车”，前后矛盾。", "设计": "语义：只是设计好的桥还不能“通车”。", "关闭": "语义：“关闭”与“通车”意思相反，不能连用。"}, "sentence_index": 0, "correct_answer": "建成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用了三年才建成这部书。", "explanation": "这里应该用〈完成〉。建成只用于房屋、桥梁、设施等建筑物，不用于书。"}, {"text": "这台电脑终于建成了。", "explanation": "这里应该用〈修好〉。建成指建筑物或设施完工，电脑是修好的，不说建成。"}, {"text": "他终于建成了一个好习惯。", "explanation": "这里应该用〈养成〉。建成用于建筑物或设施的完工，不用于习惯；习惯要说〈养成〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740a8dd6-612a-4984-b445-3f0ac1250d8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13782, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "建成", "is_correct": true, "explanation": "建成：指体育馆完工，与“比赛要等一等”的语境相符。"}, {"text": "开学", "is_correct": false, "explanation": "搭配：“开学”只用于学校，不用于体育馆。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：“毕业”用于学生，体育馆不能毕业。"}, {"text": "倒塌", "is_correct": false, "explanation": "语义：体育馆“倒塌”与“比赛要等一等”的因果关系不通。"}], "explanations": {"建成": "建成：指体育馆完工，与“比赛要等一等”的语境相符。", "开学": "搭配：“开学”只用于学校，不用于体育馆。", "毕业": "语义：“毕业”用于学生，体育馆不能毕业。", "倒塌": "语义：体育馆“倒塌”与“比赛要等一等”的因果关系不通。"}, "sentence_index": 6, "correct_answer": "建成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台空调终于建成了。", "explanation": "这里应该用〈装好〉。建成用于建筑物或设施，空调是安装好的，不说建成。"}, {"text": "他终于建成了那篇论文。", "explanation": "这里应该用〈写完〉。建成不用于文章，写完论文要说〈写完〉。"}, {"text": "这辆车是去年建成的。", "explanation": "这里应该用〈造好〉。建成指建筑物或设施完工，车辆是制造出来的，不说建成。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740a8dd6-612a-4984-b445-3f0ac1250d8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13782, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座新馆下个月就建成着。", "corrected_sentence": "这座新馆下个月就建成了。", "error_description": "错误在于动态助词：表示“建成”这一完工结果要用“了”，用“着”表示持续状态，与句意不符。应把“着”改为“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740a8dd6-612a-4984-b445-3f0ac1250d8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13782, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这栋楼明年才会建成了。", "corrected_sentence": "这栋楼明年才会建成。", "error_description": "错误在于多加了“了”：“明年”指将来，“才会”表示尚未发生，“建成”的完成不能用“了”表示。应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740a8dd6-612a-4984-b445-3f0ac1250d8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13783, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b8024f-b22b-4953-93e5-eab38a007145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13783, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b8024f-b22b-4953-93e5-eab38a007145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13783, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指没有感觉或不在意，对某事物不产生情绪或身体上的反应。", "primary_collocate": null, "pronunciation": "wú gǎn", "ipa": "u˧˥ kan˨˩˦", "syllable_count": 2, "sentences": [{"text": "他对周围的一切都无感，好像什么也没听见。", "target_word": "无感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对这部电影很无感，看到一半就睡着了。", "target_word": "无感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们都爱吃辣，可我对辣味无感。", "target_word": "无感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对流行音乐一直很无感。", "target_word": "无感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听了半天，我对这个笑话完全无感。", "target_word": "无感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在的年轻人对广告越来越无感了。", "target_word": "无感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对名牌包包无感，从来不买。", "target_word": "无感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对于别人的评价，他似乎无感。", "target_word": "无感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场比赛太无聊，我看着也无感。", "target_word": "无感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师讲了很多遍，学生们还是无感。", "target_word": "无感", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "对事物没有感觉、不在意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '851baa46-0c4d-405d-9c2e-d5933994bbc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13783, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "无感", "is_correct": true, "explanation": "正确：wú gǎn，意思是没有感觉或不在意。"}, {"text": "五感", "is_correct": false, "explanation": "wǔ gǎn（第三声）与 wú gǎn（第二声）声调不同，意思是五种感觉。"}, {"text": "舞感", "is_correct": false, "explanation": "wǔ gǎn（第三声）与 wú gǎn（第二声）声调不同，意思是跳舞的感觉。"}, {"text": "无干", "is_correct": false, "explanation": "gān（第一声）与 gǎn（第三声）声调不同，意思是没有关系。"}], "explanations": {"无感": "正确：wú gǎn，意思是没有感觉或不在意。", "五感": "wǔ gǎn（第三声）与 wú gǎn（第二声）声调不同，意思是五种感觉。", "舞感": "wǔ gǎn（第三声）与 wú gǎn（第二声）声调不同，意思是跳舞的感觉。", "无干": "gān（第一声）与 gǎn（第三声）声调不同，意思是没有关系。"}, "sentence_index": null, "correct_answer": "无感"}, "level_3": {"options": [{"text": "无感", "is_correct": true, "explanation": "正确：对周围的一切都没有反应，正合“好像什么也没听见”的意思。"}, {"text": "显眼", "is_correct": false, "explanation": "语义：“显眼”指引人注意，与“什么也没听见”的麻木状态相反。"}, {"text": "喧闹", "is_correct": false, "explanation": "搭配：“喧闹”形容声音或场面，不用来形容人对周围一切的态度。"}, {"text": "笨重", "is_correct": false, "explanation": "语义：“笨重”形容体积或动作，与人的感受无关，“对一切都笨重”说不通。"}], "explanations": {"无感": "正确：对周围的一切都没有反应，正合“好像什么也没听见”的意思。", "显眼": "语义：“显眼”指引人注意，与“什么也没听见”的麻木状态相反。", "喧闹": "搭配：“喧闹”形容声音或场面，不用来形容人对周围一切的态度。", "笨重": "语义：“笨重”形容体积或动作，与人的感受无关，“对一切都笨重”说不通。"}, "sentence_index": 0, "correct_answer": "无感"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我被他的故事感动得哭了起来，对此完全无感。", "explanation": "这里应该用〈非常感动〉。无感表示没有情绪反应，与“感动得哭了起来”矛盾。"}, {"text": "比赛获胜后，我激动得跳了起来，对此完全无感。", "explanation": "这里应该用〈非常激动〉。无感表示没有情绪反应，与“激动得跳了起来”矛盾。"}, {"text": "他对身边的朋友很无感，每天都热情地关心大家。", "explanation": "这里应该用〈在意〉。无感表示不在意，与“每天都热情地关心大家”矛盾，应该用“在意”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b8024f-b22b-4953-93e5-eab38a007145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13783, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无感", "is_correct": true, "explanation": "正确：对名牌包包没有兴趣，与“从来不买”前后一致。"}, {"text": "狂热", "is_correct": false, "explanation": "语义：狂热的人往往想买，与“从来不买”相矛盾。"}, {"text": "痴迷", "is_correct": false, "explanation": "语义：痴迷多指一心想拥有，与“从来不买”前后矛盾。"}, {"text": "热切", "is_correct": false, "explanation": "搭配：“热切”多用于期盼、眼神，不说“对包包热切”。"}], "explanations": {"无感": "正确：对名牌包包没有兴趣，与“从来不买”前后一致。", "狂热": "语义：狂热的人往往想买，与“从来不买”相矛盾。", "痴迷": "语义：痴迷多指一心想拥有，与“从来不买”前后矛盾。", "热切": "搭配：“热切”多用于期盼、眼神，不说“对包包热切”。"}, "sentence_index": 6, "correct_answer": "无感"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "每次见到妈妈，我都很无感，一头扑进她怀里撒娇。", "explanation": "这里应该用〈开心〉。无感表示没有反应，与“一头扑进她怀里撒娇”的亲昵反应矛盾。"}, {"text": "得知考试通过，他高兴得大笑起来，对此很无感。", "explanation": "这里应该用〈很高兴〉。无感表示没有情绪反应，与“高兴得大笑起来”矛盾。"}, {"text": "这场演唱会我全程都很无感，一直跟着歌声尖叫。", "explanation": "这里应该用〈投入〉。无感表示不在意，与“一直跟着歌声尖叫”矛盾，应该用“投入”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b8024f-b22b-4953-93e5-eab38a007145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13783, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我跟这场比赛一直很无感，没看进去。", "corrected_sentence": "我对这场比赛一直很无感，没看进去。", "error_description": "介词用错：“无感”的对象要用介词“对”，不能说“跟这场比赛”，应说“对这场比赛一直很无感”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b8024f-b22b-4953-93e5-eab38a007145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13783, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈对手机游戏很完全无感，从来不玩。", "corrected_sentence": "妈妈对手机游戏完全无感，从来不玩。", "error_description": "副词叠用：“很”和“完全”都修饰“无感”，不能同时使用，应说“对手机游戏完全无感”，去掉“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b8024f-b22b-4953-93e5-eab38a007145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
