INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13787, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通过飞行到达某处。", "primary_collocate": null, "pronunciation": "fēi dào", "ipa": "fei˥ tau˥˩", "syllable_count": 2, "sentences": [{"text": "当它飞到另一朵花时，花粉会掉下来。", "target_word": "飞到", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "小鸟飞到树上，唱起歌来。", "target_word": "飞到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蝴蝶飞到我的手上了。", "target_word": "飞到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机飞到北京要两个小时。", "target_word": "飞到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "燕子每年冬天都飞到南方去。", "target_word": "飞到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一只蜜蜂飞到了窗台上。", "target_word": "飞到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看着气球飞到了天上。", "target_word": "飞到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟飞到哪里去了？", "target_word": "飞到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天，大雁会飞到很远的地方过冬。", "target_word": "飞到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只蝴蝶飞到花园里，停在一朵红花上。", "target_word": "飞到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "飞到了", "label": "体标"}, {"form": "飞不到", "label": "可能补语"}], "register": "中性", "sense_fingerprint": "通过飞行到达某处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dab0c558-bacf-42b5-ac45-3bf523f0ba2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13787, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "飞到", "is_correct": true, "explanation": "“飞到”表示飞行到达另一朵花，与“当它…时”的移动语境一致。"}, {"text": "飞起", "is_correct": false, "explanation": "搭配：“飞起”后不能直接带处所宾语“另一朵花”，要说“飞起来”。"}, {"text": "飞走", "is_correct": false, "explanation": "语义：“飞走”表示离开，与“飞到另一朵花”的方向相反。"}, {"text": "飞着", "is_correct": false, "explanation": "语义：“飞着”只表示飞行的状态，没有到达另一朵花的意思。"}], "explanations": {"飞到": "“飞到”表示飞行到达另一朵花，与“当它…时”的移动语境一致。", "飞起": "搭配：“飞起”后不能直接带处所宾语“另一朵花”，要说“飞起来”。", "飞走": "语义：“飞走”表示离开，与“飞到另一朵花”的方向相反。", "飞着": "语义：“飞着”只表示飞行的状态，没有到达另一朵花的意思。"}, "sentence_index": 0, "correct_answer": "飞到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把车飞到了停车场。", "explanation": "这里应该用〈开〉。车不能飞，把车开到某处应说“开到”，“飞到”只用于凭借飞行到达某处的东西。"}, {"text": "这条路飞到了山顶。", "explanation": "这里应该用〈通到〉。路不会飞，延伸到某处应说“通到”。"}, {"text": "他们把家飞到了城市。", "explanation": "这里应该用〈搬到〉。家不能飞，迁居应说“搬到”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2324f598-67e9-4228-9439-eb703c9aa929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13787, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "飞到", "is_correct": true, "explanation": "“看着气球飞到了天上”，表示气球飞行到达天上，符合句意。"}, {"text": "飞下", "is_correct": false, "explanation": "语义：“下”指向下的方向，与“天上”的向上方位相反。"}, {"text": "飞起", "is_correct": false, "explanation": "搭配：“飞起”后不能直接带“天上”作处所宾语，需说“飞起来”。"}, {"text": "落下", "is_correct": false, "explanation": "语义：“落下”指降落，与气球上升到天上的方向相反。"}], "explanations": {"飞到": "“看着气球飞到了天上”，表示气球飞行到达天上，符合句意。", "飞下": "语义：“下”指向下的方向，与“天上”的向上方位相反。", "飞起": "搭配：“飞起”后不能直接带“天上”作处所宾语，需说“飞起来”。", "落下": "语义：“落下”指降落，与气球上升到天上的方向相反。"}, "sentence_index": 6, "correct_answer": "飞到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条河飞到了大海里。", "explanation": "这里应该用〈流入〉。河不会飞，流入某处应说“流入”。"}, {"text": "这家超市飞到了郊区。", "explanation": "这里应该用〈搬到〉。超市不会飞，整体迁到某处应说“搬到”。"}, {"text": "这袋垃圾要飞到楼下去。", "explanation": "这里应该用〈扔到〉。垃圾是被人扔出去的，不会自己飞，“飞到”不能表示人把东西抛出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2324f598-67e9-4228-9439-eb703c9aa929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13787, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "蜜蜂很快就飞到到了花上。", "corrected_sentence": "蜜蜂很快就飞到了花上。", "error_description": "错误：“飞到”的“到”已是结果补语，不能再加一个“到”，应说“飞到了花上”，不能说“飞到到了花上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2324f598-67e9-4228-9439-eb703c9aa929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13787, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小鸟飞到了了窗台上。", "corrected_sentence": "小鸟飞到了窗台上。", "error_description": "错误：“了”只需说一次，“飞到了”已带完成标记，不能重复成“飞到了了”，应说“飞到了窗台上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2324f598-67e9-4228-9439-eb703c9aa929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
