INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13790, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在某单位或岗位上从事工作。", "primary_collocate": null, "pronunciation": "zuò shì", "ipa": "tswo˥˩ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他在银行做事，已经五年了。", "target_word": "做事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在一家公司做事，工资不高。", "target_word": "做事", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你在哪儿做事？离家远不远？", "target_word": "做事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在公司做事，老板很满意。", "target_word": "做事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我哥哥在一家公司做事。", "target_word": "做事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他刚毕业，想先找个地方做事。", "target_word": "做事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在报社做事，每天都很忙。", "target_word": "做事", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她在医院做事，大家都认识她。", "target_word": "做事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸为了养家，每天辛苦做事。", "target_word": "做事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在工厂做事，每月按时拿工资。", "target_word": "做事", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "做了事", "label": "体标（了）"}, {"form": "做过事", "label": "体标（过）"}], "register": "口语", "sense_fingerprint": "做事：在某单位或岗位上工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '344206f6-976f-4874-8f0d-c04e78e16151') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13790, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "做事", "is_correct": true, "explanation": "正确。做事在此指在某处从事工作。"}, {"text": "错事", "is_correct": false, "explanation": "cuò（第四声）与 zuò 声母不同（c 与 z），意思是做错的事。"}, {"text": "作诗", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，意思是写诗。"}, {"text": "坐实", "is_correct": false, "explanation": "shí（第二声）与 shì 声调不同，意思是证实、确定。"}], "explanations": {"做事": "正确。做事在此指在某处从事工作。", "错事": "cuò（第四声）与 zuò 声母不同（c 与 z），意思是做错的事。", "作诗": "shī（第一声）与 shì（第四声）声调不同，意思是写诗。", "坐实": "shí（第二声）与 shì 声调不同，意思是证实、确定。"}, "sentence_index": null, "correct_answer": "做事"}, "level_3": {"options": [{"text": "做事", "is_correct": true, "explanation": "正确。“在银行做事”指在银行工作，与“已经五年了”相符。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：在银行游泳不合常理，与工作语境不符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：在银行睡觉不是工作，与“在银行”的语境矛盾。"}, {"text": "跑步", "is_correct": false, "explanation": "搭配：“在……”后接地点时，多接工作或办事的动词，“在银行跑步”搭配不当。"}], "explanations": {"做事": "正确。“在银行做事”指在银行工作，与“已经五年了”相符。", "游泳": "语义：在银行游泳不合常理，与工作语境不符。", "睡觉": "语义：在银行睡觉不是工作，与“在银行”的语境矛盾。", "跑步": "搭配：“在……”后接地点时，多接工作或办事的动词，“在银行跑步”搭配不当。"}, "sentence_index": 0, "correct_answer": "做事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我们去电影院做事，看了一场电影。", "explanation": "这里应该用〈看电影〉。去电影院看电影要说“看电影”，“做事”不指观看。"}, {"text": "周末他去超市做事，买了很多东西。", "explanation": "这里应该用〈购物〉。去超市买东西要说“购物”，“做事”不指购买。"}, {"text": "我去公园做事，拍了一组照片。", "explanation": "这里应该用〈拍照〉。在公园拍照要说“拍照”，“做事”不指拍摄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d6a21e1-dfee-4f95-afc8-4b11b1c0d1a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13790, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "做事", "is_correct": true, "explanation": "正确。“在报社做事”指在报社工作，所以“每天都很忙”。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：报社里不能游泳，句意不通。"}, {"text": "发呆", "is_correct": false, "explanation": "语义：发呆与“每天都很忙”矛盾。"}, {"text": "出生", "is_correct": false, "explanation": "语义：出生不是每天在单位进行的事。"}], "explanations": {"做事": "正确。“在报社做事”指在报社工作，所以“每天都很忙”。", "游泳": "语义：报社里不能游泳，句意不通。", "发呆": "语义：发呆与“每天都很忙”矛盾。", "出生": "语义：出生不是每天在单位进行的事。"}, "sentence_index": 6, "correct_answer": "做事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在厨房做事，做了一桌好菜。", "explanation": "这里应该用〈做饭〉。做菜、做饭要说“做饭”，“做事”不用于烹饪。"}, {"text": "我去药店做事，买了一盒感冒药。", "explanation": "这里应该用〈买药〉。去药店买药要说“买药”，“做事”不指购买。"}, {"text": "我们去河边做事，钓了一条大鱼。", "explanation": "这里应该用〈钓鱼〉。去河边钓鱼要说“钓鱼”，“做事”不指钓鱼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d6a21e1-dfee-4f95-afc8-4b11b1c0d1a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13790, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一直在银行做了事，从没换过工作。", "corrected_sentence": "他一直在银行做事，从没换过工作。", "error_description": "“做事”的“了”位置错误。“一直在……”表示进行中，不能接“了”，应说“一直在银行做事”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d6a21e1-dfee-4f95-afc8-4b11b1c0d1a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13790, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他以前在这家工厂做着三年事。", "corrected_sentence": "他以前在这家工厂做过三年事。", "error_description": "体标误用：说以前的工作经历并带时量“三年”，“做事”中间应插“过”，不能用表示持续的“着”，应说“做过三年事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d6a21e1-dfee-4f95-afc8-4b11b1c0d1a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13792, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "留下", "is_correct": true, "explanation": "正确。“留下”与“带走”相反，指离开时把东西留在原处。"}, {"text": "整理", "is_correct": false, "explanation": "“整理”指把东西收拾得有条理，与“带走”不构成反义关系。"}, {"text": "修补", "is_correct": false, "explanation": "“修补”指修理破损的东西，与“带走”没有反义关系。"}, {"text": "聊天", "is_correct": false, "explanation": "“聊天”指交谈，与“带走”没有反义关系。"}], "correct_answer": "留下", "explanations": {"留下": "正确。“留下”与“带走”相反，指离开时把东西留在原处。", "整理": "“整理”指把东西收拾得有条理，与“带走”不构成反义关系。", "修补": "“修补”指修理破损的东西，与“带走”没有反义关系。", "聊天": "“聊天”指交谈，与“带走”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '499b1f08-7089-4fce-8232-e7e87bcbf736') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
