INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13792, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "携带（某人或某物）一起离开。", "primary_collocate": null, "pronunciation": "dài zǒu", "ipa": "tai̯˥˩ tsou̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "花有粉，蜜蜂带走粉。", "target_word": "带走", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "下课了，请把你的书带走。", "target_word": "带走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明离开时把雨伞带走了。", "target_word": "带走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "离开房间时，别带走别人的东西。", "target_word": "带走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家那天，妈妈带走了她的小狗。", "target_word": "带走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些花很漂亮，你可以带走。", "target_word": "带走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走的时候带走了所有的衣服。", "target_word": "带走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个杯子是公司的，你不能带走。", "target_word": "带走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她出国前想带走一张全家的照片。", "target_word": "带走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟走的时候，把我的帽子也带走了。", "target_word": "带走", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "带走了", "label": "体标（完成）"}, {"form": "带走过", "label": "体标（经历）"}, {"form": "带不走", "label": "可能补语（否定）"}, {"form": "带得走", "label": "可能补语（肯定）"}], "register": "中性", "sense_fingerprint": "离开时随身携带某人或某物一起走", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d698ce0-810b-4db1-bf3a-88dde9784e24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13792, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "制造", "is_correct": false, "explanation": "语义：花粉是花本来就有的，蜜蜂不会制造粉，与“花有粉”矛盾。"}, {"text": "带走", "is_correct": true, "explanation": "正确。“带走”表示把粉随身携带离开，与句子的语境相合。"}, {"text": "挥霍", "is_correct": false, "explanation": "搭配：“挥霍”多接钱财、时间，不接花粉。"}, {"text": "研究", "is_correct": false, "explanation": "语义：“研究”需要人的思考，蜜蜂不做研究，句子语境不合。"}], "explanations": {"制造": "语义：花粉是花本来就有的，蜜蜂不会制造粉，与“花有粉”矛盾。", "带走": "正确。“带走”表示把粉随身携带离开，与句子的语境相合。", "挥霍": "搭配：“挥霍”多接钱财、时间，不接花粉。", "研究": "语义：“研究”需要人的思考，蜜蜂不做研究，句子语境不合。"}, "sentence_index": 0, "correct_answer": "带走"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我从北京给你带走了一件礼物，你看看喜不喜欢。", "explanation": "这里应该用〈带来〉。带走指离开某处时把东西一起拿走，把东西送到对方身边要用带来。"}, {"text": "他把房子带走了。", "explanation": "这里不能用〈带走〉。带走的东西要能随人离开，房子固定不动，不能被带走。"}, {"text": "朋友给我带走了一箱水果，我很高兴。", "explanation": "这里应该用〈送来〉。带走是离开时拿走，把水果送到说话人这里要用送来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '499b1f08-7089-4fce-8232-e7e87bcbf736') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13792, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "迎接", "is_correct": false, "explanation": "语义：“迎接”针对来客，与“所有的衣服”搭配不当，也与“走的时候”的语境矛盾。"}, {"text": "带走", "is_correct": true, "explanation": "正确。“带走”表示离开时把衣服一起拿走，与“走的时候”相合。"}, {"text": "挤压", "is_correct": false, "explanation": "搭配：“挤压”多接物体或空间，不说挤压所有的衣服。"}, {"text": "咬", "is_correct": false, "explanation": "语义：人不会咬下所有衣服，与句子的语境不合。"}], "explanations": {"迎接": "语义：“迎接”针对来客，与“所有的衣服”搭配不当，也与“走的时候”的语境矛盾。", "带走": "正确。“带走”表示离开时把衣服一起拿走，与“走的时候”相合。", "挤压": "搭配：“挤压”多接物体或空间，不说挤压所有的衣服。", "咬": "语义：人不会咬下所有衣服，与句子的语境不合。"}, "sentence_index": 6, "correct_answer": "带走"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈给我带走了一碗汤，我很感动。", "explanation": "这里应该用〈端来〉。带走表示离开时拿走，“给我”的东西是送到说话人身边，要用端来。"}, {"text": "他把这座山带走了。", "explanation": "这里不能用〈带走〉。山太大、固定不动，不能随人离开，不能说带走。"}, {"text": "老师给我带走了一本书，我很高兴。", "explanation": "这里应该用〈拿来〉。带走指离开时拿走，把书交到说话人手里要用拿来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '499b1f08-7089-4fce-8232-e7e87bcbf736') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13792, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "下课以后，我书把带走了。", "corrected_sentence": "下课以后，我把书带走了。", "error_description": "语序错误：“把”字结构中，“把”应放在宾语“书”之前，说“我把书带走了”，不能把“书”放在“把”的前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '499b1f08-7089-4fce-8232-e7e87bcbf736') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13792, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下课以后，我把书带走了过。", "corrected_sentence": "下课以后，我把书带走了。", "error_description": "体标错误：“了”与“过”不能同时用在同一个动词后，应只保留“了”，说“我把书带走了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '499b1f08-7089-4fce-8232-e7e87bcbf736') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13793, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '499b1f08-7089-4fce-8232-e7e87bcbf736') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13793, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '499b1f08-7089-4fce-8232-e7e87bcbf736') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13793, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "粉，指粉末状的细屑，也指化妆用的粉末。", "primary_collocate": null, "pronunciation": "fěn", "ipa": "fən˨˩˦", "syllable_count": 1, "sentences": [{"text": "花有粉，蜜蜂带走粉。", "target_word": "粉", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "桌子上有一层白粉。", "target_word": "粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她脸上擦了粉。", "target_word": "粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "粉很细，风一吹就飞了。", "target_word": "粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这些粉倒进水里。", "target_word": "粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他手上都是粉。", "target_word": "粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个盒子里的粉是白色的。", "target_word": "粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈出门前总要擦一点粉。", "target_word": "粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心，别把粉洒在地上。", "target_word": "粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种粉很细，要用小勺拿。", "target_word": "粉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一层粉", "label": "量词搭配"}, {"form": "花粉", "label": "复合词"}, {"form": "面粉", "label": "复合词"}, {"form": "粉末", "label": "复合词"}], "register": "中性", "sense_fingerprint": "粉末状的细屑，也指化妆用的粉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d698ce0-810b-4db1-bf3a-88dde9784e24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13793, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "粉", "is_correct": true, "explanation": "粉（fěn）：粉末状的细屑，正是这个读音。"}, {"text": "分", "is_correct": false, "explanation": "fēn（第一声）与 fěn（第三声）声调不同，意思是分开。"}, {"text": "份", "is_correct": false, "explanation": "fèn（第四声）与 fěn（第三声）声调不同，意思是份。"}, {"text": "很", "is_correct": false, "explanation": "hěn 与 fěn 声母不同（h／f），意思是很。"}, {"text": "反", "is_correct": false, "explanation": "fǎn 与 fěn 韵母不同（an／en），意思是相反。"}, {"text": "本", "is_correct": false, "explanation": "běn 与 fěn 声母不同（b／f），意思是书本。"}], "explanations": {"粉": "粉（fěn）：粉末状的细屑，正是这个读音。", "分": "fēn（第一声）与 fěn（第三声）声调不同，意思是分开。", "份": "fèn（第四声）与 fěn（第三声）声调不同，意思是份。", "很": "hěn 与 fěn 声母不同（h／f），意思是很。", "反": "fǎn 与 fěn 韵母不同（an／en），意思是相反。", "本": "běn 与 fěn 声母不同（b／f），意思是书本。"}, "sentence_index": null, "correct_answer": "粉"}, "level_3": {"options": [{"text": "粉", "is_correct": true, "explanation": "粉：花粉，花朵产生的粉末，蜜蜂会采集并带走，符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "语义：花上不长石头，蜜蜂也带不走石头，句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“带走”不能搭配“颜色”，颜色不是可以被带走的东西。"}, {"text": "叶子", "is_correct": false, "explanation": "语义：蜜蜂采走的是花粉，不是叶子，与句中的采集行为不符。"}], "explanations": {"粉": "粉：花粉，花朵产生的粉末，蜜蜂会采集并带走，符合句意。", "石头": "语义：花上不长石头，蜜蜂也带不走石头，句意不通。", "颜色": "搭配：“带走”不能搭配“颜色”，颜色不是可以被带走的东西。", "叶子": "语义：蜜蜂采走的是花粉，不是叶子，与句中的采集行为不符。"}, "sentence_index": 0, "correct_answer": "粉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天太热了，我想喝一杯冷粉。", "explanation": "这里应该用〈水〉。解渴要喝水，粉是粉末，不能直接喝。"}, {"text": "我用粉写了一个字在黑板上。", "explanation": "这里应该用〈粉笔〉。在黑板上写字用的是粉笔，“粉”不单独指粉笔。"}, {"text": "院子里堆着一堆粉，是我们挖出来的。", "explanation": "这里应该用〈土〉。从地里挖出来的是土，不是粉末。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '499b1f08-7089-4fce-8232-e7e87bcbf736') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13793, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "粉", "is_correct": true, "explanation": "粉（fěn）：粉末，正是这个读音。"}, {"text": "风", "is_correct": false, "explanation": "fēng（第一声）与 fěn 韵母不同（eng／en），意思是风。"}, {"text": "奋", "is_correct": false, "explanation": "fèn（第四声）与 fěn（第三声）声调不同，意思是奋斗。"}, {"text": "恨", "is_correct": false, "explanation": "hèn 与 fěn 声母和声调都不同，意思是恨。"}, {"text": "费", "is_correct": false, "explanation": "fèi 与 fěn 韵母不同（ei／en），意思是费用。"}], "explanations": {"粉": "粉（fěn）：粉末，正是这个读音。", "风": "fēng（第一声）与 fěn 韵母不同（eng／en），意思是风。", "奋": "fèn（第四声）与 fěn（第三声）声调不同，意思是奋斗。", "恨": "hèn 与 fěn 声母和声调都不同，意思是恨。", "费": "fèi 与 fěn 韵母不同（ei／en），意思是费用。"}, "sentence_index": null, "correct_answer": "粉"}, "level_3": {"options": [{"text": "粉", "is_correct": true, "explanation": "粉：白色的粉末，盒子里装的是粉，符合句意。"}, {"text": "水", "is_correct": false, "explanation": "语义：水本身没有颜色，说盒子里的水是白色的，句意不通。"}, {"text": "云", "is_correct": false, "explanation": "搭配：云飘在天上，不能说装在盒子里，“盒子里的云”搭配不当。"}, {"text": "海", "is_correct": false, "explanation": "语义：海太大，装不进盒子里，句意不通。"}], "explanations": {"粉": "粉：白色的粉末，盒子里装的是粉，符合句意。", "水": "语义：水本身没有颜色，说盒子里的水是白色的，句意不通。", "云": "搭配：云飘在天上，不能说装在盒子里，“盒子里的云”搭配不当。", "海": "语义：海太大，装不进盒子里，句意不通。"}, "sentence_index": 6, "correct_answer": "粉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈把粉放进茶里，当糖给我们喝。", "explanation": "这里应该用〈糖〉。粉不单独指糖，要说“糖”或“糖粉”。"}, {"text": "他把粉倒进了汽车油箱。", "explanation": "这里应该用〈汽油〉。油箱装的是汽油，粉末不能倒进油箱。"}, {"text": "他把粉挂在墙上，当作一幅画。", "explanation": "这里应该用〈画〉。粉末是散的，不能挂在墙上当画。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '499b1f08-7089-4fce-8232-e7e87bcbf736') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13793, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "袋子里装着一只粉。", "corrected_sentence": "袋子里装着一包粉。", "error_description": "“粉”指粉末，量词应用“包”。“只”用于动物或成对的东西，不能说“一只粉”。错误在于量词“只”，正确形式是“一包粉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '499b1f08-7089-4fce-8232-e7e87bcbf736') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13793, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "盒子里装着一朵粉，很细。", "corrected_sentence": "盒子里装着一包粉，很细。", "error_description": "“粉”是粉末，量词应用“包”或“袋”。“朵”用于花、云等，不能用来数粉末，错误在于量词“朵”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '499b1f08-7089-4fce-8232-e7e87bcbf736') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
