INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13794, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "植物长出果实或种子。", "primary_collocate": null, "pronunciation": "jiē chū", "ipa": "tɕjɛ˥ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "这样，花就能结出果实和种子。", "target_word": "结出", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这样，花可以结出果实。", "target_word": "结出", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "春天开花，秋天结出红红的苹果。", "target_word": "结出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这棵树今年结出了很多梨。", "target_word": "结出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花谢了以后，树枝上结出小小的果子。", "target_word": "结出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这棵桃树只用三年就结出了桃子。", "target_word": "结出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "西瓜藤结出了一个大西瓜。", "target_word": "结出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有蜜蜂帮忙，很多花不能结出果实。", "target_word": "结出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷种的葡萄今年结出了很多果子。", "target_word": "结出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种花结出的种子很小。", "target_word": "结出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "结出了", "label": "体标"}, {"form": "结出过", "label": "体标"}], "register": "中性", "sense_fingerprint": "植物长出果实或种子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dab0c558-bacf-42b5-ac45-3bf523f0ba2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13794, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "结出", "is_correct": true, "explanation": "结出（jiē chū）是本词条，指植物长出果实或种子。"}, {"text": "接触", "is_correct": false, "explanation": "chù（第四声）与 chū（第一声）声调不同，接触的意思是碰到、联系。"}, {"text": "借出", "is_correct": false, "explanation": "jiè（第四声）与 jiē（第一声）声调不同，借出的意思是把东西借给别人。"}, {"text": "杰出", "is_correct": false, "explanation": "jié（第二声）与 jiē（第一声）声调不同，杰出的意思是才能或成绩特别突出。"}, {"text": "解除", "is_correct": false, "explanation": "jiě（第三声）与 jiē（第一声）声调不同，chú（第二声）与 chū（第一声）声调也不同，解除的意思是取消、去掉。"}], "explanations": {"结出": "结出（jiē chū）是本词条，指植物长出果实或种子。", "接触": "chù（第四声）与 chū（第一声）声调不同，接触的意思是碰到、联系。", "借出": "jiè（第四声）与 jiē（第一声）声调不同，借出的意思是把东西借给别人。", "杰出": "jié（第二声）与 jiē（第一声）声调不同，杰出的意思是才能或成绩特别突出。", "解除": "jiě（第三声）与 jiē（第一声）声调不同，chú（第二声）与 chū（第一声）声调也不同，解除的意思是取消、去掉。"}, "sentence_index": null, "correct_answer": "结出"}, "level_3": {"options": [{"text": "结出", "is_correct": true, "explanation": "原句中的形式，植物长出果实和种子用“结出”。"}, {"text": "开出", "is_correct": false, "explanation": "语义：“开”指开花，“开出”说的是花开，不能说开出果实和种子。"}, {"text": "生出", "is_correct": false, "explanation": "搭配：“生出”多指人或动物生育，植物不说生出果实和种子。"}, {"text": "产出", "is_correct": false, "explanation": "语义：“产出”指产品或产量，多用于土地、工厂或人的生产成果，花不说产出果实和种子。"}], "explanations": {"结出": "原句中的形式，植物长出果实和种子用“结出”。", "开出": "语义：“开”指开花，“开出”说的是花开，不能说开出果实和种子。", "生出": "搭配：“生出”多指人或动物生育，植物不说生出果实和种子。", "产出": "语义：“产出”指产品或产量，多用于土地、工厂或人的生产成果，花不说产出果实和种子。"}, "sentence_index": 0, "correct_answer": "结出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今年，工厂结出了很多机器。", "explanation": "这里应该用〈生产〉。结出的主语应是植物，工厂制造机器要用生产。"}, {"text": "我家的猫结出了三只小猫。", "explanation": "这里应该用〈生出〉。结出只用于植物，猫、人生育小动物要用生出。"}, {"text": "我们每年秋天结出很多苹果。", "explanation": "这里应该用〈收获〉。结出的主语必须是植物，人收获庄稼要用收获。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2324f598-67e9-4228-9439-eb703c9aa929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13794, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "结出", "is_correct": true, "explanation": "原句中的形式，表示植物结出果实。"}, {"text": "收获", "is_correct": false, "explanation": "配价：“收获”的施事应是人，西瓜藤不能收获西瓜。"}, {"text": "产生", "is_correct": false, "explanation": "搭配：“产生”多搭配抽象事物，不说“产生一个大西瓜”。"}, {"text": "养出", "is_correct": false, "explanation": "配价：“养出”需要人来饲养、培育，西瓜藤不能养出西瓜。"}], "explanations": {"结出": "原句中的形式，表示植物结出果实。", "收获": "配价：“收获”的施事应是人，西瓜藤不能收获西瓜。", "产生": "搭配：“产生”多搭配抽象事物，不说“产生一个大西瓜”。", "养出": "配价：“养出”需要人来饲养、培育，西瓜藤不能养出西瓜。"}, "sentence_index": 6, "correct_answer": "结出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的嗓子结出了清脆的声音。", "explanation": "这里应该用〈发出〉。结出只用于植物结果实或种子，声音要用发出。"}, {"text": "姐姐在纸上结出了一只鸟。", "explanation": "这里应该用〈画出〉。结出只用于植物结果实或种子，纸上画出的图形要用画出。"}, {"text": "春天到了，桃树结出了一树粉色的花。", "explanation": "这里应该用〈开出〉。结出只用于果实或种子，花朵开放要用开出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2324f598-67e9-4228-9439-eb703c9aa929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13794, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这棵梨树今年结出着很多果子。", "corrected_sentence": "这棵梨树今年结出了很多果子。", "error_description": "“结出”表示结果已经出现，后面应加“了”；“结出着”不成立。表示持续的状态要说“结着”，例如“树上结着很多果子”。正确的说法是：这棵梨树今年结出了很多果子。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2324f598-67e9-4228-9439-eb703c9aa929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13794, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这株番茄结出的很多果实。", "corrected_sentence": "这株番茄结出了很多果实。", "error_description": "“结出”后应接动态助词“了”表示结果已经出现；误用“的”后，句子变成没有谓语的名词短语，不成句。正确的说法是：这株番茄结出了很多果实。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2324f598-67e9-4228-9439-eb703c9aa929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13795, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "增加", "is_correct": true, "explanation": "增加与减少相对，“变少”指数量减少，其反义是增加。"}, {"text": "保持", "is_correct": false, "explanation": "保持表示维持原状，与“变少”不构成反义。"}, {"text": "讨论", "is_correct": false, "explanation": "讨论是交流意见，与“变少”没有反义关系。"}, {"text": "移动", "is_correct": false, "explanation": "移动指位置改变，与数量的增减无关。"}], "correct_answer": "增加", "explanations": {"增加": "增加与减少相对，“变少”指数量减少，其反义是增加。", "保持": "保持表示维持原状，与“变少”不构成反义。", "讨论": "讨论是交流意见，与“变少”没有反义关系。", "移动": "移动指位置改变，与数量的增减无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2324f598-67e9-4228-9439-eb703c9aa929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13795, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "增多", "is_correct": true, "explanation": "增多与减少相反，“变少”指数量减少，其反义是数量增多。"}, {"text": "出现", "is_correct": false, "explanation": "出现指显露或产生，与“变少”不构成反义。"}, {"text": "离开", "is_correct": false, "explanation": "离开指脱离某处，与数量的变化无关，不是反义词。"}, {"text": "搬运", "is_correct": false, "explanation": "搬运指移动物体，与“变少”没有反义关系。"}], "correct_answer": "增多", "explanations": {"增多": "增多与减少相反，“变少”指数量减少，其反义是数量增多。", "出现": "出现指显露或产生，与“变少”不构成反义。", "离开": "离开指脱离某处，与数量的变化无关，不是反义词。", "搬运": "搬运指移动物体，与“变少”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2324f598-67e9-4228-9439-eb703c9aa929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13795, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "数量上减少。", "primary_collocate": null, "pronunciation": "biàn shǎo", "ipa": "pjɛn˥˩ ʂau˨˩˦", "syllable_count": 2, "sentences": [{"text": "如果蜜蜂变少了，其他动植物也会受影响。", "target_word": "变少", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "研究发现，很多地方蜜蜂变少了。", "target_word": "变少", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "冬天到了，路上的行人变少了。", "target_word": "变少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气变冷，树上的鸟变少了。", "target_word": "变少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河里的鱼变少了，渔民很担心。", "target_word": "变少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过了十点，街上的车变少了。", "target_word": "变少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月我的零花钱变少了。", "target_word": "变少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "暑假以后，教室里的学生变少了。", "target_word": "变少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林变小，山里的动物变少了。", "target_word": "变少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盒子里的饼干变少了，只剩三块。", "target_word": "变少", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "变少了", "label": "体标"}, {"form": "变少过", "label": "体标"}], "register": "中性", "sense_fingerprint": "数量上减少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dab0c558-bacf-42b5-ac45-3bf523f0ba2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13795, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "变少", "is_correct": true, "explanation": "原句中的形式，表示蜜蜂的数量减少。"}, {"text": "变甜", "is_correct": false, "explanation": "语义：“变甜”说味道，蜜蜂不会变甜，句中讲的是蜜蜂的数量。"}, {"text": "变脏", "is_correct": false, "explanation": "语义：“变脏”说外表的状况，与数量无关，不能用来描述蜜蜂减少。"}, {"text": "变长", "is_correct": false, "explanation": "语义：“变长”说外形的长度变化，与蜜蜂的数量无关。"}], "explanations": {"变少": "原句中的形式，表示蜜蜂的数量减少。", "变甜": "语义：“变甜”说味道，蜜蜂不会变甜，句中讲的是蜜蜂的数量。", "变脏": "语义：“变脏”说外表的状况，与数量无关，不能用来描述蜜蜂减少。", "变长": "语义：“变长”说外形的长度变化，与蜜蜂的数量无关。"}, "sentence_index": 0, "correct_answer": "变少"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "最近房价变少了。", "explanation": "这里应该用〈下降〉。变少只用于人或物的数量减少，房价这类数值的降低要用下降。"}, {"text": "今天的气温变少了。", "explanation": "这里应该用〈降低〉。变少说的是数量减少，气温这类数值的下降要用降低。"}, {"text": "他的汉语水平变少了。", "explanation": "这里应该用〈退步〉。变少只说数量减少，水平倒退要用退步。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2324f598-67e9-4228-9439-eb703c9aa929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13795, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "变少", "is_correct": true, "explanation": "原句中的形式，表示零花钱的数量减少。"}, {"text": "变贵", "is_correct": false, "explanation": "语义：“变贵”说价格升高，零花钱不说变贵，句中指的是数量。"}, {"text": "变厚", "is_correct": false, "explanation": "语义：“变厚”说物体的厚薄，不能用来表示钱的数量减少。"}, {"text": "变快", "is_correct": false, "explanation": "语义：“变快”说速度提高，与零花钱的数量无关。"}], "explanations": {"变少": "原句中的形式，表示零花钱的数量减少。", "变贵": "语义：“变贵”说价格升高，零花钱不说变贵，句中指的是数量。", "变厚": "语义：“变厚”说物体的厚薄，不能用来表示钱的数量减少。", "变快": "语义：“变快”说速度提高，与零花钱的数量无关。"}, "sentence_index": 6, "correct_answer": "变少"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个箱子的长度变少了。", "explanation": "这里应该用〈缩短〉。变少只说数量减少，长度变短要说“缩短”。"}, {"text": "这个箱子的重量变少了。", "explanation": "这里应该用〈减轻〉。变少只说数量减少，重量的降低要用减轻。"}, {"text": "车速变少了。", "explanation": "这里应该用〈变慢〉。变少只说数量减少，速度降低要用变慢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2324f598-67e9-4228-9439-eb703c9aa929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13795, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们小区的流浪猫变少着。", "corrected_sentence": "我们小区的流浪猫变少了。", "error_description": "“变少”表示数量已经减少，变化完成要加“了”；“变少着”不成立。正确的说法是：我们小区的流浪猫变少了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2324f598-67e9-4228-9439-eb703c9aa929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13795, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家超市的顾客被变少了。", "corrected_sentence": "这家超市的顾客变少了。", "error_description": "“变少”是不及物动词，表示数量减少，不能放在“被”字句里。错误在于加了“被”；正确的说法是：这家超市的顾客变少了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2324f598-67e9-4228-9439-eb703c9aa929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
