INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13798, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "接触并附着在物体表面，或物体表面因接触而留下痕迹。", "primary_collocate": null, "pronunciation": "zhān", "ipa": "ʈʂan˥", "syllable_count": 1, "sentences": [{"text": "蜜蜂从花里采蜜，身上会沾上花粉。", "target_word": "沾", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "他的鞋上沾了很多泥。", "target_word": "沾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小心，油漆还没干，别沾到衣服上。", "target_word": "沾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子的手上沾着蛋糕。", "target_word": "沾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的手沾上了墨水，洗不掉。", "target_word": "沾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "白衬衫上沾了一点红酒。", "target_word": "沾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨后，裤子上沾满了泥点。", "target_word": "沾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的脸上沾着面粉，像只小花猫。", "target_word": "沾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蝴蝶的翅膀沾上了花粉。", "target_word": "沾", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "刚刷的墙别用手碰，会沾一手白漆。", "target_word": "沾", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "沾了", "label": "体标（了）"}, {"form": "沾着", "label": "体标（着）"}, {"form": "沾过", "label": "体标（过）"}, {"form": "沾上", "label": "复合"}], "register": "中性", "sense_fingerprint": "接触后东西附着在表面上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '703d6979-3962-4484-92d2-882f13f16783') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13798, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "沾", "is_correct": true, "explanation": "沾（zhān，第一声），意思是接触后附着在表面上。"}, {"text": "站", "is_correct": false, "explanation": "zhàn（第四声）与 zhān（第一声）声调不同，意思是站立。"}, {"text": "针", "is_correct": false, "explanation": "zhēn 与 zhān 韵母不同（ēn 与 ān），意思是针。"}, {"text": "山", "is_correct": false, "explanation": "shān 与 zhān 声母不同（sh 与 zh），意思是山。"}, {"text": "展", "is_correct": false, "explanation": "zhǎn（第三声）与 zhān（第一声）声调不同，意思是展开。"}, {"text": "张", "is_correct": false, "explanation": "zhāng 与 zhān 韵母不同（āng 与 ān），意思是张开。"}], "explanations": {"沾": "沾（zhān，第一声），意思是接触后附着在表面上。", "站": "zhàn（第四声）与 zhān（第一声）声调不同，意思是站立。", "针": "zhēn 与 zhān 韵母不同（ēn 与 ān），意思是针。", "山": "shān 与 zhān 声母不同（sh 与 zh），意思是山。", "展": "zhǎn（第三声）与 zhān（第一声）声调不同，意思是展开。", "张": "zhāng 与 zhān 韵母不同（āng 与 ān），意思是张开。"}, "sentence_index": null, "correct_answer": "沾"}, "level_3": {"options": [{"text": "扔", "is_correct": false, "explanation": "语义：「扔」指抛掷，身上不会扔上花粉。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：「戴」用于佩戴衣物或饰物，花粉不能戴。"}, {"text": "沾", "is_correct": true, "explanation": "正确：「沾上花粉」指身上接触并附着花粉，与句意相符。"}, {"text": "烤", "is_correct": false, "explanation": "语义：「烤」指加热食物，与花粉附着无关。"}], "explanations": {"扔": "语义：「扔」指抛掷，身上不会扔上花粉。", "戴": "搭配：「戴」用于佩戴衣物或饰物，花粉不能戴。", "沾": "正确：「沾上花粉」指身上接触并附着花粉，与句意相符。", "烤": "语义：「烤」指加热食物，与花粉附着无关。"}, "sentence_index": 0, "correct_answer": "沾"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈不小心把白布沾了一个大洞。", "explanation": "这里应该用〈烧〉。沾只表示接触后附着，把布烧出洞要说〈烧〉，“沾”不能表示造成破洞。"}, {"text": "妈妈用抹布沾了桌子。", "explanation": "这里应该用〈擦〉。沾只表示轻碰后留下一点，擦桌子要用〈擦〉。"}, {"text": "他用胶水把照片沾在本子上。", "explanation": "这里应该用〈粘〉。沾只表示接触附着，用胶水固定东西要用〈粘〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '500d3285-fe4e-4f39-81a9-59a8a9272a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13798, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "沾", "is_correct": true, "explanation": "沾（zhān，第一声），意思是接触后附着在表面上。"}, {"text": "占", "is_correct": false, "explanation": "zhàn（第四声）与 zhān（第一声）声调不同，意思是占据。"}, {"text": "真", "is_correct": false, "explanation": "zhēn 与 zhān 韵母不同（ēn 与 ān），意思是真实。"}, {"text": "章", "is_correct": false, "explanation": "zhāng 与 zhān 韵母不同（āng 与 ān），意思是文章。"}], "explanations": {"沾": "沾（zhān，第一声），意思是接触后附着在表面上。", "占": "zhàn（第四声）与 zhān（第一声）声调不同，意思是占据。", "真": "zhēn 与 zhān 韵母不同（ēn 与 ān），意思是真实。", "章": "zhāng 与 zhān 韵母不同（āng 与 ān），意思是文章。"}, "sentence_index": null, "correct_answer": "沾"}, "level_3": {"options": [{"text": "写", "is_correct": false, "explanation": "语义：「写」指书写文字，泥点不能写满裤子。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：「穿」的对象是衣物，裤子上不能穿满泥点。"}, {"text": "沾", "is_correct": true, "explanation": "正确：「沾满」指泥点附着在裤子上，与「下雨后」的语境相符。"}, {"text": "缝", "is_correct": false, "explanation": "语义：「缝」指缝合，与泥点附着无关。"}], "explanations": {"写": "语义：「写」指书写文字，泥点不能写满裤子。", "穿": "搭配：「穿」的对象是衣物，裤子上不能穿满泥点。", "沾": "正确：「沾满」指泥点附着在裤子上，与「下雨后」的语境相符。", "缝": "语义：「缝」指缝合，与泥点附着无关。"}, "sentence_index": 6, "correct_answer": "沾"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用白漆沾了一遍墙。", "explanation": "这里应该用〈涂〉。沾只表示少量接触后附着，大面积涂抹要用〈涂〉。"}, {"text": "他把海报沾在墙上。", "explanation": "这里应该用〈贴〉。沾不能表示把纸张固定在墙上，要用〈贴〉。"}, {"text": "妈妈把牛奶沾进杯子里。", "explanation": "这里应该用〈倒〉。沾只表示接触后附着在物体表面，把牛奶倒进杯子要用〈倒〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '500d3285-fe4e-4f39-81a9-59a8a9272a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13798, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他身上了沾一点泥巴。", "corrected_sentence": "他身上沾了一点泥巴。", "error_description": "「了」位置错误：「了」应紧跟动词「沾」，应说「沾了一点泥巴」，不能放在「沾」之前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '500d3285-fe4e-4f39-81a9-59a8a9272a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13798, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "衣服上沾了着一点油。", "corrected_sentence": "衣服上沾着一点油。", "error_description": "体标错误：表示附着的持续状态要用「着」，「了」与「着」不能同时出现，应说「沾着一点油」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '500d3285-fe4e-4f39-81a9-59a8a9272a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
