INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13799, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "花粉是种子植物花药中的粉状微粒，由雄蕊产生，用于授粉繁殖。", "primary_collocate": null, "pronunciation": "huā fěn", "ipa": "xua˥ fən˨˩˦", "syllable_count": 2, "sentences": [{"text": "许多植物需要授粉才能结果，而蜜蜂在采集花蜜时，会把花粉从一朵花带到另一朵花，这个过程叫做授粉。", "target_word": "花粉", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "蜜蜂从花里采蜜，身上会沾上花粉。", "target_word": "花粉", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "当它飞到另一朵花时，花粉会掉下来。", "target_word": "花粉", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "春天花开了，空气里有很多花粉。", "target_word": "花粉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对花粉过敏，一到春天就打喷嚏。", "target_word": "花粉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蜜蜂的腿上沾着黄黄的花粉。", "target_word": "花粉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风把花粉吹到了很远的地方。", "target_word": "花粉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "花粉落在雌蕊上，花才能结果。", "target_word": "花粉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种花的花粉是黄色的，很细。", "target_word": "花粉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他戴着口罩，不想吸进花粉。", "target_word": "花粉", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一粒花粉", "label": "量词"}, {"form": "花粉管", "label": "复合"}], "register": "中性", "sense_fingerprint": "植物雄蕊产生、用于授粉的粉状微粒", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d653fec-04d6-4c8b-893f-33391eee6ee0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13799, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "花粉", "is_correct": true, "explanation": "正确：句中“花粉”指花药里的粉状微粒，蜜蜂把它从一朵花带到另一朵花，帮助授粉。"}, {"text": "种子", "is_correct": false, "explanation": "语义：蜜蜂带走的是花粉，种子并不参与授粉，句子说的是授粉过程。"}, {"text": "果实", "is_correct": false, "explanation": "语义：果实要在授粉之后才结出，花不会把果实带到另一朵花上。"}, {"text": "花瓣", "is_correct": false, "explanation": "搭配：“带……到……”一般接可以移动的东西，花瓣固定长在花上，不说被带走。"}], "explanations": {"花粉": "正确：句中“花粉”指花药里的粉状微粒，蜜蜂把它从一朵花带到另一朵花，帮助授粉。", "种子": "语义：蜜蜂带走的是花粉，种子并不参与授粉，句子说的是授粉过程。", "果实": "语义：果实要在授粉之后才结出，花不会把果实带到另一朵花上。", "花瓣": "搭配：“带……到……”一般接可以移动的东西，花瓣固定长在花上，不说被带走。"}, "sentence_index": 0, "correct_answer": "花粉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "蜜蜂把花粉酿成了蜂蜜。", "explanation": "这里应该用〈花蜜〉。蜂蜜是蜜蜂用花蜜酿成的，花粉不能用来酿蜜。"}, {"text": "公园里开满了美丽的花粉。", "explanation": "这里应该用〈花朵〉。“开满”说的是花朵开放，花粉本身不会开放。"}, {"text": "桌上放着一朵花粉。", "explanation": "这里应该用〈点〉。“朵”用于花朵，花粉是粉末，应该说“一点花粉”或“一粒花粉”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '882a0bcb-908b-47d8-af67-d883598ad1ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13799, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "花粉", "is_correct": true, "explanation": "正确：句中“花粉”是植物的粉状微粒，风把它吹到很远的地方，帮助植物繁殖。"}, {"text": "大象", "is_correct": false, "explanation": "语义：大象体形庞大、非常重，风吹不动，不能说被吹到很远的地方。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱又大又重，不会被风吹走，这句话不合常理。"}, {"text": "墙", "is_correct": false, "explanation": "搭配：“吹到……的地方”说的是轻的东西被吹走，墙是固定的建筑，不说被风吹走。"}], "explanations": {"花粉": "正确：句中“花粉”是植物的粉状微粒，风把它吹到很远的地方，帮助植物繁殖。", "大象": "语义：大象体形庞大、非常重，风吹不动，不能说被吹到很远的地方。", "冰箱": "语义：冰箱又大又重，不会被风吹走，这句话不合常理。", "墙": "搭配：“吹到……的地方”说的是轻的东西被吹走，墙是固定的建筑，不说被风吹走。"}, "sentence_index": 6, "correct_answer": "花粉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师在黑板上用花粉写字。", "explanation": "这里应该用〈粉笔〉。在黑板上写字要用粉笔，花粉不能用来写字。"}, {"text": "窗台上放着一条花粉。", "explanation": "这里应该用〈点〉。“条”用于细长的东西，花粉是粉末，应该说“一点花粉”。"}, {"text": "妈妈用花粉和面，做了馒头。", "explanation": "这里应该用〈面粉〉。和面、做馒头要用面粉，花粉不能用来和面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '882a0bcb-908b-47d8-af67-d883598ad1ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13799, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的鼻子里进了一个花粉。", "corrected_sentence": "我的鼻子里进了一点花粉。", "error_description": "量词错误：花粉是粉末，应用“点”或“粒”计量，不能用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '882a0bcb-908b-47d8-af67-d883598ad1ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13799, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "蜜蜂把黄色地花粉带回了蜂巢。", "corrected_sentence": "蜜蜂把黄色的花粉带回了蜂巢。", "error_description": "结构助词错误：修饰名词“花粉”的“黄色”要用“的”，“地”用于修饰动词，不能用在名词前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '882a0bcb-908b-47d8-af67-d883598ad1ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13801, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "懒惰", "is_correct": true, "explanation": "正确：“懒惰”与“勤劳”是一对反义词，指不愿劳动、不肯吃苦。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”指没有声音或情绪平稳，与“勤劳”不构成反义关系。"}, {"text": "富裕", "is_correct": false, "explanation": "“富裕”指物质条件充足，与“勤劳”所说的劳动态度没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”指光线充足、颜色鲜亮，与“勤劳”没有反义关系。"}], "correct_answer": "懒惰", "explanations": {"懒惰": "正确：“懒惰”与“勤劳”是一对反义词，指不愿劳动、不肯吃苦。", "安静": "“安静”指没有声音或情绪平稳，与“勤劳”不构成反义关系。", "富裕": "“富裕”指物质条件充足，与“勤劳”所说的劳动态度没有反义关系。", "明亮": "“明亮”指光线充足、颜色鲜亮，与“勤劳”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '500d3285-fe4e-4f39-81a9-59a8a9272a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13801, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "懒惰", "is_correct": true, "explanation": "正确：“懒惰”与“勤劳”是一对反义词，指不愿劳动、不肯吃苦。"}, {"text": "灵活", "is_correct": false, "explanation": "“灵活”指反应快、不呆板，与“勤劳”不构成反义关系。"}, {"text": "慷慨", "is_correct": false, "explanation": "“慷慨”指大方、不吝啬，与“勤劳”不构成反义关系。"}, {"text": "沉默", "is_correct": false, "explanation": "“沉默”指不爱说话，与“勤劳”不构成反义关系。"}], "correct_answer": "懒惰", "explanations": {"懒惰": "正确：“懒惰”与“勤劳”是一对反义词，指不愿劳动、不肯吃苦。", "灵活": "“灵活”指反应快、不呆板，与“勤劳”不构成反义关系。", "慷慨": "“慷慨”指大方、不吝啬，与“勤劳”不构成反义关系。", "沉默": "“沉默”指不爱说话，与“勤劳”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '500d3285-fe4e-4f39-81a9-59a8a9272a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13801, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指努力劳动，不怕辛苦。", "primary_collocate": null, "pronunciation": "qín láo", "ipa": "tɕʰin˧˥ lau˧˥", "syllable_count": 2, "sentences": [{"text": "其他昆虫也可以帮忙，但蜜蜂是最勤劳的。", "target_word": "勤劳", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我的奶奶一辈子都很勤劳。", "target_word": "勤劳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "勤劳的农民每天天不亮就下地干活。", "target_word": "勤劳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蚂蚁和蜜蜂都是勤劳的小动物。", "target_word": "勤劳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他很勤劳，家里总是干干净净。", "target_word": "勤劳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈勤劳又善良，大家都喜欢她。", "target_word": "勤劳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "勤劳的人不怕累，总是有活就干。", "target_word": "勤劳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "靠自己勤劳的双手，他们盖起了新房子。", "target_word": "勤劳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个村子的人很勤劳，日子过得越来越好。", "target_word": "勤劳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要学习他勤劳的精神。", "target_word": "勤劳", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "勤劳的", "label": "的字结构"}, {"form": "勤劳地", "label": "状语形式"}, {"form": "勤勞", "label": "繁体"}], "register": "中性", "sense_fingerprint": "努力劳动、不怕辛苦的品质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '703d6979-3962-4484-92d2-882f13f16783') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13801, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "勤劳", "is_correct": true, "explanation": "正确：指努力劳动、不怕辛苦，与“其他昆虫也可以帮忙，但……”的对比相合，突出蜜蜂最能干。"}, {"text": "懒惰", "is_correct": false, "explanation": "语义：“懒惰”指不愿劳动，说蜜蜂是最懒惰的，与“但”引出的对比矛盾。"}, {"text": "狡猾", "is_correct": false, "explanation": "语义：“狡猾”指耍心眼、不老实，与句中“帮忙”所体现的正面形象相反。"}, {"text": "娇气", "is_correct": false, "explanation": "搭配：“娇气”多指怕苦、受不了累的人，用来形容以勤劳著称的蜜蜂不合语境。"}], "explanations": {"勤劳": "正确：指努力劳动、不怕辛苦，与“其他昆虫也可以帮忙，但……”的对比相合，突出蜜蜂最能干。", "懒惰": "语义：“懒惰”指不愿劳动，说蜜蜂是最懒惰的，与“但”引出的对比矛盾。", "狡猾": "语义：“狡猾”指耍心眼、不老实，与句中“帮忙”所体现的正面形象相反。", "娇气": "搭配：“娇气”多指怕苦、受不了累的人，用来形容以勤劳著称的蜜蜂不合语境。"}, "sentence_index": 0, "correct_answer": "勤劳"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件外套很勤劳，穿了五年还是完好无损。", "explanation": "这里应该用〈结实〉。勤劳只用于人或动物，形容衣物耐穿要说结实。"}, {"text": "这块蛋糕很勤劳，吃起来又软又香。", "explanation": "这里应该用〈松软〉。勤劳只用于人或动物，形容食物口感要说松软。"}, {"text": "这座桥很勤劳，经受了几十年的风雨。", "explanation": "这里应该用〈坚固〉。勤劳只用于人或动物，形容建筑牢固要说坚固。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '500d3285-fe4e-4f39-81a9-59a8a9272a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13801, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "勤劳", "is_correct": true, "explanation": "正确：指努力劳动、不怕辛苦，与“不怕累，总是有活就干”一致。"}, {"text": "挑剔", "is_correct": false, "explanation": "语义：“挑剔”指对事情要求过高、不肯随便接受，与“有活就干”相反。"}, {"text": "脆弱", "is_correct": false, "explanation": "语义：“脆弱”指经不起考验、容易受伤，与“不怕累”的意思矛盾。"}, {"text": "慵懒", "is_correct": false, "explanation": "语义：“慵懒”指懒洋洋、不爱动，与“不怕累，总是有活就干”的意思正相反。"}], "explanations": {"勤劳": "正确：指努力劳动、不怕辛苦，与“不怕累，总是有活就干”一致。", "挑剔": "语义：“挑剔”指对事情要求过高、不肯随便接受，与“有活就干”相反。", "脆弱": "语义：“脆弱”指经不起考验、容易受伤，与“不怕累”的意思矛盾。", "慵懒": "语义：“慵懒”指懒洋洋、不爱动，与“不怕累，总是有活就干”的意思正相反。"}, "sentence_index": 6, "correct_answer": "勤劳"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条路很勤劳，弯弯曲曲一直通到山顶。", "explanation": "这里应该用〈蜿蜒〉。勤劳只用于人或动物，形容道路弯曲要说蜿蜒。"}, {"text": "这把椅子很勤劳，用了二十年还没坏。", "explanation": "这里应该用〈耐用〉。勤劳只用于人或动物，形容物品耐用要说耐用。"}, {"text": "他过马路很勤劳，每次都左右张望。", "explanation": "这里应该用〈谨慎〉。勤劳说的是肯干，行事小心、提防危险要说谨慎。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '500d3285-fe4e-4f39-81a9-59a8a9272a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13801, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她每天勤劳的打扫房间。", "corrected_sentence": "她每天勤劳地打扫房间。", "error_description": "“勤劳”修饰动词“打扫”时要用“地”。写成“勤劳的打扫”是错误的，正确说法是“勤劳地打扫”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '500d3285-fe4e-4f39-81a9-59a8a9272a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13801, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她比她姐姐最勤劳。", "corrected_sentence": "她比她姐姐更勤劳。", "error_description": "比较错误：“比”字句表示程度时要用“更”，不能用“最”，应说“她比她姐姐更勤劳”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '500d3285-fe4e-4f39-81a9-59a8a9272a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
