INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13802, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用翅膀在空中移动，如鸟或昆虫", "primary_collocate": null, "pronunciation": "fēi", "ipa": "fei˥", "syllable_count": 1, "sentences": [{"text": "它们每天可以飞很远，去很多花上。", "target_word": "飞", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "小鸟从树上飞走了。", "target_word": "飞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蝴蝶飞过了小河。", "target_word": "飞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天上有几只鸟在飞。", "target_word": "飞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，燕子从南方飞回来。", "target_word": "飞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只鸟受伤了，飞不高。", "target_word": "飞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜜蜂飞到花上，开始采蜜。", "target_word": "飞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，那只白鸟飞得很高。", "target_word": "飞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸟儿飞着唱着，一点也不累。", "target_word": "飞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雁秋天会往南飞。", "target_word": "飞", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "飞了", "label": "体标"}, {"form": "飞着", "label": "体标"}, {"form": "飞过", "label": "体标"}, {"form": "飛", "label": "繁体"}], "register": "中性", "sense_fingerprint": "鸟或昆虫用翅膀在空中移动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e84b5b62-f832-4dbb-bc2a-7fd6d14aeece') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13802, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "飞", "is_correct": true, "explanation": "正确答案：飞（fēi），用翅膀在空中移动。"}, {"text": "肥", "is_correct": false, "explanation": "féi（第二声）与 fēi（第一声）声调不同，意思是肥。"}, {"text": "废", "is_correct": false, "explanation": "fèi（第四声）与 fēi（第一声）声调不同，意思是废弃。"}, {"text": "匪", "is_correct": false, "explanation": "fěi（第三声）与 fēi（第一声）声调不同，意思是土匪。"}, {"text": "费", "is_correct": false, "explanation": "fèi（第四声）与 fēi（第一声）声调不同，意思是费用。"}], "explanations": {"飞": "正确答案：飞（fēi），用翅膀在空中移动。", "肥": "féi（第二声）与 fēi（第一声）声调不同，意思是肥。", "废": "fèi（第四声）与 fēi（第一声）声调不同，意思是废弃。", "匪": "fěi（第三声）与 fēi（第一声）声调不同，意思是土匪。", "费": "fèi（第四声）与 fēi（第一声）声调不同，意思是费用。"}, "sentence_index": null, "correct_answer": "飞"}, "level_3": {"options": [{"text": "睡", "is_correct": false, "explanation": "语义：“睡”指闭眼休息，不能表示移动很远，句意不通。"}, {"text": "飞", "is_correct": true, "explanation": "正确：“飞”指用翅膀在空中移动，与“飞很远，去花上”相符。"}, {"text": "站", "is_correct": false, "explanation": "搭配：“站”表示停留在某处，不说“站很远”，不能表示长距离移动。"}, {"text": "拉", "is_correct": false, "explanation": "语义：“拉”指用力牵引物体，不表示自身移动，句意不通。"}], "explanations": {"睡": "语义：“睡”指闭眼休息，不能表示移动很远，句意不通。", "飞": "正确：“飞”指用翅膀在空中移动，与“飞很远，去花上”相符。", "站": "搭配：“站”表示停留在某处，不说“站很远”，不能表示长距离移动。", "拉": "语义：“拉”指用力牵引物体，不表示自身移动，句意不通。"}, "sentence_index": 0, "correct_answer": "飞"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "木头在河面上飞。", "explanation": "这里应该用〈漂〉。木头靠水的浮力在水面上漂动，不会在空中飞；“飞”说的是鸟、虫等用翅膀在空中动。"}, {"text": "鱼在水里飞来飞去。", "explanation": "这里应该用〈游〉。鱼在水中靠鳍游动，“飞”要用翅膀，不能用在鱼身上。"}, {"text": "马在草原上飞。", "explanation": "这里应该用〈跑〉。马靠四条腿跑动，“飞”要靠翅膀，马不会飞。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f500a6c-5aff-4760-a8d3-1b1cdbc1029e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13802, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "飞", "is_correct": true, "explanation": "正确答案：飞（fēi），用翅膀在空中移动。"}, {"text": "肺", "is_correct": false, "explanation": "fèi（第四声）与 fēi（第一声）声调不同，意思是肺部。"}, {"text": "吠", "is_correct": false, "explanation": "fèi（第四声）与 fēi（第一声）声调不同，意思是狗叫。"}, {"text": "沸", "is_correct": false, "explanation": "fèi（第四声）与 fēi（第一声）声调不同，意思是沸腾。"}, {"text": "诽", "is_correct": false, "explanation": "fěi（第三声）与 fēi（第一声）声调不同，意思是诽谤。"}], "explanations": {"飞": "正确答案：飞（fēi），用翅膀在空中移动。", "肺": "fèi（第四声）与 fēi（第一声）声调不同，意思是肺部。", "吠": "fèi（第四声）与 fēi（第一声）声调不同，意思是狗叫。", "沸": "fèi（第四声）与 fēi（第一声）声调不同，意思是沸腾。", "诽": "fěi（第三声）与 fēi（第一声）声调不同，意思是诽谤。"}, "sentence_index": null, "correct_answer": "飞"}, "level_3": {"options": [{"text": "躺", "is_correct": false, "explanation": "语义：“躺”指身体平放休息，蜜蜂不会躺到花上，与“开始采蜜”不符。"}, {"text": "飞", "is_correct": true, "explanation": "正确：“飞”指用翅膀在空中移动，与“飞到花上”相符。"}, {"text": "滚", "is_correct": false, "explanation": "语义：“滚”指物体翻转移动，与蜜蜂飞到花上的动作不符。"}, {"text": "翻", "is_correct": false, "explanation": "体貌：“翻”指身体翻转，与蜜蜂靠翅膀飞行的动作不符。"}], "explanations": {"躺": "语义：“躺”指身体平放休息，蜜蜂不会躺到花上，与“开始采蜜”不符。", "飞": "正确：“飞”指用翅膀在空中移动，与“飞到花上”相符。", "滚": "语义：“滚”指物体翻转移动，与蜜蜂飞到花上的动作不符。", "翻": "体貌：“翻”指身体翻转，与蜜蜂靠翅膀飞行的动作不符。"}, "sentence_index": 6, "correct_answer": "飞"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "猴子在树上飞来飞去。", "explanation": "这里应该用〈爬〉。猴子靠手脚攀援，不是用翅膀飞。"}, {"text": "老人慢慢飞回家。", "explanation": "这里应该用〈走〉。人回家靠步行或乘车，不能用“飞”。"}, {"text": "青蛙在水边飞。", "explanation": "这里应该用〈跳〉。青蛙靠后腿跳跃，不会飞。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f500a6c-5aff-4760-a8d3-1b1cdbc1029e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13802, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只小鸟从窗前飞了走。", "corrected_sentence": "那只小鸟从窗前飞走了。", "error_description": "“飞走”是动词加结果补语，“了”要放在补语“走”后面：应说“飞走了”，不说“飞了走”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f500a6c-5aff-4760-a8d3-1b1cdbc1029e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13802, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只老鹰飞了很高。", "corrected_sentence": "那只老鹰飞得很高。", "error_description": "补语“很高”前要用“得”连接：应说“飞得很高”，不说“飞了很高”，“了”不能用在动词和补语之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f500a6c-5aff-4760-a8d3-1b1cdbc1029e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
