INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13803, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "动植物是动物和植物的总称，包括所有生物中的动物界和植物界。", "primary_collocate": null, "pronunciation": "dòng zhí wù", "ipa": "tʊŋ˥˩ ʈʂɨ˧˥ u˥˩", "syllable_count": 3, "sentences": [{"text": "如果蜜蜂变少了，其他动植物也会受影响。", "target_word": "动植物", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这个公园里有很多动植物。", "target_word": "动植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要保护动植物。", "target_word": "动植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的动植物很丰富。", "target_word": "动植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带我们去看动植物。", "target_word": "动植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林里生活着很多动植物。", "target_word": "动植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书介绍了海边的动植物。", "target_word": "动植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气太冷，有些动植物活不下去。", "target_word": "动植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对动植物很感兴趣。", "target_word": "动植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水脏了，河里的动植物都少了。", "target_word": "动植物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "動植物", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动物和植物的总称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e84b5b62-f832-4dbb-bc2a-7fd6d14aeece') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13803, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "汽车", "is_correct": false, "explanation": "语义：“汽车”是人造的交通工具，不属于会受蜜蜂数量影响的生态群体，与生态语境不符。"}, {"text": "动植物", "is_correct": true, "explanation": "正确：“动植物”指动物和植物的总称，与“其他动植物也会受影响”相符。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“天空”是整体概念，不说“其他天空”。"}, {"text": "家具", "is_correct": false, "explanation": "语义：“家具”是人造物，不在蜜蜂所在的生态系统中，与句意不符。"}], "explanations": {"汽车": "语义：“汽车”是人造的交通工具，不属于会受蜜蜂数量影响的生态群体，与生态语境不符。", "动植物": "正确：“动植物”指动物和植物的总称，与“其他动植物也会受影响”相符。", "天空": "搭配：“天空”是整体概念，不说“其他天空”。", "家具": "语义：“家具”是人造物，不在蜜蜂所在的生态系统中，与句意不符。"}, "sentence_index": 0, "correct_answer": "动植物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在森林里发现了一只动植物。", "explanation": "这里应该用〈种〉。动植物是总称，不能用“只”来数，要说“一种动植物”。"}, {"text": "这片草地上长满了动植物。", "explanation": "这里应该用〈植物〉。“长满”说的是植物，动植物里有动物，动物不会长在草地上。"}, {"text": "山上种了很多动植物。", "explanation": "这里应该用〈树〉。“种”说的是植物，动植物里有动物，动物不能种。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f500a6c-5aff-4760-a8d3-1b1cdbc1029e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13803, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "螺丝钉", "is_correct": false, "explanation": "语义：“螺丝钉”是机械零件，不是书中介绍海边事物的对象，与句意不符。"}, {"text": "动植物", "is_correct": true, "explanation": "正确：“动植物”指海边的动物和植物，与“这本书介绍了海边的动植物”相符。"}, {"text": "地铁", "is_correct": false, "explanation": "语义：地铁是城市交通设施，不是书中介绍海边动植物的对象，与句意不符。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是家用电器，海边的冰箱不是书中介绍的内容。"}], "explanations": {"螺丝钉": "语义：“螺丝钉”是机械零件，不是书中介绍海边事物的对象，与句意不符。", "动植物": "正确：“动植物”指海边的动物和植物，与“这本书介绍了海边的动植物”相符。", "地铁": "语义：地铁是城市交通设施，不是书中介绍海边动植物的对象，与句意不符。", "冰箱": "语义：“冰箱”是家用电器，海边的冰箱不是书中介绍的内容。"}, "sentence_index": 6, "correct_answer": "动植物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他买了一条动植物。", "explanation": "这里应该用〈种〉。动植物是总称，“条”用于细长的东西，不能用来数动植物。"}, {"text": "花园里种满了动植物。", "explanation": "这里应该用〈植物〉。“种满”说的是植物，动植物里有动物，动物不能种。"}, {"text": "我每天早上喂家里的动植物喝牛奶。", "explanation": "这里应该用〈小猫〉。动植物是动物和植物的总称，不能指家里具体的一只宠物，植物也不喝牛奶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f500a6c-5aff-4760-a8d3-1b1cdbc1029e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13803, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这片保护区里有很多动植物们。", "corrected_sentence": "这片保护区里有很多动植物。", "error_description": "“们”只用于指人，动植物是总称，不能加“们”，应说“动植物”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f500a6c-5aff-4760-a8d3-1b1cdbc1029e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13803, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们应该尊重这个动植物。", "corrected_sentence": "我们应该尊重这些动植物。", "error_description": "“动植物”是总称，指多种生物，不能用量词“个”来限定，应说“这些动植物”，不说“这个动植物”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f500a6c-5aff-4760-a8d3-1b1cdbc1029e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
