INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13804, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "蜜蜂从花中采集花蜜，经酿造后储存在蜂巢中的甜物质。", "primary_collocate": null, "pronunciation": "fēng mì", "ipa": "fɤŋ˥ mi˥˩", "syllable_count": 2, "sentences": [{"text": "蜜蜂很勤劳，每天都在生产蜂蜜。", "target_word": "蜂蜜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蜜蜂是一种重要的昆虫，它们不仅生产蜂蜜，还在生态系统中扮演着关键角色。", "target_word": "蜂蜜", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "蜂蜜是蜜蜂用花蜜做成的，很甜。", "target_word": "蜂蜜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蜂农从蜂巢里取出新鲜的蜂蜜。", "target_word": "蜂蜜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我早上喝牛奶时，喜欢加一勺蜂蜜。", "target_word": "蜂蜜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这瓶蜂蜜是从山里的蜂农那里买的。", "target_word": "蜂蜜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蜂蜜放得很久也不会坏。", "target_word": "蜂蜜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蜜蜂酿造蜂蜜，要采很多朵花的花蜜。", "target_word": "蜂蜜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶说，嗓子疼时吃点蜂蜜会好一些。", "target_word": "蜂蜜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "面包上抹着一层金黄色的蜂蜜。", "target_word": "蜂蜜", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一瓶蜂蜜", "label": "量词"}, {"form": "蜂蜜水", "label": "复合"}], "register": "中性", "sense_fingerprint": "蜜蜂酿造并储存在蜂巢中的甜物质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d653fec-04d6-4c8b-893f-33391eee6ee0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13804, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "蜂蜜", "is_correct": true, "explanation": "正确答案：蜂蜜（fēng mì），蜜蜂用花蜜酿成、储存在蜂巢中的甜物质。"}, {"text": "分泌", "is_correct": false, "explanation": "fēn 与 fēng 韵尾不同（n 与 ng），分泌（fēn mì）意思是生物体排出某种物质。"}, {"text": "锋利", "is_correct": false, "explanation": "mì 与 lì 声母不同（m 与 l），锋利（fēng lì）意思是刀刃等很薄很快。"}, {"text": "风气", "is_correct": false, "explanation": "mì 与 qì 声母不同（m 与 q），风气（fēng qì）意思是社会或集体的习惯和作风。"}, {"text": "风靡", "is_correct": false, "explanation": "mǐ（第三声）与 mì（第四声）声调不同，风靡（fēng mǐ）意思是广泛流行。"}], "explanations": {"蜂蜜": "正确答案：蜂蜜（fēng mì），蜜蜂用花蜜酿成、储存在蜂巢中的甜物质。", "分泌": "fēn 与 fēng 韵尾不同（n 与 ng），分泌（fēn mì）意思是生物体排出某种物质。", "锋利": "mì 与 lì 声母不同（m 与 l），锋利（fēng lì）意思是刀刃等很薄很快。", "风气": "mì 与 qì 声母不同（m 与 q），风气（fēng qì）意思是社会或集体的习惯和作风。", "风靡": "mǐ（第三声）与 mì（第四声）声调不同，风靡（fēng mǐ）意思是广泛流行。"}, "sentence_index": null, "correct_answer": "蜂蜜"}, "level_3": {"options": [{"text": "蜂蜜", "is_correct": true, "explanation": "正确：句中“蜂蜜”指蜜蜂酿造的甜物质，与“生产”搭配，表示蜜蜂的产物。"}, {"text": "牛奶", "is_correct": false, "explanation": "语义：蜜蜂不产牛奶，句子说的是蜜蜂的产物，这里不合事实。"}, {"text": "布料", "is_correct": false, "explanation": "语义：蜜蜂不生产布料，与句中“蜜蜂”的作用不符。"}, {"text": "花朵", "is_correct": false, "explanation": "搭配：“生产”一般接产品，花朵是植物长出来的，不说生产。"}], "explanations": {"蜂蜜": "正确：句中“蜂蜜”指蜜蜂酿造的甜物质，与“生产”搭配，表示蜜蜂的产物。", "牛奶": "语义：蜜蜂不产牛奶，句子说的是蜜蜂的产物，这里不合事实。", "布料": "语义：蜜蜂不生产布料，与句中“蜜蜂”的作用不符。", "花朵": "搭配：“生产”一般接产品，花朵是植物长出来的，不说生产。"}, "sentence_index": 0, "correct_answer": "蜂蜜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "蜜蜂从花里采集蜂蜜。", "explanation": "这里应该用〈花蜜〉。蜜蜂采集的是花蜜，蜂蜜要在酿好后才有。"}, {"text": "蜂蜜可以用来做蜡烛。", "explanation": "这里应该用〈蜂蜡〉。蜡烛用蜂蜡做，蜂蜜是甜的食物，不能做蜡烛。"}, {"text": "厨房里放着一只蜂蜜。", "explanation": "这里应该用〈瓶〉。蜂蜜是液体，用“瓶”计量；“只”用于动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '882a0bcb-908b-47d8-af67-d883598ad1ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13804, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蜂蜜", "is_correct": true, "explanation": "正确：句中“蜂蜜”是可以长期保存的甜食，放得很久也不会坏。"}, {"text": "鲜花", "is_correct": false, "explanation": "语义：鲜花放久了会枯萎，不会“放得很久也不会坏”。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“放得很久”一般用于可以保存的食物或物品，房子不能被“放”。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包放久了会变硬、发霉，不会“放得很久也不会坏”。"}], "explanations": {"蜂蜜": "正确：句中“蜂蜜”是可以长期保存的甜食，放得很久也不会坏。", "鲜花": "语义：鲜花放久了会枯萎，不会“放得很久也不会坏”。", "房子": "搭配：“放得很久”一般用于可以保存的食物或物品，房子不能被“放”。", "面包": "语义：面包放久了会变硬、发霉，不会“放得很久也不会坏”。"}, "sentence_index": 6, "correct_answer": "蜂蜜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "田里飞着很多蜂蜜。", "explanation": "这里应该用〈蜜蜂〉。“飞”的是蜜蜂这样的昆虫，蜂蜜是液体食物，不会飞。"}, {"text": "妈妈用蜂蜜炸了一盘薯条。", "explanation": "这里应该用〈油〉。炸东西要用油，蜂蜜受热容易焦，不能用来炸。"}, {"text": "桌上放着一条蜂蜜。", "explanation": "这里应该用〈瓶〉。蜂蜜是液体，用“瓶”计量，“条”用于细长的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '882a0bcb-908b-47d8-af67-d883598ad1ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13804, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "超市里有一个蜂蜜。", "corrected_sentence": "超市里有一瓶蜂蜜。", "error_description": "量词错误：蜂蜜是液体，应用“瓶”计量，不能用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '882a0bcb-908b-47d8-af67-d883598ad1ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13804, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈买了一瓶很甜蜂蜜。", "corrected_sentence": "妈妈买了一瓶很甜的蜂蜜。", "error_description": "结构错误：“很甜”修饰“蜂蜜”，中间要加“的”，不能直接说“很甜蜂蜜”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '882a0bcb-908b-47d8-af67-d883598ad1ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
