INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13806, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '882a0bcb-908b-47d8-af67-d883598ad1ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13806, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指雄蕊的花粉传到雌蕊柱头上的过程。", "primary_collocate": null, "pronunciation": "shòu fěn", "ipa": "ʂoʊ˥˩ fən˨˩˦", "syllable_count": 2, "sentences": [{"text": "在地球错综复杂的生态系统中，蜜蜂作为最为关键的授粉昆虫之一，其存在远不止于生产蜂蜜这一表层价值。", "target_word": "授粉", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "事实上，全球约75%的农作物种类在不同程度上依赖动物授粉，而蜜蜂正是其中占比最高的传粉媒介。", "target_word": "授粉", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这些研究揭示了一个令人警觉的事实：当某一区域的授粉昆虫丰度下降时，不仅植物结实率显著降低，连锁效应还会波及依赖这些植物生存的鸟类、哺乳动物及其他无脊椎动物，从而引发生态系统服务功能的级联式崩溃。", "target_word": "授粉", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "例如，在某些高原农业区，野生蜂类数量锐减已导致本地果树坐果率不足三成，迫使农民转向成本高昂的人工授粉，这不仅增加了农业生产的经济负担，也暴露了食物供应链的脆弱性。", "target_word": "授粉", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "部分前沿研究指出，建立生态廊道、恢复原生植被、实施精准农业管理以及制定跨区域的授粉保护政策，可能是缓解危机的有效路径。", "target_word": "授粉", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "某些国家已启动保护授粉昆虫的计划，通过立法限制特定神经毒性农药的使用，并鼓励农场主采用生态友好型耕作方式。", "target_word": "授粉", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "许多植物需要授粉才能结果，而蜜蜂在采集花蜜时，会把花粉从一朵花带到另一朵花。", "target_word": "授粉", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "农业非常依赖蜜蜂的授粉服务。", "target_word": "授粉", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "科学家估计，全球大约三分之一的粮食生产与蜜蜂授粉有关。", "target_word": "授粉", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "春天花开了，蜜蜂飞来飞去帮花授粉。", "target_word": "授粉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "授粉了", "label": "体标"}, {"form": "人工授粉", "label": "复合"}], "register": "中性", "sense_fingerprint": "授粉：花粉从雄蕊传到雌蕊柱头的过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d653fec-04d6-4c8b-893f-33391eee6ee0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13806, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "授粉", "is_correct": true, "explanation": "正确：修饰“昆虫”，指蜜蜂传递花粉的作用，与“最为关键”的生态角色相符。"}, {"text": "生产", "is_correct": false, "explanation": "搭配：“生产”的对象应是蜂蜜、粮食等产品，不能用来修饰“昆虫”。"}, {"text": "装修", "is_correct": false, "explanation": "语义：装修指整修房屋，不能修饰“昆虫”，与生态作用无关。"}, {"text": "考试", "is_correct": false, "explanation": "搭配：“考试昆虫”不成词，考试与昆虫的生态作用无关。"}], "explanations": {"授粉": "正确：修饰“昆虫”，指蜜蜂传递花粉的作用，与“最为关键”的生态角色相符。", "生产": "搭配：“生产”的对象应是蜂蜜、粮食等产品，不能用来修饰“昆虫”。", "装修": "语义：装修指整修房屋，不能修饰“昆虫”，与生态作用无关。", "考试": "搭配：“考试昆虫”不成词，考试与昆虫的生态作用无关。"}, "sentence_index": 0, "correct_answer": "授粉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位老师每天在课堂上认真授粉，学生都很喜欢。", "explanation": "这里应该用〈授课〉。授粉指花粉传到雌蕊柱头，只用于植物的花；老师讲课要说授课。"}, {"text": "我昨天给新买的书架授粉了。", "explanation": "这里应该用〈粉刷〉。授粉指花粉传到雌蕊柱头，只用于植物的花；给书架涂色、上漆要说粉刷。"}, {"text": "妈妈每天早上都给我授粉。", "explanation": "这里应该用〈照顾〉。授粉只指植物花粉的传递，只用于植物；妈妈照顾孩子要说照顾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '882a0bcb-908b-47d8-af67-d883598ad1ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13806, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "授粉", "is_correct": true, "explanation": "正确：作“需要”的宾语，指植物结果前必需的传粉过程。"}, {"text": "迁徙", "is_correct": false, "explanation": "语义：植物不会迁徙，与“需要……才能结果”的语境不符。"}, {"text": "睡眠", "is_correct": false, "explanation": "语义：睡眠与植物结果无关，句意说的是结果所需的条件。"}, {"text": "唱歌", "is_correct": false, "explanation": "搭配：“需要……才能结果”不搭配“唱歌”，二者没有因果关系。"}], "explanations": {"授粉": "正确：作“需要”的宾语，指植物结果前必需的传粉过程。", "迁徙": "语义：植物不会迁徙，与“需要……才能结果”的语境不符。", "睡眠": "语义：睡眠与植物结果无关，句意说的是结果所需的条件。", "唱歌": "搭配：“需要……才能结果”不搭配“唱歌”，二者没有因果关系。"}, "sentence_index": 6, "correct_answer": "授粉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生每天都给病人授粉。", "explanation": "这里应该用〈看病〉。授粉只用于植物的花；医生给病人治疗要说看病。"}, {"text": "农民每天都给小猪授粉。", "explanation": "这里应该用〈喂〉。授粉只用于植物的花；给小猪吃食要说喂。"}, {"text": "爸爸每天都给汽车授粉。", "explanation": "这里应该用〈加油〉。授粉只用于植物的花；给汽车补充燃料要说加油。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '882a0bcb-908b-47d8-af67-d883598ad1ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13806, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "蜜蜂正在被苹果花授粉。", "corrected_sentence": "蜜蜂正在给苹果花授粉。", "error_description": "介词错误：引出授粉对象“苹果花”要用“给”，不能用“被”；“被苹果花授粉”会使苹果花变成施动者，与句意相反。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '882a0bcb-908b-47d8-af67-d883598ad1ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13806, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "蜜蜂正在给草莓花授粉了。", "corrected_sentence": "蜜蜂正在给草莓花授粉。", "error_description": "体标错误：“正在”表示动作进行中，不能再在“授粉”后加表示完成的“了”，应删去“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '882a0bcb-908b-47d8-af67-d883598ad1ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
