INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13810, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "携带或引导到某处。", "primary_collocate": null, "pronunciation": "dài dào", "ipa": "tai˥˩ tau˥˩", "syllable_count": 2, "sentences": [{"text": "许多植物需要授粉才能结果，而蜜蜂在采集花蜜时，会把花粉从一朵花带到另一朵花，这个过程叫做授粉。", "target_word": "带到", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "风把花粉带到很远的地方。", "target_word": "带到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这本书带到教室。", "target_word": "带到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水把小船带到了海边。", "target_word": "带到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把朋友带到自己家里。", "target_word": "带到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把学生带到图书馆去看书。", "target_word": "带到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸟儿把种子带到别的山上。", "target_word": "带到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把这封信带到邮局。", "target_word": "带到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把我带到公园玩。", "target_word": "带到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路能把我们带到山顶。", "target_word": "带到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "带到了", "label": "体标"}, {"form": "带到过", "label": "体标"}], "register": "中性", "sense_fingerprint": "带到：携带或引导到某处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d5bd87a-e772-4fff-ab41-ecf10ff578c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13810, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "带到", "is_correct": true, "explanation": "正确：带到，dài dào，意思是把人或东西带往某处。"}, {"text": "带刀", "is_correct": false, "explanation": "dāo（第一声）与 dào（第四声）声调不同，“带刀”的意思是携带刀子，与“带到”的第二个音节不同。"}, {"text": "逮到", "is_correct": false, "explanation": "dǎi（第三声）与 dài（第四声）声调不同，“逮到”的意思是抓住，与“带到”的第一个音节不同。"}, {"text": "大道", "is_correct": false, "explanation": "dà 与 dài 的韵母不同（a 与 ai），“大道”的意思是大路，与“带到”的第一个音节不同。"}], "explanations": {"带到": "正确：带到，dài dào，意思是把人或东西带往某处。", "带刀": "dāo（第一声）与 dào（第四声）声调不同，“带刀”的意思是携带刀子，与“带到”的第二个音节不同。", "逮到": "dǎi（第三声）与 dài（第四声）声调不同，“逮到”的意思是抓住，与“带到”的第一个音节不同。", "大道": "dà 与 dài 的韵母不同（a 与 ai），“大道”的意思是大路，与“带到”的第一个音节不同。"}, "sentence_index": null, "correct_answer": "带到"}, "level_3": {"options": [{"text": "带到", "is_correct": true, "explanation": "正确：“把花粉从一朵花带到另一朵花”，表示把花粉携带到另一朵花上。"}, {"text": "飞到", "is_correct": false, "explanation": "配价：“飞”是不及物动词，不能带“把”字宾语，不能说“把花粉飞到另一朵花”。"}, {"text": "跳到", "is_correct": false, "explanation": "配价：“跳”没有使物体转移的用法，不能说“把花粉跳到另一朵花”。"}, {"text": "摘到", "is_correct": false, "explanation": "语义：“摘”是从植株上取下，不表示把花粉转移到另一朵花。"}], "explanations": {"带到": "正确：“把花粉从一朵花带到另一朵花”，表示把花粉携带到另一朵花上。", "飞到": "配价：“飞”是不及物动词，不能带“把”字宾语，不能说“把花粉飞到另一朵花”。", "跳到": "配价：“跳”没有使物体转移的用法，不能说“把花粉跳到另一朵花”。", "摘到": "语义：“摘”是从植株上取下，不表示把花粉转移到另一朵花。"}, "sentence_index": 0, "correct_answer": "带到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这项政策带到了很大的变化。", "explanation": "这里应该用〈带来〉。带到指把人或东西送往某处，引起变化、结果要用〈带来〉。"}, {"text": "我终于带到了那份奖学金。", "explanation": "这里应该用〈拿到〉。带到表示携带到某处，获得奖学金要用〈拿到〉。"}, {"text": "这次大雨带到了很多损失。", "explanation": "这里应该用〈造成〉。带到不能引出“损失”这类结果，产生损失要用〈造成〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fca93829-67fb-4877-966a-46fdd516aa95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13810, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "带到", "is_correct": true, "explanation": "正确：“鸟儿把种子带到别的山上”，表示种子随鸟转移到别处。"}, {"text": "寄到", "is_correct": false, "explanation": "搭配：“寄”指通过邮递发送，不能说鸟儿“寄”种子。"}, {"text": "扛到", "is_correct": false, "explanation": "语义：“扛”需要用肩膀负重，鸟儿不能扛种子。"}, {"text": "押到", "is_correct": false, "explanation": "语义：“押”指押送或扣押，带有强制意味，不符合鸟儿运送种子的情境。"}], "explanations": {"带到": "正确：“鸟儿把种子带到别的山上”，表示种子随鸟转移到别处。", "寄到": "搭配：“寄”指通过邮递发送，不能说鸟儿“寄”种子。", "扛到": "语义：“扛”需要用肩膀负重，鸟儿不能扛种子。", "押到": "语义：“押”指押送或扣押，带有强制意味，不符合鸟儿运送种子的情境。"}, "sentence_index": 6, "correct_answer": "带到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个消息带到了大家的关注。", "explanation": "这里应该用〈引起〉。带到表示携带到某处，引发关注要用〈引起〉。"}, {"text": "这份坚持带到了应有的回报。", "explanation": "这里应该用〈得到〉。带到不用于获得回报，获得回报要用〈得到〉。"}, {"text": "这次比赛带到了好成绩。", "explanation": "这里应该用〈取得〉。带到表示携带，不表示获得成绩，取得成绩要用〈取得〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fca93829-67fb-4877-966a-46fdd516aa95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13810, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "下课后请把作业带到了办公室。", "corrected_sentence": "下课后请把作业带到办公室。", "error_description": "错误在于“带到”后面多加了“了”。“请”表示祈使，要求对方将来去做，“了”表示动作已经完成，二者矛盾；应说“下课后请把作业带到办公室”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fca93829-67fb-4877-966a-46fdd516aa95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13810, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨天妈妈我带到了医院。", "corrected_sentence": "昨天妈妈把我带到了医院。", "error_description": "错误在于漏掉“把”：把字句中“把”须放在宾语“我”前，漏掉后“妈妈我带到了医院”不成句，应为“昨天妈妈把我带到了医院”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fca93829-67fb-4877-966a-46fdd516aa95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13812, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '882a0bcb-908b-47d8-af67-d883598ad1ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13812, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '882a0bcb-908b-47d8-af67-d883598ad1ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13812, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指杏子核仁或杏仁树的种子，可食用或药用。", "primary_collocate": null, "pronunciation": "xìng rén", "ipa": "ɕiŋ˥˩ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "从苹果、杏仁到咖啡与可可，这些人类饮食结构中的重要组成部分，其产量与质量皆深刻受制于蜂类活动的稳定性。", "target_word": "杏仁", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "例如，苹果、杏仁和蓝莓等作物，大部分都要靠蜜蜂来帮助繁殖。", "target_word": "杏仁", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "我早上喝牛奶，吃了几颗杏仁。", "target_word": "杏仁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在蛋糕上放了很多杏仁。", "target_word": "杏仁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中医说，杏仁可以当药，能帮助止咳。", "target_word": "杏仁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种杏仁有点苦，不能多吃。", "target_word": "杏仁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对杏仁过敏，一吃就会难受。", "target_word": "杏仁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里卖的杏仁，是用来当零食的。", "target_word": "杏仁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把杏仁放进热水里，皮就很容易剥下来。", "target_word": "杏仁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杏子里面的核打开以后，就能看到杏仁。", "target_word": "杏仁", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一颗杏仁", "label": "量词"}, {"form": "甜杏仁", "label": "复合"}], "register": "中性", "sense_fingerprint": "杏仁：杏核里的种子，可食用或入药", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d653fec-04d6-4c8b-893f-33391eee6ee0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13812, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "杏仁", "is_correct": true, "explanation": "杏仁：杏核里的种子，可食用或入药。"}, {"text": "行人", "is_correct": false, "explanation": "xíng（第二声）与 xìng（第四声）声调不同，行人指步行的人。"}, {"text": "新人", "is_correct": false, "explanation": "xīn（第一声）与 xìng 的韵尾（-n 与 -ng）和声调都不同，新人指新加入或新婚的人。"}, {"text": "杏林", "is_correct": false, "explanation": "杏林与杏仁只差第二音节（l 与 r 声母不同，声调相同），杏林指杏树林，也比喻医学界。"}], "explanations": {"杏仁": "杏仁：杏核里的种子，可食用或入药。", "行人": "xíng（第二声）与 xìng（第四声）声调不同，行人指步行的人。", "新人": "xīn（第一声）与 xìng 的韵尾（-n 与 -ng）和声调都不同，新人指新加入或新婚的人。", "杏林": "杏林与杏仁只差第二音节（l 与 r 声母不同，声调相同），杏林指杏树林，也比喻医学界。"}, "sentence_index": null, "correct_answer": "杏仁"}, "level_3": {"options": [{"text": "杏仁", "is_correct": true, "explanation": "正确：与“苹果”“咖啡”“可可”并列，都是饮食中的食材。"}, {"text": "显微镜", "is_correct": false, "explanation": "语义：显微镜不是食材，与“饮食结构”的语境不符。"}, {"text": "地铁", "is_correct": false, "explanation": "搭配：地铁不能与苹果、咖啡并列作食物。"}, {"text": "足球", "is_correct": false, "explanation": "语义：足球不属于饮食结构，无法与前面的食物并列。"}], "explanations": {"杏仁": "正确：与“苹果”“咖啡”“可可”并列，都是饮食中的食材。", "显微镜": "语义：显微镜不是食材，与“饮食结构”的语境不符。", "地铁": "搭配：地铁不能与苹果、咖啡并列作食物。", "足球": "语义：足球不属于饮食结构，无法与前面的食物并列。"}, "sentence_index": 0, "correct_answer": "杏仁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "奶奶晒的杏仁软软的，酸酸甜甜，我最爱吃。", "explanation": "这里应该用〈杏干〉。杏仁是硬的种子；晒过后软软甜甜的果肉要说杏干。"}, {"text": "这棵杏仁长得很高，每年春天都开满白花。", "explanation": "这里应该用〈杏树〉。杏仁是种子，不会长成高树，也不会开花。"}, {"text": "我吃完杏子，把杏仁扔进了垃圾桶，嫌它又硬又大。", "explanation": "这里应该用〈杏核〉。杏核是包着杏仁的硬壳，又硬又大要说杏核；杏仁是核里的种子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '882a0bcb-908b-47d8-af67-d883598ad1ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13812, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "杏仁", "is_correct": true, "explanation": "正确：“对……过敏，一吃就会难受”的对象应是可食用的东西。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不能吃，“一吃就会难受”与它的性质相悖。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：“一吃”要求对象可食用，钢琴不能与之搭配。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能食用，与“一吃就会难受”的语境矛盾。"}], "explanations": {"杏仁": "正确：“对……过敏，一吃就会难受”的对象应是可食用的东西。", "汽车": "语义：汽车不能吃，“一吃就会难受”与它的性质相悖。", "钢琴": "搭配：“一吃”要求对象可食用，钢琴不能与之搭配。", "石头": "语义：石头不能食用，与“一吃就会难受”的语境矛盾。"}, "sentence_index": 6, "correct_answer": "杏仁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "杏仁正在枝头上盛开，香气很浓。", "explanation": "这里应该用〈杏花〉。杏仁是果核里的种子，不会在枝头盛开；枝头盛开、香气浓郁的是杏花。"}, {"text": "这颗杏仁又软又甜，刚从树上长出来。", "explanation": "这里应该用〈杏子〉。软甜、长在树上是果实的特点，杏仁指核里的种子。"}, {"text": "秋天到了，这些杏仁变黄了，可以收回家了。", "explanation": "这里应该用〈杏子〉。变黄和收获是果实的变化，杏仁不会这样变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '882a0bcb-908b-47d8-af67-d883598ad1ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13812, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天吃了一只杏仁。", "corrected_sentence": "我昨天吃了一颗杏仁。", "error_description": "错误形式：“吃了一只杏仁”；正确形式：“吃了一颗杏仁”。杏仁的量词应用“颗”，“只”一般用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '882a0bcb-908b-47d8-af67-d883598ad1ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13812, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一颗很香杏仁。", "corrected_sentence": "这是一颗很香的杏仁。", "error_description": "结构错误：“很香”修饰“杏仁”，中间要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '882a0bcb-908b-47d8-af67-d883598ad1ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
