INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13819, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fca93829-67fb-4877-966a-46fdd516aa95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13819, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "为了见到或得到某人或某物而付出努力。", "primary_collocate": null, "pronunciation": "xún zhǎo", "ipa": "ɕyn˧˥ ʈʂɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "许多研究正在寻找原因，可能包括农药的使用、栖息地的减少以及气候变化。", "target_word": "寻找", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "小狗走丢了，孩子们到处寻找。", "target_word": "寻找", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天都在寻找一份新工作。", "target_word": "寻找", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察正在寻找那个丢失的孩子。", "target_word": "寻找", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们一直在寻找回家的路。", "target_word": "寻找", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她寻找了很久，终于找到了钥匙。", "target_word": "寻找", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多年轻人去大城市寻找机会。", "target_word": "寻找", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在书包里寻找着那把小钥匙。", "target_word": "寻找", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家们正在寻找新的能源。", "target_word": "寻找", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他寻找过很多地方，都没有看到那只猫。", "target_word": "寻找", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "寻找了", "label": "完成体"}, {"form": "寻找着", "label": "持续体"}, {"form": "寻找过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "努力去找某人或某物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d5bd87a-e772-4fff-ab41-ecf10ff578c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13819, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "丢失", "is_correct": false, "explanation": "语义：“丢失”是失去东西，研究不会把原因丢失，与“正在”后的动作矛盾。"}, {"text": "寻找", "is_correct": true, "explanation": "“寻找”指为了得到某物而努力去找，与“研究正在……原因”的语境相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能带“原因”作宾语。"}, {"text": "帮助", "is_correct": false, "explanation": "配价：“帮助”要求带人作宾语，不能说“帮助原因”。"}], "explanations": {"丢失": "语义：“丢失”是失去东西，研究不会把原因丢失，与“正在”后的动作矛盾。", "寻找": "“寻找”指为了得到某物而努力去找，与“研究正在……原因”的语境相符。", "吃": "搭配：“吃”不能带“原因”作宾语。", "帮助": "配价：“帮助”要求带人作宾语，不能说“帮助原因”。"}, "sentence_index": 0, "correct_answer": "寻找"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他寻找了对老师的感谢。", "explanation": "这里应该用〈表达〉。寻找的对象是能去找到的人或东西，感谢是要表达的情感，应说“表达感谢”。"}, {"text": "他寻找了一个小时的头疼。", "explanation": "这里误把〈寻找〉当成“感受”来用。寻找的对象要是能找到的人或东西；头疼是身体感受，应说“感到”或“忍受”。"}, {"text": "妈妈寻找了我的生日。", "explanation": "这里应该用〈庆祝〉。寻找的对象是能找到的人或东西，生日是要庆祝的日子，应说“庆祝生日”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fca93829-67fb-4877-966a-46fdd516aa95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13819, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”是不再努力，与“去大城市”的目的矛盾。"}, {"text": "寻找", "is_correct": true, "explanation": "“寻找”指为了得到而努力去找，与“去大城市”的语境相符。"}, {"text": "抚养", "is_correct": false, "explanation": "搭配：“抚养”的宾语是人，不能说“抚养机会”。"}, {"text": "错过", "is_correct": false, "explanation": "语义：“错过”是失去时机，与“去大城市”的目的矛盾。"}], "explanations": {"放弃": "语义：“放弃”是不再努力，与“去大城市”的目的矛盾。", "寻找": "“寻找”指为了得到而努力去找，与“去大城市”的语境相符。", "抚养": "搭配：“抚养”的宾语是人，不能说“抚养机会”。", "错过": "语义：“错过”是失去时机，与“去大城市”的目的矛盾。"}, "sentence_index": 6, "correct_answer": "寻找"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "护士寻找了病人的体温。", "explanation": "这里应该用〈量〉。寻找的对象是能找到的人或东西，体温要用“量”来测。"}, {"text": "天空寻找了一场大雨。", "explanation": "这里应该用〈下〉。寻找的对象是人或东西，大雨是天气现象，应说“下大雨”。"}, {"text": "大家寻找了一首生日歌给她听。", "explanation": "这里应该用〈唱〉。寻找的对象是要去找的人或东西；给人听的歌要“唱”，应说“唱了一首生日歌”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fca93829-67fb-4877-966a-46fdd516aa95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13819, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在桌子上寻找了着遥控器。", "corrected_sentence": "他在桌子上寻找着遥控器。", "error_description": "错误在于体标叠加：持续体只用“着”，“了”和“着”不能同时放在动词“寻找”后，应说“寻找着遥控器”，不能说“寻找了着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fca93829-67fb-4877-966a-46fdd516aa95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13819, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在书架上寻找得那本字典。", "corrected_sentence": "他在书架上寻找那本字典。", "error_description": "错误在于多加了“得”：“寻找”后直接带宾语“那本字典”，不用“得”，应说“在书架上寻找那本字典”，不能说“寻找得那本字典”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fca93829-67fb-4877-966a-46fdd516aa95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13820, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '882a0bcb-908b-47d8-af67-d883598ad1ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13820, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '882a0bcb-908b-47d8-af67-d883598ad1ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13820, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种用于防治农作物病虫害的化学药剂。", "primary_collocate": null, "pronunciation": "nóng yào", "ipa": "nʊŋ˧˥ jaʊ˥˩", "syllable_count": 2, "sentences": [{"text": "栖息地碎片化、农药滥用、气候变化以及外来物种入侵，正在协同加速蜜蜂种群的衰退，进而威胁整个陆地生态系统的功能完整性。", "target_word": "农药", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "某些国家已启动“授粉者保护区”计划，通过立法限制特定神经毒性农药的使用，并鼓励农场主采用生态友好型耕作方式。", "target_word": "农药", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "许多研究正在寻找原因，可能包括农药的使用、栖息地的减少以及气候变化。", "target_word": "农药", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "为了保护蜜蜂，一些农民开始减少使用化学农药，转而采用更环保的种植方式。", "target_word": "农药", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "农民在田里喷农药，杀死了害虫。", "target_word": "农药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种农药对人和动物都不安全。", "target_word": "农药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃水果前要洗干净，不然可能残留农药。", "target_word": "农药", "complexity_tier": "T3", "furigana": "chī shuǐguǒ qián yào xǐ gānjìng, bùrán kěnéng cánliú nóngyào.", "sentence_source": "generated"}, {"text": "农民买了两瓶农药，准备喷在菜地里。", "target_word": "农药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们不用农药，只用天然的办法对付害虫。", "target_word": "农药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用太多农药，会让土地受到伤害。", "target_word": "农药", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一瓶农药", "label": "量词"}, {"form": "化学农药", "label": "复合"}, {"form": "農藥", "label": "繁体"}], "register": "中性", "sense_fingerprint": "农药：防治农作物病虫害的化学药剂", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d653fec-04d6-4c8b-893f-33391eee6ee0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13820, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蜜蜂", "is_correct": false, "explanation": "语义：蜜蜂是被威胁的生物，不能被“滥用”，句中“滥用”的对象应是化学物质。"}, {"text": "农药", "is_correct": true, "explanation": "农药：防治农作物病虫害的化学药剂。“农药滥用”指过量或不当使用农药，是句中加速蜜蜂衰退的原因之一。"}, {"text": "化石", "is_correct": false, "explanation": "语义：化石是古代生物的遗迹，不能被“滥用”，与句中的生态威胁无关。"}, {"text": "矿石", "is_correct": false, "explanation": "搭配：“滥用”多接药物、权力、资源，不说“矿石滥用”。"}], "explanations": {"蜜蜂": "语义：蜜蜂是被威胁的生物，不能被“滥用”，句中“滥用”的对象应是化学物质。", "农药": "农药：防治农作物病虫害的化学药剂。“农药滥用”指过量或不当使用农药，是句中加速蜜蜂衰退的原因之一。", "化石": "语义：化石是古代生物的遗迹，不能被“滥用”，与句中的生态威胁无关。", "矿石": "搭配：“滥用”多接药物、权力、资源，不说“矿石滥用”。"}, "sentence_index": 0, "correct_answer": "农药"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生给发烧的病人开了一种新农药，吃完很快就退烧了。", "explanation": "这里应该用〈药物〉。农药只用于防治农作物病虫害，不能用来给人治病。"}, {"text": "我用农药洗衣服，衣服很快就干净了。", "explanation": "这里应该用〈洗衣粉〉。农药是用来杀虫的，有毒，不能用来洗衣服。"}, {"text": "他很喜欢吃农药，每天都要吃一点。", "explanation": "这里应该用〈糖〉。农药有毒，人不能吃；糖是常见的可以当零食吃的食品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '882a0bcb-908b-47d8-af67-d883598ad1ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13820, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴是乐器，不会残留在水果上，句中指的是沾在水果上的化学物质。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“残留”指留下的物质或痕迹，不说“残留歌曲”。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不会沾在水果上形成残留，与“洗干净”的语境不符。"}, {"text": "农药", "is_correct": true, "explanation": "农药：防治病虫害的化学药剂。水果上残留的是农药，所以吃之前要洗干净。"}], "explanations": {"钢琴": "语义：钢琴是乐器，不会残留在水果上，句中指的是沾在水果上的化学物质。", "歌曲": "搭配：“残留”指留下的物质或痕迹，不说“残留歌曲”。", "手机": "语义：手机不会沾在水果上形成残留，与“洗干净”的语境不符。", "农药": "农药：防治病虫害的化学药剂。水果上残留的是农药，所以吃之前要洗干净。"}, "sentence_index": 6, "correct_answer": "农药"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民在地里撒了一大袋农药，让庄稼长得更壮。", "explanation": "这里应该用〈化肥〉。农药是用来杀虫的，让庄稼长得更壮要用化肥，不能用农药。"}, {"text": "秋天收完粮食，农民把农药装进袋子里，拿去喂牛。", "explanation": "这里应该用〈饲料〉。农药有毒，不能拿来喂牛；喂牛要用饲料。"}, {"text": "春天到了，农民把农药装进播种机，准备种在地里。", "explanation": "这里应该用〈种子〉。农药是用来杀虫的，不能装进播种机种在地里；播种要用种子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '882a0bcb-908b-47d8-af67-d883598ad1ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13820, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他去年过用农药，后来就不用了。", "corrected_sentence": "他去年用过农药，后来就不用了。", "error_description": "语序错误：“过”放在了动词“用”之前。“过”应紧跟动词，写作“用过农药”，表示曾经有过这种经历；“过用农药”不说。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '882a0bcb-908b-47d8-af67-d883598ad1ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13820, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "仓库里有一只农药，别让孩子碰。", "corrected_sentence": "仓库里有一袋农药，别让孩子碰。", "error_description": "量词错误：“农药”应用“袋”“瓶”等计量，“只”用于动物等，不能用来数农药，应为“一袋农药”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '882a0bcb-908b-47d8-af67-d883598ad1ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13821, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有利于", "is_correct": true, "explanation": "反义：“有利于”与“不利于”对事物的影响方向相反，词典列为反义词。"}, {"text": "保持", "is_correct": false, "explanation": "无关：“保持”指维持原状，与“不利于”没有反义关系。"}, {"text": "讨论", "is_correct": false, "explanation": "无关：“讨论”指交换意见，与“不利于”没有反义关系。"}, {"text": "购买", "is_correct": false, "explanation": "无关：“购买”指花钱获得物品，与“不利于”没有反义关系。"}], "correct_answer": "有利于", "explanations": {"有利于": "反义：“有利于”与“不利于”对事物的影响方向相反，词典列为反义词。", "保持": "无关：“保持”指维持原状，与“不利于”没有反义关系。", "讨论": "无关：“讨论”指交换意见，与“不利于”没有反义关系。", "购买": "无关：“购买”指花钱获得物品，与“不利于”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba75fc5-0637-4944-9c4b-532ed38d3d17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13821, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有利于", "is_correct": true, "explanation": "反义：“有利于”与“不利于”对事物的影响方向相反，词典列为反义词。"}, {"text": "介绍", "is_correct": false, "explanation": "无关：“介绍”指向别人说明情况，与“不利于”没有反义关系。"}, {"text": "修理", "is_correct": false, "explanation": "无关：“修理”指把坏的东西弄好，与“不利于”没有反义关系。"}, {"text": "思考", "is_correct": false, "explanation": "无关：“思考”指用脑子考虑问题，与“不利于”没有反义关系。"}], "correct_answer": "有利于", "explanations": {"有利于": "反义：“有利于”与“不利于”对事物的影响方向相反，词典列为反义词。", "介绍": "无关：“介绍”指向别人说明情况，与“不利于”没有反义关系。", "修理": "无关：“修理”指把坏的东西弄好，与“不利于”没有反义关系。", "思考": "无关：“思考”指用脑子考虑问题，与“不利于”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba75fc5-0637-4944-9c4b-532ed38d3d17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13821, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "表示对某事物产生负面作用或阻碍", "primary_collocate": null, "pronunciation": "bù lì yú", "ipa": "pu˥˩ li˥˩ y˧˥", "syllable_count": 3, "sentences": [{"text": "生物多样性的下降也让情况变得更严重，因为单一的环境不利于蜜蜂和其他传粉昆虫的生存。", "target_word": "不利于", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "熬夜不利于身体健康。", "target_word": "不利于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "太吵的环境不利于学习。", "target_word": "不利于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "吃太多糖不利于牙齿健康。", "target_word": "不利于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "总是坐着不动，不利于身体。", "target_word": "不利于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡前玩手机不利于睡个好觉。", "target_word": "不利于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这样的天气不利于农作物生长。", "target_word": "不利于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "空气不好，不利于孩子成长。", "target_word": "不利于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司内部不团结，不利于长期发展。", "target_word": "不利于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "压力太大不利于工作，也不利于生活。", "target_word": "不利于", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "有利于", "label": "反义词"}, {"form": "不利", "label": "简略形式"}], "register": "中性偏书面", "sense_fingerprint": "对某事物产生负面作用或阻碍，后接名词或动词短语，如不利于健康", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '911ce2b6-7d1d-4794-8ddb-56c9662d33c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13821, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不利于", "is_correct": true, "explanation": "正确：单一的环境对蜜蜂等传粉昆虫的生存产生负面作用，与“情况变得更严重”的语境一致。"}, {"text": "有利于", "is_correct": false, "explanation": "语义：“有利于”表示好处，与前句“情况变得更严重”矛盾。"}, {"text": "促进", "is_correct": false, "explanation": "语义：“促进”表示推动，说单一的环境促进生存，与“更严重”的语境相反。"}, {"text": "缩短", "is_correct": false, "explanation": "搭配：“缩短”的对象是时间或距离，不能说“缩短……的生存”。"}], "explanations": {"不利于": "正确：单一的环境对蜜蜂等传粉昆虫的生存产生负面作用，与“情况变得更严重”的语境一致。", "有利于": "语义：“有利于”表示好处，与前句“情况变得更严重”矛盾。", "促进": "语义：“促进”表示推动，说单一的环境促进生存，与“更严重”的语境相反。", "缩短": "搭配：“缩短”的对象是时间或距离，不能说“缩短……的生存”。"}, "sentence_index": 0, "correct_answer": "不利于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他总是不利于我们的讨论。", "explanation": "这里应该用〈妨碍〉。“不利于”说条件或做法对事物的不良影响，不用来形容某人主动阻挠别人的讨论。"}, {"text": "父母不利于孩子的梦想。", "explanation": "这里应该用〈反对〉。“不利于”强调客观条件的影响，不用来形容长辈主动否定晚辈的想法。"}, {"text": "这块石头不利于我的脚步。", "explanation": "这里应该用〈阻挡〉。“不利于”是抽象的不良影响，不用于具体物体挡住人的行走。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba75fc5-0637-4944-9c4b-532ed38d3d17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13821, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不利于", "is_correct": true, "explanation": "正确：这样的天气对农作物的生长产生负面影响，与语境一致。"}, {"text": "打扰", "is_correct": false, "explanation": "搭配：“打扰”指妨碍别人做事，对象是人，不能说“天气打扰农作物生长”。"}, {"text": "捣乱", "is_correct": false, "explanation": "语域：“捣乱”口语色彩浓，用于书面的农业描述不合适，且不能接“生长”。"}, {"text": "检测", "is_correct": false, "explanation": "语义：天气不能“检测”，主语与动词搭配不合理。"}], "explanations": {"不利于": "正确：这样的天气对农作物的生长产生负面影响，与语境一致。", "打扰": "搭配：“打扰”指妨碍别人做事，对象是人，不能说“天气打扰农作物生长”。", "捣乱": "语域：“捣乱”口语色彩浓，用于书面的农业描述不合适，且不能接“生长”。", "检测": "语义：天气不能“检测”，主语与动词搭配不合理。"}, "sentence_index": 6, "correct_answer": "不利于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老板不利于员工的请假。", "explanation": "这里应该用〈批准〉。“不利于”说条件对事物有不良影响，不用来说某人作出的审批决定。"}, {"text": "这只狗不利于我的手。", "explanation": "这里应该用〈咬伤〉。“不利于”说条件或做法造成的不良影响，直接对身体造成伤害要用“咬伤”，不能说“不利于手”。"}, {"text": "妈妈不利于我的玩耍。", "explanation": "这里应该用〈阻拦〉。“不利于”用于条件或做法的不良影响，不用于形容家长主动阻拦孩子玩耍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba75fc5-0637-4944-9c4b-532ed38d3d17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13821, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "长期缺乏运动不利于了身体健康。", "corrected_sentence": "长期缺乏运动不利于身体健康。", "error_description": "错误：“不利于”后面多加了“了”。正确：“不利于”是动词，后面直接接宾语，“于”之后不能加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba75fc5-0637-4944-9c4b-532ed38d3d17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13821, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "过度使用手机不利于对视力。", "corrected_sentence": "过度使用手机不利于视力。", "error_description": "错误：“不利于”后面的宾语“视力”前多加了介词“对”。正确：“不利于”直接带宾语，写成“不利于视力”，不能说“不利于对视力”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba75fc5-0637-4944-9c4b-532ed38d3d17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13822, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7392bf12-981c-4536-b27f-a87304bb7884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13822, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7392bf12-981c-4536-b27f-a87304bb7884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13822, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "雄蕊的花粉借助风或昆虫等媒介传递到雌蕊柱头上的过程。", "primary_collocate": null, "pronunciation": "chuán fěn", "ipa": "tʂʰwan˧˥ fən˨˩˦", "syllable_count": 2, "sentences": [{"text": "事实上，全球约75%的农作物种类在不同程度上依赖动物授粉，而蜜蜂正是其中占比最高的传粉媒介。", "target_word": "传粉", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "环境变差以后，能帮花传粉的昆虫越来越少了。", "target_word": "传粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜜蜂在花丛中飞来飞去，帮花传粉。", "target_word": "传粉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风也可以帮助植物传粉。", "target_word": "传粉", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "春天，蝴蝶和蜜蜂忙着给果树传粉。", "target_word": "传粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些花靠风传粉，有些花靠昆虫传粉。", "target_word": "传粉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨天，蜜蜂不出门，花就很难传粉。", "target_word": "传粉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民在果园里放了蜂箱，让蜜蜂传粉。", "target_word": "传粉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种花的传粉工作主要靠夜里的蛾子。", "target_word": "传粉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蜜蜂传粉以后，花才会结出果实。", "target_word": "传粉", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "传粉者", "label": "复合"}, {"form": "传粉昆虫", "label": "复合"}, {"form": "傳粉", "label": "繁体"}], "register": "中性", "sense_fingerprint": "植物学：花粉借风或昆虫从雄蕊传到雌蕊柱头的过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b139446e-7524-4719-8232-ba3bfc86546e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13822, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "传粉", "is_correct": true, "explanation": "正确：“传粉”指花粉借媒介传到雌蕊柱头，修饰“媒介”，说明蜜蜂是传粉的媒介。"}, {"text": "传染", "is_correct": false, "explanation": "语义：“传染”指疾病或病菌的传播，与蜜蜂为农作物授粉的语境不符。"}, {"text": "繁殖", "is_correct": false, "explanation": "搭配：“繁殖”指生物生育后代，不能修饰“媒介”，不说“繁殖媒介”。"}, {"text": "吸引", "is_correct": false, "explanation": "语义：“吸引”指引起注意或产生吸引力，与花粉的转移无关，“吸引媒介”不合句意。"}], "explanations": {"传粉": "正确：“传粉”指花粉借媒介传到雌蕊柱头，修饰“媒介”，说明蜜蜂是传粉的媒介。", "传染": "语义：“传染”指疾病或病菌的传播，与蜜蜂为农作物授粉的语境不符。", "繁殖": "搭配：“繁殖”指生物生育后代，不能修饰“媒介”，不说“繁殖媒介”。", "吸引": "语义：“吸引”指引起注意或产生吸引力，与花粉的转移无关，“吸引媒介”不合句意。"}, "sentence_index": 0, "correct_answer": "传粉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "流感病毒主要通过飞沫传粉。", "explanation": "这里应该用〈传染〉。传粉专指花粉从雄蕊传到雌蕊的植物授粉过程，病毒经飞沫扩散要用传染。"}, {"text": "他把这份材料传粉给了老师。", "explanation": "这里应该用〈传递〉。传粉只指植物花粉的转移，不能用于文件、材料等物品。"}, {"text": "新闻通过网络迅速传粉。", "explanation": "这里应该用〈传播〉。传粉只指花粉从雄蕊传到雌蕊的转移，不用于新闻、信息等的扩散。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7392bf12-981c-4536-b27f-a87304bb7884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13822, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "传粉", "is_correct": true, "explanation": "正确：“花就很难传粉”说下雨时蜜蜂不出门，花难以完成花粉的转移，“传粉”符合句意。"}, {"text": "迁徙", "is_correct": false, "explanation": "语义：“迁徙”指动物成群远行，花不能迁徙，句意不通。"}, {"text": "飞行", "is_correct": false, "explanation": "语义：“飞行”需要能动的主体，花不会飞行，与下雨天蜜蜂不出门的语境无关。"}, {"text": "采蜜", "is_correct": false, "explanation": "配价：“采蜜”要求蜜蜂等动物作施事，花不能采蜜，“花就很难采蜜”不合常理。"}], "explanations": {"传粉": "正确：“花就很难传粉”说下雨时蜜蜂不出门，花难以完成花粉的转移，“传粉”符合句意。", "迁徙": "语义：“迁徙”指动物成群远行，花不能迁徙，句意不通。", "飞行": "语义：“飞行”需要能动的主体，花不会飞行，与下雨天蜜蜂不出门的语境无关。", "采蜜": "配价：“采蜜”要求蜜蜂等动物作施事，花不能采蜜，“花就很难采蜜”不合常理。"}, "sentence_index": 6, "correct_answer": "传粉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种颜料很快就在墙上传粉了。", "explanation": "这里的“传粉”被误用为“涂抹、扩散”的意思。传粉只指花粉从雄蕊传到雌蕊，颜料不是花粉，墙面也没有雌蕊柱头。"}, {"text": "这股暖流很快就在海面上传粉了。", "explanation": "这里的“传粉”被误用为“流动、扩散”的意思。传粉只指花粉的传递，暖流不是花粉，海面上也没有花。"}, {"text": "这次寒潮很快就在城市里传粉了。", "explanation": "这里的“传粉”被误用为“蔓延、扩散”的意思。传粉只指植物花粉的传递，寒潮是天气现象，城市不是授粉的对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7392bf12-981c-4536-b27f-a87304bb7884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13822, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "蜜蜂整个春天都在果园里了传粉。", "corrected_sentence": "蜜蜂整个春天都在果园里传粉。", "error_description": "“了”误置于“果园里”与动词“传粉”之间。“了”表示完成或变化，不能插在处所状语与动词之间，应删去，写作“都在果园里传粉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7392bf12-981c-4536-b27f-a87304bb7884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13822, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "蜜蜂每天都把花传粉。", "corrected_sentence": "蜜蜂每天都给花传粉。", "error_description": "介词误用：“传粉”是不及物动词，不能用“把”带宾语，应改为“给花传粉”，用介词“给”引出受益的花。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7392bf12-981c-4536-b27f-a87304bb7884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
