INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13823, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用于防治农业病虫害、杂草等的化学合成物质。", "primary_collocate": null, "pronunciation": "huà xué nóng yào", "ipa": "xua˥˩ ɕɥe˧˥ noŋ˧˥ jɑʊ˥˩", "syllable_count": 4, "sentences": [{"text": "为了保护蜜蜂，一些农民开始减少使用化学农药，转而采用更环保的种植方式。", "target_word": "化学农药", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "农民在地里喷了化学农药。", "target_word": "化学农药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "化学农药能杀死害虫，也会伤到蜜蜂。", "target_word": "化学农药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种化学农药对人不太好。", "target_word": "化学农药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不想再用化学农药种菜了。", "target_word": "化学农药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买化学农药的时候要看清楚说明。", "target_word": "化学农药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "用了化学农药的菜，要多洗几次。", "target_word": "化学农药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店卖种子，也卖化学农药。", "target_word": "化学农药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子不能碰化学农药，很危险。", "target_word": "化学农药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "化学农药用得太多，河水也会变脏。", "target_word": "化学农药", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "农药", "label": "简称"}, {"form": "种", "label": "量词"}, {"form": "瓶", "label": "量词"}], "register": "中性", "sense_fingerprint": "农业中用来防治病虫害和杂草的化学合成药剂，可喷洒使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '911ce2b6-7d1d-4794-8ddb-56c9662d33c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13823, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "化学农药", "is_correct": true, "explanation": "正确：减少使用它，转而采用更环保的种植方式，与“保护蜜蜂”的语境一致。"}, {"text": "有机肥", "is_correct": false, "explanation": "语义：有机肥本身也是环保的，减少使用它不能“转而采用更环保的种植方式”，与语境矛盾。"}, {"text": "太阳能", "is_correct": false, "explanation": "语义：太阳能是清洁能源，减少使用它与“更环保”的逻辑相反。"}, {"text": "雨水", "is_correct": false, "explanation": "搭配：“雨水”一般不说“减少使用”，与“减少使用”搭配不当。"}], "explanations": {"化学农药": "正确：减少使用它，转而采用更环保的种植方式，与“保护蜜蜂”的语境一致。", "有机肥": "语义：有机肥本身也是环保的，减少使用它不能“转而采用更环保的种植方式”，与语境矛盾。", "太阳能": "语义：太阳能是清洁能源，减少使用它与“更环保”的逻辑相反。", "雨水": "搭配：“雨水”一般不说“减少使用”，与“减少使用”搭配不当。"}, "sentence_index": 0, "correct_answer": "化学农药"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上用化学农药刷牙。", "explanation": "这里应该用〈牙膏〉。化学农药是用来杀虫、除草的，不能用来刷牙。"}, {"text": "农民就用化学农药给庄稼施肥。", "explanation": "这里应该用〈化肥〉。化学农药是用来杀虫、除草的，不能用来施肥。"}, {"text": "医生用化学农药治感冒。", "explanation": "这里应该用〈感冒药〉。这里的“化学农药”指杀虫除草的药剂，不能用于治病。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba75fc5-0637-4944-9c4b-532ed38d3d17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13823, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "化学农药", "is_correct": true, "explanation": "正确：用过它的菜要多洗几次，与“用了……的菜”的语境一致。"}, {"text": "毒药", "is_correct": false, "explanation": "语义：“毒药”的毒性远超农药，用过毒药的菜不是多洗几次就能处理，与语境不符。"}, {"text": "冰块", "is_correct": false, "explanation": "搭配：“用了冰块的菜”不是常见说法，“用”与“冰块”搭配不当。"}, {"text": "柴油", "is_correct": false, "explanation": "语义：柴油不能用于烹饪或处理蔬菜，与“菜”的语境矛盾。"}], "explanations": {"化学农药": "正确：用过它的菜要多洗几次，与“用了……的菜”的语境一致。", "毒药": "语义：“毒药”的毒性远超农药，用过毒药的菜不是多洗几次就能处理，与语境不符。", "冰块": "搭配：“用了冰块的菜”不是常见说法，“用”与“冰块”搭配不当。", "柴油": "语义：柴油不能用于烹饪或处理蔬菜，与“菜”的语境矛盾。"}, "sentence_index": 6, "correct_answer": "化学农药"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈用化学农药给孩子洗澡。", "explanation": "这里应该用〈沐浴露〉。农药不能用于人体清洁，这里应该用专门的清洁用品。"}, {"text": "化学农药可以当作调料放进汤里。", "explanation": "这里应该用〈食盐〉。化学农药不是食用物质，不能当作调料。"}, {"text": "他用化学农药做饼干。", "explanation": "这里应该用〈面粉〉。化学农药不能用来做食物，做饼干要用面粉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba75fc5-0637-4944-9c4b-532ed38d3d17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13823, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "农民喷完着化学农药。", "corrected_sentence": "农民喷完了化学农药。", "error_description": "错误：“完”表示动作结束，后面要用“了”，不能用“着”，写成“喷完着”不对。正确：“农民喷完了化学农药”，“了”表示动作已经完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba75fc5-0637-4944-9c4b-532ed38d3d17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13823, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只化学农药太贵了。", "corrected_sentence": "这瓶化学农药太贵了。", "error_description": "错误：“只”是动物的量词，用来修饰“化学农药”不对。正确：农药多以瓶、袋计量，应说“这瓶化学农药”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba75fc5-0637-4944-9c4b-532ed38d3d17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13824, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
