INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13824, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "养蜂是指人工饲养蜜蜂，以获取蜂蜜、蜂王浆等产品。", "primary_collocate": null, "pronunciation": "yǎng fēng", "ipa": "jɑŋ˨˩˦ fɤŋ˥", "syllable_count": 2, "sentences": [{"text": "城市里也有人开始在屋顶或阳台养蜂。", "target_word": "养蜂", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "他退休以后，在山上养蜂。", "target_word": "养蜂", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "想养蜂，要先买蜂箱。", "target_word": "养蜂", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在花园里养蜂，每年都能收到蜂蜜。", "target_word": "养蜂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "养蜂的人要穿特别的衣服。", "target_word": "养蜂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷养蜂已经十年了。", "target_word": "养蜂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天花开了，农民开始养蜂。", "target_word": "养蜂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在农村养蜂，卖蜂蜜赚钱。", "target_word": "养蜂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你想学养蜂，就不能怕蜜蜂。", "target_word": "养蜂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在这个山村，很多人靠养蜂生活。", "target_word": "养蜂", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "养过蜂", "label": "体标"}, {"form": "养蜂人", "label": "复合"}, {"form": "養蜂", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人工饲养蜜蜂以获取蜂蜜等产品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '618ae9a4-f14e-4a14-a72f-8b79178904af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13824, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "放牧", "is_correct": false, "explanation": "语义：城市屋顶和阳台不宜放牧，“在屋顶或阳台放牧”与句意明显不合。"}, {"text": "滑冰", "is_correct": false, "explanation": "语义：屋顶和阳台上不能滑冰，与“城市里也有人开始”的语境不合。"}, {"text": "买", "is_correct": false, "explanation": "配价：“买”需要带宾语（买什么），“在屋顶或阳台买”缺少宾语，句子不完整。"}, {"text": "养蜂", "is_correct": true, "explanation": "正确。“养蜂”指人工饲养蜜蜂，屋顶和阳台可以放置蜂箱，与句意相合。"}], "explanations": {"放牧": "语义：城市屋顶和阳台不宜放牧，“在屋顶或阳台放牧”与句意明显不合。", "滑冰": "语义：屋顶和阳台上不能滑冰，与“城市里也有人开始”的语境不合。", "买": "配价：“买”需要带宾语（买什么），“在屋顶或阳台买”缺少宾语，句子不完整。", "养蜂": "正确。“养蜂”指人工饲养蜜蜂，屋顶和阳台可以放置蜂箱，与句意相合。"}, "sentence_index": 0, "correct_answer": "养蜂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在阳台养蜂了三只小猫。", "explanation": "这里应该用〈养〉。“养蜂”已经包含对象“蜂”，后面不能再带“小猫”；养猫应说“养了三只小猫”。"}, {"text": "他在鱼缸里养蜂，养了十条金鱼。", "explanation": "这里应该用〈养鱼〉。养蜂饲养的是蜜蜂，鱼缸里养金鱼应说养鱼。"}, {"text": "他在家里养蜂，养了一只小狗。", "explanation": "这里应该用〈养狗〉。养蜂只指饲养蜜蜂，养小狗应说养狗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13824, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冬眠", "is_correct": false, "explanation": "语义：冬眠是动物的习性，“农民开始冬眠”与“春天花开了”的语境不合。"}, {"text": "滑雪", "is_correct": false, "explanation": "语义：春天花开的季节不适合滑雪，“农民开始滑雪”与句中季节矛盾。"}, {"text": "出版", "is_correct": false, "explanation": "语义：农民开始“出版”与春天花开的语境不合；“出版”需带宾语（出版什么），句子不完整。"}, {"text": "养蜂", "is_correct": true, "explanation": "正确。“春天花开了，农民开始养蜂”，花开后正适合养蜂采蜜，句意通顺。"}], "explanations": {"冬眠": "语义：冬眠是动物的习性，“农民开始冬眠”与“春天花开了”的语境不合。", "滑雪": "语义：春天花开的季节不适合滑雪，“农民开始滑雪”与句中季节矛盾。", "出版": "语义：农民开始“出版”与春天花开的语境不合；“出版”需带宾语（出版什么），句子不完整。", "养蜂": "正确。“春天花开了，农民开始养蜂”，花开后正适合养蜂采蜜，句意通顺。"}, "sentence_index": 6, "correct_answer": "养蜂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "在这个山村，很多蜜蜂靠养蜂生活。", "explanation": "这里误用了〈养蜂〉的施事：养蜂须由人来做，蜜蜂自己做的是〈采蜜〉，不能说养蜂。"}, {"text": "在这个山村，很多鱼靠养蜂生活。", "explanation": "这里应该用〈养鱼〉。养蜂要由人来做，鱼不能养蜂。"}, {"text": "在这个山村，这块石头靠养蜂生活。", "explanation": "这里的主语是石头，石头不能养蜂；养蜂的施事须是人，换动词并不能解决主语问题。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13824, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶养蜂得很好，蜂蜜很香。", "corrected_sentence": "奶奶养蜂养得很好，蜂蜜很香。", "error_description": "补语错误：动词“养蜂”后接程度补语“得很好”时，动词须重复，应说“养蜂养得很好”，不能说“养蜂得很好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13824, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他养蜂得很好。", "corrected_sentence": "他养蜂养得很好。", "error_description": "补语错误：动词“养蜂”后接程度补语“得很好”时，动词要重复，应说“养蜂养得很好”，不能说“养蜂得很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
