INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13825, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指生物生存所需的各种外界条件的总和，包括空气、水、土壤、气候等自然因素以及社会文化等。", "primary_collocate": null, "pronunciation": "shēng cún huán jìng", "ipa": "ʂɤŋ˥ tsʰwən˧˥ xwan˧˥ tɕiŋ˥˩", "syllable_count": 4, "sentences": [{"text": "这些做法有助于改善蜜蜂的生存环境。", "target_word": "生存环境", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "森林变少，动物的生存环境越来越差。", "target_word": "生存环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "污染会影响鱼类的生存环境。", "target_word": "生存环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家正在研究北极熊的生存环境。", "target_word": "生存环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "气候变化让很多动物的生存环境变差了。", "target_word": "生存环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保护湿地就是保护鸟类的生存环境。", "target_word": "生存环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的生存环境对植物很重要。", "target_word": "生存环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人们应该给野生动物留下干净的生存环境。", "target_word": "生存环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种鱼对生存环境的要求很高。", "target_word": "生存环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河水变脏以后，青蛙的生存环境受到了影响。", "target_word": "生存环境", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生存環境", "label": "繁体"}], "register": "中性", "sense_fingerprint": "生物生存所需的各种外界条件的总和（科学概念）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '020655ba-9334-42e1-8d99-bb5d113bb481') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13825, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生存环境", "is_correct": true, "explanation": "正确：“生存环境”指生物生存所需的外界条件，符合“改善蜜蜂的……”的搭配和语义。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资是人的劳动报酬，蜜蜂没有工资，不能被改善。"}, {"text": "学历", "is_correct": false, "explanation": "语义：学历是人受教育的记录，与蜜蜂无关，不能用“改善”来说。"}, {"text": "姓名", "is_correct": false, "explanation": "语义：姓名是人的称呼，蜜蜂没有姓名，不能用“改善”来说。"}], "explanations": {"生存环境": "正确：“生存环境”指生物生存所需的外界条件，符合“改善蜜蜂的……”的搭配和语义。", "工资": "语义：工资是人的劳动报酬，蜜蜂没有工资，不能被改善。", "学历": "语义：学历是人受教育的记录，与蜜蜂无关，不能用“改善”来说。", "姓名": "语义：姓名是人的称呼，蜜蜂没有姓名，不能用“改善”来说。"}, "sentence_index": 0, "correct_answer": "生存环境"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆汽车的生存环境很好，车库里干燥通风。", "explanation": "这里应该用〈停放环境〉。生存环境指生物维持生命的外界条件，汽车不是生物，谈车辆的停放条件要用〈停放环境〉。"}, {"text": "这台电脑的生存环境很稳定，运行速度很快。", "explanation": "〈生存环境〉只用于生物，电脑不是生物，不能说它有生存环境，这里应该用〈运行环境〉。"}, {"text": "这张照片的生存环境很好，颜色很鲜艳。", "explanation": "这里应该用〈保存环境〉。生存环境指生物维持生命的外界条件，照片不是生物，谈存放条件要用〈保存环境〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b53513-05b2-4c98-aea5-e579448c7005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13825, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生存环境", "is_correct": true, "explanation": "正确：“生存环境”指植物生存所需的外界条件，“好的……对植物很重要”成立。"}, {"text": "户口", "is_correct": false, "explanation": "语义：户口是人的户籍登记，植物没有户口，句子不通。"}, {"text": "体貌", "is_correct": false, "explanation": "语义：体貌指人的外形，不用于植物，与“对植物很重要”冲突。"}, {"text": "嗓音", "is_correct": false, "explanation": "语义：嗓音是人或动物发出的声音，植物没有嗓音，不能说“好的嗓音对植物很重要”。"}], "explanations": {"生存环境": "正确：“生存环境”指植物生存所需的外界条件，“好的……对植物很重要”成立。", "户口": "语义：户口是人的户籍登记，植物没有户口，句子不通。", "体貌": "语义：体貌指人的外形，不用于植物，与“对植物很重要”冲突。", "嗓音": "语义：嗓音是人或动物发出的声音，植物没有嗓音，不能说“好的嗓音对植物很重要”。"}, "sentence_index": 6, "correct_answer": "生存环境"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台冰箱的生存环境很好，通风干燥，制冷效果也好。", "explanation": "这里应该用〈工作环境〉。生存环境指生物维持生命的外界条件，冰箱不是生物，谈设备的运行条件要用〈工作环境〉。"}, {"text": "这块手表的生存环境很好，防水防尘。", "explanation": "这里应该用〈使用环境〉。生存环境指生物维持生命的外界条件，手表不是生物，谈器物的使用条件要用〈使用环境〉。"}, {"text": "这套书的生存环境很干燥，所以没有发霉。", "explanation": "这里应该用〈存放环境〉。生存环境指生物维持生命的外界条件，书不是生物，谈存放条件要用〈存放环境〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b53513-05b2-4c98-aea5-e579448c7005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13825, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要为动物创造一只好的生存环境。", "corrected_sentence": "我们要为动物创造一个好的生存环境。", "error_description": "错误：量词。“生存环境”是抽象名词，应用量词“个”；“只”用于动物或成对物品中的一个，不能修饰“生存环境”。错误形式“一只好的生存环境”，正确形式“一个好的生存环境”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b53513-05b2-4c98-aea5-e579448c7005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13825, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这片森林有一只好的生存环境。", "corrected_sentence": "这片森林有一个好的生存环境。", "error_description": "错误：量词。“生存环境”是抽象名词，应用量词“个”；“只”用于动物或成对物品中的一个，不能修饰“生存环境”。错误形式“有一只好的生存环境”，正确形式“有一个好的生存环境”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b53513-05b2-4c98-aea5-e579448c7005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
