INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13826, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指花和草，泛指植物。", "primary_collocate": null, "pronunciation": "huā cǎo", "ipa": "xwa˥ tsʰaʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我们每个人都可以通过种植花草、支持生态农业来帮助蜜蜂。", "target_word": "花草", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "公园里有很多花草。", "target_word": "花草", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈喜欢在阳台上养花草。", "target_word": "花草", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天来了，花草都长出来了。", "target_word": "花草", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下了一场雨，花草看起来更新鲜了。", "target_word": "花草", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷每天早上给花草浇水。", "target_word": "花草", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小区的花草很多，空气也很好。", "target_word": "花草", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请不要踩院子里的花草。", "target_word": "花草", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对花草很有研究，家里种了不少。", "target_word": "花草", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房间里放几盆花草，人的心情会更好。", "target_word": "花草", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "花花草草", "label": "重叠"}, {"form": "花草树木", "label": "复合"}], "register": "中性", "sense_fingerprint": "花和草的合称，泛指植物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '020655ba-9334-42e1-8d99-bb5d113bb481') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13826, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "花草", "is_correct": true, "explanation": "正确：“花草”指花和草，种植花草可以帮助蜜蜂，符合句意。"}, {"text": "户口", "is_correct": false, "explanation": "搭配：“种植”只搭配植物、作物，不能说“种植户口”。"}, {"text": "学历", "is_correct": false, "explanation": "语义：学历是人受教育的记录，不能被种植。"}, {"text": "体貌", "is_correct": false, "explanation": "语义：体貌指人的外形，不能被种植。"}], "explanations": {"花草": "正确：“花草”指花和草，种植花草可以帮助蜜蜂，符合句意。", "户口": "搭配：“种植”只搭配植物、作物，不能说“种植户口”。", "学历": "语义：学历是人受教育的记录，不能被种植。", "体貌": "语义：体貌指人的外形，不能被种植。"}, "sentence_index": 0, "correct_answer": "花草"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只小猫是我家的花草，每天陪我玩。", "explanation": "这里不这么用。〈花草〉指花和草，是植物，不能指小猫，小猫应说〈宠物〉。"}, {"text": "妈妈用花草修好了家里的旧电视。", "explanation": "这里应该用〈工具〉。花草是植物，不能拿来修电视，修电器要用工具。"}, {"text": "这台电脑靠花草供电，不用插电就能开机。", "explanation": "这里应该用〈电池〉。花草是植物，不能给电脑供电，供电要靠电池或电源。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b53513-05b2-4c98-aea5-e579448c7005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13826, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "花草", "is_correct": true, "explanation": "正确：“花草”指花和草，小区里花草很多、空气很好，符合句意。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资是劳动报酬，小区不会有很多工资，句子不通。"}, {"text": "嗓音", "is_correct": false, "explanation": "语义：嗓音是声音，不能用“很多”来说一个小区。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高指人或物的高矮，不能说“小区的身高很多”。"}], "explanations": {"花草": "正确：“花草”指花和草，小区里花草很多、空气很好，符合句意。", "工资": "语义：工资是劳动报酬，小区不会有很多工资，句子不通。", "嗓音": "语义：嗓音是声音，不能用“很多”来说一个小区。", "身高": "语义：身高指人或物的高矮，不能说“小区的身高很多”。"}, "sentence_index": 6, "correct_answer": "花草"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器的花草坏了，需要送去修理。", "explanation": "这里应该用〈零件〉。花草是植物，不是机器的零件，机器的部件要说〈零件〉。"}, {"text": "他用花草换了一辆自行车，觉得很划算。", "explanation": "这里应该用〈钱〉。〈花草〉是植物，不是货币，不能拿来换车。"}, {"text": "工人们用花草修成了一座桥。", "explanation": "〈花草〉是植物，不能用来修桥，这里应该用〈木材〉或〈石头〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b53513-05b2-4c98-aea5-e579448c7005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13826, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "阳台上摆着一只花草，很漂亮。", "corrected_sentence": "阳台上摆着一盆花草，很漂亮。", "error_description": "错误：量词。“花草”可用量词“盆”；“只”用于动物或成对物品中的一个，不能修饰“花草”。错误形式“一只花草”，正确形式“一盆花草”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b53513-05b2-4c98-aea5-e579448c7005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13826, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些的花草很美丽，大家都喜欢。", "corrected_sentence": "这些花草很美丽，大家都喜欢。", "error_description": "错误：多余的“的”。“这些”后面不能直接加“的”，应说“这些花草”。错误形式“这些的花草”，正确形式“这些花草”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b53513-05b2-4c98-aea5-e579448c7005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
