INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13828, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容事物互相交错，头绪繁多，情况复杂。", "primary_collocate": null, "pronunciation": "cuò zōng fù zá", "ipa": "tsʰwo˥˩ tsʊŋ˥ fu˥˩ tsa˧˥", "syllable_count": 4, "sentences": [{"text": "在地球错综复杂的生态系统中，蜜蜂作为最为关键的授粉昆虫之一，其存在远不止于生产蜂蜜这一表层价值。", "target_word": "错综复杂", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这件事的关系错综复杂，我一时说不清。", "target_word": "错综复杂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座城市的地铁线路错综复杂，外地人常常迷路。", "target_word": "错综复杂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家公司之间的利益关系错综复杂。", "target_word": "错综复杂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "森林里的树根错综复杂，走路要小心。", "target_word": "错综复杂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个案子错综复杂，警察查了很久。", "target_word": "错综复杂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他家的亲戚关系错综复杂，我记不住。", "target_word": "错综复杂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老城区的小路错综复杂，像一张大网。", "target_word": "错综复杂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "故事的线索错综复杂，看完电影我还是不明白。", "target_word": "错综复杂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对错综复杂的情况，我们要先冷静下来。", "target_word": "错综复杂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "錯綜複雜", "label": "繁体"}], "register": "中性", "sense_fingerprint": "事物、关系、线索等交错缠绕，头绪多，情况复杂", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b9e37f0-e74a-4b71-a88f-897ca2745a14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13828, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "简陋", "is_correct": false, "explanation": "搭配：“简陋”多形容房屋、设施等，不用来形容生态系统。"}, {"text": "错综复杂", "is_correct": true, "explanation": "“错综复杂”指生态系统各部分相互交织、关系繁多，与后文“远不止于表层价值”的深层含义相合。"}, {"text": "呆板", "is_correct": false, "explanation": "搭配：“呆板”形容神态、做法或文风，不能修饰生态系统。"}, {"text": "沙哑", "is_correct": false, "explanation": "搭配：“沙哑”形容嗓音，不能修饰生态系统。"}], "explanations": {"简陋": "搭配：“简陋”多形容房屋、设施等，不用来形容生态系统。", "错综复杂": "“错综复杂”指生态系统各部分相互交织、关系繁多，与后文“远不止于表层价值”的深层含义相合。", "呆板": "搭配：“呆板”形容神态、做法或文风，不能修饰生态系统。", "沙哑": "搭配：“沙哑”形容嗓音，不能修饰生态系统。"}, "sentence_index": 0, "correct_answer": "错综复杂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他错综复杂地走进了教室，大家都看着他。", "explanation": "用法不当：错综复杂形容事物、关系、线索等交错繁多，不能用来描述人走路的方式，也不能作“走进”的状语。"}, {"text": "我的房间里灯光很错综复杂，找东西时总是很麻烦。", "explanation": "这里应该用〈昏暗〉。错综复杂指事物互相交织、头绪繁多；灯光弱、看不清应该用昏暗。"}, {"text": "这只杯子的形状很错综复杂，用起来很舒服。", "explanation": "这里应该用〈精巧〉。错综复杂指多个部分互相交织、头绪繁多；形状设计巧妙、做工细致应该用精巧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c018d9f-8dba-4412-8287-232c7933641e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13828, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "整齐", "is_correct": false, "explanation": "搭配：“整齐”说排列有序，不用来形容人与人之间的亲戚关系。"}, {"text": "错综复杂", "is_correct": true, "explanation": "“错综复杂”描述亲戚关系纠缠交织、难以理清，正好解释后半句“我记不住”。"}, {"text": "明亮", "is_correct": false, "explanation": "语义：“明亮”形容光线或外貌，不能用来形容亲戚关系。"}, {"text": "轻浮", "is_correct": false, "explanation": "搭配：“轻浮”形容人的言行，不说亲戚关系。"}], "explanations": {"整齐": "搭配：“整齐”说排列有序，不用来形容人与人之间的亲戚关系。", "错综复杂": "“错综复杂”描述亲戚关系纠缠交织、难以理清，正好解释后半句“我记不住”。", "明亮": "语义：“明亮”形容光线或外貌，不能用来形容亲戚关系。", "轻浮": "搭配：“轻浮”形容人的言行，不说亲戚关系。"}, "sentence_index": 6, "correct_answer": "错综复杂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这碗清汤面的汤很错综复杂，一眼就能看到碗底。", "explanation": "这里应该用〈清澈〉。错综复杂指事物互相交织、头绪繁多；汤清得能看见碗底，应该用清澈。"}, {"text": "他的脸很错综复杂，大家一眼就认出了他。", "explanation": "这里应该用〈独特〉。错综复杂指事物互相交织、头绪繁多；相貌与众不同、一眼就能认出应该用独特。"}, {"text": "这个数字很错综复杂，只是一个“一”字。", "explanation": "这里应该用〈简单〉。错综复杂指头绪繁多、互相交织；只有一个字的数字应该用简单。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c018d9f-8dba-4412-8287-232c7933641e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13828, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一接手这个项目，就把事情错综复杂。", "corrected_sentence": "他一接手这个项目，就把事情搞得错综复杂。", "error_description": "错误形式：“把事情错综复杂”。正确形式：“把事情搞得错综复杂”。错综复杂是形容词，作结果补语要用“搞得”引出，不能直接放在“把”字宾语后面作谓语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c018d9f-8dba-4412-8287-232c7933641e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13828, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几条线缠在一起，错综复杂很，我理了半天。", "corrected_sentence": "这几条线缠在一起，错综复杂得很，我理了半天。", "error_description": "错误形式：“错综复杂很”。正确形式：“错综复杂得很”。作程度补语时要用“得很”，“很”不能放在形容词后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c018d9f-8dba-4412-8287-232c7933641e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
