INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13831, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "用来指出实际情况，常引出与预期不同的事实", "primary_collocate": null, "pronunciation": "shì shí shàng", "ipa": "ʂɻ̩˥˩ ʂɻ̩˧˥ ʂɑŋ˥˩", "syllable_count": 3, "sentences": [{"text": "事实上，全球约75%的农作物种类在不同程度上依赖动物授粉，而蜜蜂正是其中占比最高的传粉媒介。", "target_word": "事实上", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "大家以为他会生气，事实上他一点也不生气。", "target_word": "事实上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个词听起来很难，事实上用法很简单。", "target_word": "事实上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们常说猫怕水，事实上有些猫很爱游泳。", "target_word": "事实上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说自己没学过英语，事实上他在美国住过五年。", "target_word": "事实上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人以为咖啡能提神，事实上效果并不大。", "target_word": "事实上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上看着很近，事实上开车要两个小时。", "target_word": "事实上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我以为他是老师，事实上他是医生。", "target_word": "事实上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都觉得她会赢，事实上她第一轮就输了。", "target_word": "事实上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店看着不大，事实上里面有三层楼。", "target_word": "事实上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "前文有想法或预期，后文用来指出与之不同的实际情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce3cdbb2-6def-43dc-9a20-b31c9024b160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13831, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "事实上", "is_correct": true, "explanation": "正确：「事实上」引出客观的统计事实，与后文的说明相符。"}, {"text": "突然", "is_correct": false, "explanation": "语义：「突然」表示出乎意料地发生，不能用来引出「全球约75%」这类统计数据。"}, {"text": "幸好", "is_correct": false, "explanation": "语义：「幸好」表示庆幸，句中只是陈述数据，没有庆幸的意思。"}, {"text": "反正", "is_correct": false, "explanation": "语义：「反正」表示「不管怎样，结果都一样」，不能用来引出一项客观的统计事实。"}], "explanations": {"事实上": "正确：「事实上」引出客观的统计事实，与后文的说明相符。", "突然": "语义：「突然」表示出乎意料地发生，不能用来引出「全球约75%」这类统计数据。", "幸好": "语义：「幸好」表示庆幸，句中只是陈述数据，没有庆幸的意思。", "反正": "语义：「反正」表示「不管怎样，结果都一样」，不能用来引出一项客观的统计事实。"}, "sentence_index": 0, "correct_answer": "事实上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "事实上，请你把门关上。", "explanation": "这里应表示〈请求〉，而「事实上」只用来引出实际情况，不能用来直接提出要求。"}, {"text": "事实上，你今天吃饭了吗？", "explanation": "这里应表示〈询问〉，而「事实上」只用来引出实际情况，不能引出疑问句；提问应直接说「你今天吃饭了吗？」"}, {"text": "事实上，祝你生日快乐！", "explanation": "这里应表示〈祝福〉，而「事实上」只用来引出实际情况，不能用于祝福这类言语行为。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13831, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "事实上", "is_correct": true, "explanation": "正确：「事实上」引出实际情况，与「看着很近」的预期形成对比。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：「偶尔」表示次数少，与「开车要两个小时」这一确定的实际情况不符。"}, {"text": "忽而", "is_correct": false, "explanation": "语义：「忽而」多用于「忽而……忽而……」，表示交替变化，不能引出与预期不同的实际情况。"}, {"text": "幸亏", "is_correct": false, "explanation": "语义：「幸亏」表示侥幸避免了不利，句中并没有这种意思。"}], "explanations": {"事实上": "正确：「事实上」引出实际情况，与「看着很近」的预期形成对比。", "偶尔": "语义：「偶尔」表示次数少，与「开车要两个小时」这一确定的实际情况不符。", "忽而": "语义：「忽而」多用于「忽而……忽而……」，表示交替变化，不能引出与预期不同的实际情况。", "幸亏": "语义：「幸亏」表示侥幸避免了不利，句中并没有这种意思。"}, "sentence_index": 6, "correct_answer": "事实上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "事实上，我们去公园散步吧。", "explanation": "这里应表示〈建议〉，而「事实上」只用来引出既成的客观情况，不能用来提出建议。"}, {"text": "事实上，对不起，我迟到了。", "explanation": "这里应表示〈道歉〉，而「事实上」引出的是客观事实，不能用来开头表示道歉。"}, {"text": "事实上，好的，我知道了。", "explanation": "这里应表示〈应答〉，而「事实上」只用于引出实际情况，不能用来回应别人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13831, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我以为天气很冷，事实上的今天很暖和。", "corrected_sentence": "我以为天气很冷，事实上今天很暖和。", "error_description": "错误：「事实上」后面多加了「的」，写成「事实上的今天」。正确：「事实上」是副词，直接修饰后面的分句或谓语，不能加「的」去修饰名词；「事实上的」是另一种用法，表示「实际存在的」，这里说不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13831, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家饭馆看着很贵，事实上了价格很便宜。", "corrected_sentence": "这家饭馆看着很贵，事实上价格很便宜。", "error_description": "错误：「事实上」后面多加了动态助词「了」，写成「事实上了」。正确：「事实上」是副词，不带「了」，应写成「事实上价格很便宜」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '212e2189-3a9b-4783-aacf-18bf5e476a5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
