INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13832, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指农业上栽培的各种植物，包括粮食、蔬菜、水果等。", "primary_collocate": null, "pronunciation": "nóng zuò wù", "ipa": "nʊŋ˧˥ tswo˥˩ u˥˩", "syllable_count": 3, "sentences": [{"text": "事实上，全球约75%的农作物种类在不同程度上依赖动物授粉，而蜜蜂正是其中占比最高的传粉媒介。", "target_word": "农作物", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "水稻、小麦和玉米都是重要的农作物。", "target_word": "农作物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年雨水多，很多农作物长得特别好。", "target_word": "农作物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民正在给农作物浇水。", "target_word": "农作物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场大雪冻坏了不少农作物。", "target_word": "农作物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北方的主要农作物是小麦和玉米。", "target_word": "农作物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农作物需要阳光、水和肥料才能长大。", "target_word": "农作物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虫子吃了农作物，农民很着急。", "target_word": "农作物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地区适合种植多种农作物。", "target_word": "农作物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在大学里研究农作物的病虫害。", "target_word": "农作物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "農作物", "label": "繁体"}], "register": "中性", "sense_fingerprint": "农业上栽培的各种植物，包括粮食、蔬菜、水果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b9e37f0-e74a-4b71-a88f-897ca2745a14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13832, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "农作物", "is_correct": true, "explanation": "正确：“农作物”指田里栽培的植物，全球大部分种类依赖动物授粉，与句意相符。"}, {"text": "矿物", "is_correct": false, "explanation": "语义：矿物不是植物，不会依赖动物授粉。"}, {"text": "家具", "is_correct": false, "explanation": "语义：家具不是生物，与授粉无关。"}, {"text": "语言", "is_correct": false, "explanation": "配价：“依赖……授粉”的主语必须是需要授粉的植物，“语言”不能作这个主语。"}], "explanations": {"农作物": "正确：“农作物”指田里栽培的植物，全球大部分种类依赖动物授粉，与句意相符。", "矿物": "语义：矿物不是植物，不会依赖动物授粉。", "家具": "语义：家具不是生物，与授粉无关。", "语言": "配价：“依赖……授粉”的主语必须是需要授粉的植物，“语言”不能作这个主语。"}, "sentence_index": 0, "correct_answer": "农作物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人正在锯农作物，准备拿去做家具。", "explanation": "这里应该用〈木材〉。农作物是田里种出来的植物，不能用锯子锯，锯的应是木材。"}, {"text": "他在动物园里喂养农作物。", "explanation": "这里应该用〈动物〉。喂养的对象是动物，农作物是栽培的植物，不能喂养。"}, {"text": "农民正在给一只农作物浇水。", "explanation": "这里应该用〈种〉。农作物的量词是“种”，不用“只”，“只”多用于动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c018d9f-8dba-4412-8287-232c7933641e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13832, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "农作物", "is_correct": true, "explanation": "正确：“农作物”是生物，需要阳光、水和肥料才能长大。"}, {"text": "机器", "is_correct": false, "explanation": "搭配：“长大”一般用于生物，不说机器长大。"}, {"text": "小说", "is_correct": false, "explanation": "配价：“长大”的主语需是生物，“小说”不能作主语。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是生物，不需要阳光、水和肥料。"}], "explanations": {"农作物": "正确：“农作物”是生物，需要阳光、水和肥料才能长大。", "机器": "搭配：“长大”一般用于生物，不说机器长大。", "小说": "配价：“长大”的主语需是生物，“小说”不能作主语。", "冰箱": "语义：冰箱不是生物，不需要阳光、水和肥料。"}, "sentence_index": 6, "correct_answer": "农作物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在大学里研究一头农作物。", "explanation": "这里应该用〈种〉。农作物的量词是“种”，不用“头”，“头”多用于大牲畜。"}, {"text": "他在大学里研究农作物的国籍。", "explanation": "这里应该用〈品种〉。农作物没有国籍，说它的来源或类别要用品种，不用“国籍”。"}, {"text": "他在大学里研究农作物的歌声。", "explanation": "这里应该用〈生长〉。农作物不会唱歌，研究的是它的生长情况，不是歌声。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c018d9f-8dba-4412-8287-232c7933641e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13832, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种农作物们耐旱，适合在北方种植。", "corrected_sentence": "这种农作物耐旱，适合在北方种植。", "error_description": "错误：复数标记“们”只用于指人，不能加在非生命的“农作物”后。正确：“这种农作物”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c018d9f-8dba-4412-8287-232c7933641e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13832, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那是一条耐寒的农作物。", "corrected_sentence": "那是一种耐寒的农作物。", "error_description": "错误：量词用错。正确：“一种农作物”，农作物的量词是“种”，“条”用于细长的东西。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c018d9f-8dba-4412-8287-232c7933641e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
