INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13833, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "占据，指用强力取得或拥有某个位置、空间或利益。", "primary_collocate": null, "pronunciation": "zhàn", "ipa": "ʈʂan˥˩", "syllable_count": 1, "sentences": [{"text": "这个会议室的座位大多已经被提前到场的人占了，后来的同学只能站在走廊里听讲。", "target_word": "占", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "那辆车占了两个停车位。", "target_word": "占", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他早早地占着一个好座位。", "target_word": "占", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张大桌子占了房间很多空间。", "target_word": "占", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别人占着我的座位，我只好站着。", "target_word": "占", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队占了山上的小村子。", "target_word": "占", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在公园里占好了一块地方玩游戏。", "target_word": "占", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "行李放在过道上会占地方。", "target_word": "占", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他来得早，占了教室最前面的位子。", "target_word": "占", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家商店占着街角最好的位置。", "target_word": "占", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "占了", "label": "体标"}, {"form": "占着", "label": "体标"}, {"form": "占过", "label": "体标"}, {"form": "占据", "label": "复合"}, {"form": "占领", "label": "复合"}, {"form": "占用", "label": "复合"}, {"form": "佔", "label": "繁体"}], "register": "中性", "sense_fingerprint": "占据位置、空间或利益", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b9e37f0-e74a-4b71-a88f-897ca2745a14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13833, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "占", "is_correct": true, "explanation": "占（zhàn）：用强力取得或占据某个位置、空间或利益。"}, {"text": "沾", "is_correct": false, "explanation": "zhān（第一声）与 zhàn（第四声）声调不同，意思是沾上、沾染，与占据无关。"}, {"text": "展", "is_correct": false, "explanation": "zhǎn（第三声）与 zhàn（第四声）声调不同，意思是展开。"}, {"text": "善", "is_correct": false, "explanation": "shàn 与 zhàn 声母不同（sh 与 zh），意思是善良、好。"}, {"text": "赞", "is_correct": false, "explanation": "zàn 与 zhàn 声母不同（z 与 zh），意思是赞美。"}, {"text": "账", "is_correct": false, "explanation": "zhàng 与 zhàn 韵母不同（ang 与 an），意思是账目。"}], "explanations": {"占": "占（zhàn）：用强力取得或占据某个位置、空间或利益。", "沾": "zhān（第一声）与 zhàn（第四声）声调不同，意思是沾上、沾染，与占据无关。", "展": "zhǎn（第三声）与 zhàn（第四声）声调不同，意思是展开。", "善": "shàn 与 zhàn 声母不同（sh 与 zh），意思是善良、好。", "赞": "zàn 与 zhàn 声母不同（z 与 zh），意思是赞美。", "账": "zhàng 与 zhàn 韵母不同（ang 与 an），意思是账目。"}, "sentence_index": null, "correct_answer": "占"}, "level_3": {"options": [{"text": "占", "is_correct": true, "explanation": "占：指提前到场的人先占据座位，与“被……占了”相配。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能用于座位。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指歌唱，与座位无关。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”的对象是饮料，与座位无关。"}], "explanations": {"占": "占：指提前到场的人先占据座位，与“被……占了”相配。", "吃": "搭配：“吃”的对象是食物，不能用于座位。", "唱": "语义：“唱”指歌唱，与座位无关。", "喝": "语义：“喝”的对象是饮料，与座位无关。"}, "sentence_index": 0, "correct_answer": "占"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他占了很多才能。", "explanation": "这里应该用〈拥有〉。占指用强力取得某个位置、空间或利益，才能是抽象的个人特质，不能被占，应该用拥有。"}, {"text": "他终于占了自己的理想。", "explanation": "这里应该用〈实现〉。占指用强力取得或拥有位置、空间或利益，理想是抽象的目标，不能被占，应该用实现。"}, {"text": "这家人占着安静的生活。", "explanation": "这里应该用〈享受〉。占指取得具体的位置、空间或利益，安静的生活是抽象状态，不能被占，应该用享受。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c018d9f-8dba-4412-8287-232c7933641e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13833, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "占", "is_correct": true, "explanation": "占（zhàn）：用强力取得或占据某个位置、空间或利益。"}, {"text": "粘", "is_correct": false, "explanation": "zhān（第一声）与 zhàn（第四声）声调不同，意思是粘贴。"}, {"text": "扇", "is_correct": false, "explanation": "shàn 与 zhàn 声母不同（sh 与 zh），意思是扇子。"}, {"text": "暂", "is_correct": false, "explanation": "zàn 与 zhàn 声母不同（z 与 zh），意思是暂时。"}, {"text": "胀", "is_correct": false, "explanation": "zhàng 与 zhàn 韵母不同（ang 与 an），意思是膨胀。"}, {"text": "颤", "is_correct": false, "explanation": "chàn 与 zhàn 声母不同（ch 与 zh），意思是颤抖。"}], "explanations": {"占": "占（zhàn）：用强力取得或占据某个位置、空间或利益。", "粘": "zhān（第一声）与 zhàn（第四声）声调不同，意思是粘贴。", "扇": "shàn 与 zhàn 声母不同（sh 与 zh），意思是扇子。", "暂": "zàn 与 zhàn 声母不同（z 与 zh），意思是暂时。", "胀": "zhàng 与 zhàn 韵母不同（ang 与 an），意思是膨胀。", "颤": "chàn 与 zhàn 声母不同（ch 与 zh），意思是颤抖。"}, "sentence_index": null, "correct_answer": "占"}, "level_3": {"options": [{"text": "占", "is_correct": true, "explanation": "占：“占好了一块地方”指先占据场地。"}, {"text": "送", "is_correct": false, "explanation": "搭配：“送”要接人或物，不能说“送好了一块地方”。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”的宾语应为食物，不能带“地方”作宾语。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”指书写文字，与在公园里占用场地无关。"}], "explanations": {"占": "占：“占好了一块地方”指先占据场地。", "送": "搭配：“送”要接人或物，不能说“送好了一块地方”。", "吃": "配价：“吃”的宾语应为食物，不能带“地方”作宾语。", "写": "语义：“写”指书写文字，与在公园里占用场地无关。"}, "sentence_index": 6, "correct_answer": "占"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她占了大家的信任。", "explanation": "这里应该用〈赢得〉。占用于取得位置、空间或利益，信任是人与人之间的情感，不能被占，应该用赢得。"}, {"text": "他占了很大的进步。", "explanation": "这里应该用〈取得〉。占强调用力占据某物，进步这类抽象结果不能被占，应该用取得。"}, {"text": "她占了一张奖状。", "explanation": "这里应该用〈获得〉。占指用强力取得或拥有位置、空间或利益，奖状要靠成绩获得，不能被占，应该用获得。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c018d9f-8dba-4412-8287-232c7933641e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13833, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他占了着座位不让别人坐。", "corrected_sentence": "他占着座位不让别人坐。", "error_description": "“了”与“着”不能同时用在“占”后，应去掉“了”，改为“他占着座位不让别人坐”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c018d9f-8dba-4412-8287-232c7933641e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13833, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "书堆占了满整张桌子。", "corrected_sentence": "书堆占满了整张桌子。", "error_description": "“满”是“占”的结果补语，应紧跟在“占”后，“了”放在“满”的后面，应说“占满了整张桌子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c018d9f-8dba-4412-8287-232c7933641e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13834, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c018d9f-8dba-4412-8287-232c7933641e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13834, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c018d9f-8dba-4412-8287-232c7933641e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13834, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指可可树的种子，经加工后可制成可可粉、巧克力等食品。", "primary_collocate": null, "pronunciation": "kě kě", "ipa": "kʰɤ˨˩˦ kʰɤ˨˩˦", "syllable_count": 2, "sentences": [{"text": "从苹果、杏仁到咖啡与可可，这些人类饮食结构中的重要组成部分，其产量与质量皆深刻受制于蜂类活动的稳定性。", "target_word": "可可", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "巧克力是用可可做的。", "target_word": "可可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些可可是从非洲运来的。", "target_word": "可可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "非洲的很多农民种可可。", "target_word": "可可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "可可的味道有一点苦。", "target_word": "可可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在牛奶里加了可可。", "target_word": "可可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种蛋糕里有咖啡和可可。", "target_word": "可可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "热带地区的农民种着可可。", "target_word": "可可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂把可可做成了巧克力。", "target_word": "可可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂每年都要买很多可可。", "target_word": "可可", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "可可粉", "label": "复合"}, {"form": "可可豆", "label": "复合"}, {"form": "热可可", "label": "复合"}], "register": "中性", "sense_fingerprint": "可可树的种子，可制成可可粉和巧克力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b9e37f0-e74a-4b71-a88f-897ca2745a14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13834, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可可", "is_correct": true, "explanation": "可可：指可可树的种子，与苹果、杏仁、咖啡同属食物，可以并列。"}, {"text": "木材", "is_correct": false, "explanation": "语义：木材不属于饮食结构，不能与前面的食物并列。"}, {"text": "石油", "is_correct": false, "explanation": "搭配：“与”并列的应是同类食物，石油无法与苹果、咖啡并列。"}, {"text": "水泥", "is_correct": false, "explanation": "语义：水泥不是食物，与“饮食结构”的描述无关。"}], "explanations": {"可可": "可可：指可可树的种子，与苹果、杏仁、咖啡同属食物，可以并列。", "木材": "语义：木材不属于饮食结构，不能与前面的食物并列。", "石油": "搭配：“与”并列的应是同类食物，石油无法与苹果、咖啡并列。", "水泥": "语义：水泥不是食物，与“饮食结构”的描述无关。"}, "sentence_index": 0, "correct_answer": "可可"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "农民今年收了一封可可。", "explanation": "这里应该用〈袋〉。可可豆收好后装袋计量，“封”用于信件，不能说“一封可可”。"}, {"text": "他买了一张可可，准备做饼干。", "explanation": "这里应该用〈包〉。可可粉按包计量，“张”用于纸张、桌子等平面的东西，不能用于可可。"}, {"text": "他从市场买回一首可可。", "explanation": "这里应该用〈袋〉。可可按袋计量，“首”用于歌曲、诗，不能用于可可。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c018d9f-8dba-4412-8287-232c7933641e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13834, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可可", "is_correct": true, "explanation": "可可：蛋糕里常用的原料，可以与咖啡并列。"}, {"text": "螺丝", "is_correct": false, "explanation": "语义：螺丝不能用于做蛋糕，与咖啡并列不成立。"}, {"text": "钢筋", "is_correct": false, "explanation": "搭配：“咖啡和”并列的应为可食用之物，钢筋无法与之并列。"}, {"text": "沙子", "is_correct": false, "explanation": "语义：沙子不是食材，放进蛋糕不合常理。"}], "explanations": {"可可": "可可：蛋糕里常用的原料，可以与咖啡并列。", "螺丝": "语义：螺丝不能用于做蛋糕，与咖啡并列不成立。", "钢筋": "搭配：“咖啡和”并列的应为可食用之物，钢筋无法与之并列。", "沙子": "语义：沙子不是食材，放进蛋糕不合常理。"}, "sentence_index": 6, "correct_answer": "可可"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一条可可。", "explanation": "这里应该用〈包〉。可可粉按包计量，“条”用于细长的东西，不能用于可可。"}, {"text": "我的同桌买了一本可可。", "explanation": "这里应该用〈包〉。可可粉按包计量，“本”用于书册，不能用于可可。"}, {"text": "工厂昨天运来了一座可可。", "explanation": "这里应该用〈批〉。大量的可可按批计量，“座”用于山、房屋等，不能用于可可。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c018d9f-8dba-4412-8287-232c7933641e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13834, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈买了一只可可，准备做饼干。", "corrected_sentence": "妈妈买了一包可可，准备做饼干。", "error_description": "“可可”指粉末状的可可，量词应用“包”，不能用“只”，应改为“妈妈买了一包可可，准备做饼干”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c018d9f-8dba-4412-8287-232c7933641e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13834, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工厂上个月运来了一本可可。", "corrected_sentence": "工厂上个月运来了一批可可。", "error_description": "量词错误：“本”用于书册，不能用于可可。大量运来的可可应按“批”计量，应改为“工厂上个月运来了一批可可”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c018d9f-8dba-4412-8287-232c7933641e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13835, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23c349f0-88a0-4b80-b2a7-c87fc75f0484') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13835, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23c349f0-88a0-4b80-b2a7-c87fc75f0484') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13835, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "饮食结构指一个人或群体日常摄入的食物种类、数量及其比例关系。", "primary_collocate": null, "pronunciation": "yǐn shí jié gòu", "ipa": "in˨˩˦ ʂʐ̩˧˥ tɕjɛ˧˥ kou˥˩", "syllable_count": 4, "sentences": [{"text": "从苹果、杏仁到咖啡与可可，这些人类饮食结构中的重要组成部分，其产量与质量皆深刻受制于蜂类活动的稳定性。", "target_word": "饮食结构", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "医生建议他调整一下饮食结构。", "target_word": "饮食结构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的饮食结构太单一，每天只吃面条。", "target_word": "饮食结构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "改善饮食结构对身体健康很重要。", "target_word": "饮食结构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "南方和北方的饮食结构有很大的不同。", "target_word": "饮食结构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把家人的饮食结构改成了多吃蔬菜、少吃肉。", "target_word": "饮食结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "随着收入提高，农村居民的饮食结构发生了明显变化。", "target_word": "饮食结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "营养师先了解了孩子的饮食结构，再制定食谱。", "target_word": "饮食结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "合理的饮食结构应该包括粮食、蔬菜、水果和肉类。", "target_word": "饮食结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的饮食结构要少油少盐，多吃清淡的食物。", "target_word": "饮食结构", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "飲食結構", "label": "繁体"}], "register": "书面", "sense_fingerprint": "人或群体日常摄入食物的种类、数量和比例构成", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5fc0a8-d4f8-4387-9171-1f1a55380ca6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13835, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "饮食结构", "is_correct": true, "explanation": "正确：「饮食结构」指人或群体吃的食物的种类、数量和比例，与句中列举的苹果、杏仁、咖啡等食物相符。"}, {"text": "人口结构", "is_correct": false, "explanation": "搭配：「产量与质量」说的是食物，不能与「人口结构」搭配；「人口结构」指人口的年龄、性别等构成。"}, {"text": "交通工具", "is_correct": false, "explanation": "语义：苹果、咖啡不是交通工具的组成部分，句意不通。"}, {"text": "农药", "is_correct": false, "explanation": "语义：农药不是人类饮食的组成部分，与句中列举的食物相矛盾。"}], "explanations": {"饮食结构": "正确：「饮食结构」指人或群体吃的食物的种类、数量和比例，与句中列举的苹果、杏仁、咖啡等食物相符。", "人口结构": "搭配：「产量与质量」说的是食物，不能与「人口结构」搭配；「人口结构」指人口的年龄、性别等构成。", "交通工具": "语义：苹果、咖啡不是交通工具的组成部分，句意不通。", "农药": "语义：农药不是人类饮食的组成部分，与句中列举的食物相矛盾。"}, "sentence_index": 0, "correct_answer": "饮食结构"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要制定一只新的饮食结构。", "explanation": "这里应该用〈种〉或〈套〉。「只」用于单个动物或成对的物件，饮食结构是抽象的体系，不能用「只」来计量。"}, {"text": "这座大桥的饮食结构很坚固，车辆可以安全通过。", "explanation": "这里应该用〈桥梁〉。「饮食结构」指食物的种类与比例，不能用来形容大桥的坚固；说大桥坚固应指桥梁的承重结构。"}, {"text": "这辆汽车的饮食结构很先进，跑得很快。", "explanation": "这里应该用〈发动机〉。饮食结构指人或群体吃的食物的种类与比例，汽车不吃东西，不能这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23c349f0-88a0-4b80-b2a7-c87fc75f0484') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13835, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "饮食结构", "is_correct": true, "explanation": "正确：「饮食结构」指人或群体吃的食物的结构，与「收入提高」后居民饮食的变化相符。"}, {"text": "交通规则", "is_correct": false, "explanation": "语义：交通规则由政府制定，与收入提高无关，不能说随着收入提高而「发生明显变化」。"}, {"text": "地壳", "is_correct": false, "explanation": "语义：地壳是地球的构造，不属于居民，句意荒谬。"}, {"text": "质量", "is_correct": false, "explanation": "搭配：「质量」不用于描述人群，不能说农村居民的「质量」发生变化。"}], "explanations": {"饮食结构": "正确：「饮食结构」指人或群体吃的食物的结构，与「收入提高」后居民饮食的变化相符。", "交通规则": "语义：交通规则由政府制定，与收入提高无关，不能说随着收入提高而「发生明显变化」。", "地壳": "语义：地壳是地球的构造，不属于居民，句意荒谬。", "质量": "搭配：「质量」不用于描述人群，不能说农村居民的「质量」发生变化。"}, "sentence_index": 6, "correct_answer": "饮食结构"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种饮料的饮食结构很简单，只有糖和水。", "explanation": "这里应该用〈成分〉。饮料不吃东西，饮食结构指人或群体吃的食物的种类与比例，说饮料的构成应用「成分」。"}, {"text": "他的饮食结构很大，一顿能吃三碗。", "explanation": "这里应该用〈饭量〉。「饭量」说吃多少，饮食结构说吃哪些食物及其比例，不能用「很大」来形容。"}, {"text": "这本书的饮食结构很清楚，一共分十章。", "explanation": "这里应该用〈结构〉。书的章节安排是书的结构，饮食结构只指人吃的食物的种类与比例。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23c349f0-88a0-4b80-b2a7-c87fc75f0484') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13835, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我妈妈希望我改善一只饮食结构，少吃油炸食品。", "corrected_sentence": "我妈妈希望我改善饮食结构，少吃油炸食品。", "error_description": "量词错误：「只」用于单个动物或成对的物件，「饮食结构」是抽象的体系，不能说「一只饮食结构」，应直接说「改善饮食结构」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23c349f0-88a0-4b80-b2a7-c87fc75f0484') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13835, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶正在饮食结构。", "corrected_sentence": "奶奶正在调整饮食结构。", "error_description": "动词缺失：「饮食结构」是名词，不能直接跟在「正在」后作谓语，应补出动词「调整」，说「正在调整饮食结构」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23c349f0-88a0-4b80-b2a7-c87fc75f0484') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
