INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13836, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23c349f0-88a0-4b80-b2a7-c87fc75f0484') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13836, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "蜂类是指蜜蜂、黄蜂等昆虫的统称，它们通常有翅膀和刺，能采蜜或捕食。", "primary_collocate": null, "pronunciation": "fēng lèi", "ipa": "fɤŋ˥ leɪ˥˩", "syllable_count": 2, "sentences": [{"text": "从苹果、杏仁到咖啡与可可，这些人类饮食结构中的重要组成部分，其产量与质量皆深刻受制于蜂类活动的稳定性。", "target_word": "蜂类", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "例如，在某些高原农业区，野生蜂类数量锐减已导致本地果树坐果率不足三成，迫使农民转向成本高昂的人工授粉，这不仅增加了农业生产的经济负担，也暴露了食物供应链的脆弱性。", "target_word": "蜂类", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "然而，当前全球平均每三年就有一种野生蜂类被列为濒危物种，这一速度是自然灭绝率的数百倍。", "target_word": "蜂类", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "多数蜂类会采集花蜜，帮助植物授粉。", "target_word": "蜂类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜜蜂和黄蜂都属于蜂类。", "target_word": "蜂类", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "蜂类的尾部通常有刺，用来保护自己。", "target_word": "蜂类", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天花开了，蜂类开始在田野里忙碌。", "target_word": "蜂类", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家发现蜂类会用舞蹈告诉同伴花在哪里。", "target_word": "蜂类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些蜂类自己做窝，有些蜂类住在大蜂群里。", "target_word": "蜂类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了保护蜂类，农民减少了农药的使用。", "target_word": "蜂类", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "蜂類", "label": "繁体"}], "register": "书面", "sense_fingerprint": "蜜蜂、黄蜂等有翅有刺昆虫的统称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5fc0a8-d4f8-4387-9171-1f1a55380ca6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13836, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蜂类", "is_correct": true, "explanation": "正确：「蜂类」指昆虫，句中说的是它们的活动，与「受制于……活动的稳定性」相符。"}, {"text": "农药", "is_correct": false, "explanation": "语义：农药本身不会「活动」，句中指的是有生命的昆虫。"}, {"text": "花粉", "is_correct": false, "explanation": "语义：花粉靠风或昆虫传播，本身不做「活动」，句意不通。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：「活动」一般不搭配「天气」，句中指昆虫的活动。"}], "explanations": {"蜂类": "正确：「蜂类」指昆虫，句中说的是它们的活动，与「受制于……活动的稳定性」相符。", "农药": "语义：农药本身不会「活动」，句中指的是有生命的昆虫。", "花粉": "语义：花粉靠风或昆虫传播，本身不做「活动」，句意不通。", "天气": "搭配：「活动」一般不搭配「天气」，句中指昆虫的活动。"}, "sentence_index": 0, "correct_answer": "蜂类"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "蜂类在河里游来游去，捕食小虾。", "explanation": "这里应该用〈鱼类〉。在河里游、捕食小虾的是鱼类，蜂类是会飞的昆虫。"}, {"text": "这瓶蜂类很甜，是用来做饮料的。", "explanation": "这里应该用〈蜂蜜〉。蜂蜜是食物，蜂类是昆虫的统称，不能说「很甜」，也不能用来做饮料。"}, {"text": "花朵里有甜甜的蜂类。", "explanation": "这里应该用〈花蜜〉。花蜜是花里的甜液，蜂类是昆虫，不能放在「甜甜的」后面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23c349f0-88a0-4b80-b2a7-c87fc75f0484') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13836, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蜂类", "is_correct": true, "explanation": "正确：「蜂类」会在田野里忙碌，与「春天花开了，开始在田野里忙碌」相符。"}, {"text": "房屋", "is_correct": false, "explanation": "语义：房屋是建筑，不会在田野里「忙碌」，句意不通。"}, {"text": "水果", "is_correct": false, "explanation": "搭配：「忙碌」多用于人或会动的生物，不说水果「忙碌」。"}, {"text": "石块", "is_correct": false, "explanation": "语义：石块是静止的物体，不会「忙碌」，与「开始……忙碌」矛盾。"}], "explanations": {"蜂类": "正确：「蜂类」会在田野里忙碌，与「春天花开了，开始在田野里忙碌」相符。", "房屋": "语义：房屋是建筑，不会在田野里「忙碌」，句意不通。", "水果": "搭配：「忙碌」多用于人或会动的生物，不说水果「忙碌」。", "石块": "语义：石块是静止的物体，不会「忙碌」，与「开始……忙碌」矛盾。"}, "sentence_index": 6, "correct_answer": "蜂类"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "田野里开满了蜂类。", "explanation": "这里应该用〈花〉。「开满」用于花朵，蜂类不会「开」。"}, {"text": "蜂类的叶子是绿色的，秋天会变黄。", "explanation": "这里应该用〈植物〉。有叶子的是植物，蜂类是昆虫，没有叶子。"}, {"text": "蜂类是用蜂蜡做的，很精致。", "explanation": "这里应该用〈蜂窝〉。蜂窝是蜜蜂用蜂蜡筑成的；蜂类是昆虫，不能说它是用蜂蜡做的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23c349f0-88a0-4b80-b2a7-c87fc75f0484') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13836, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "许多野生蜂类已经被列濒危物种。", "corrected_sentence": "许多野生蜂类已经被列为濒危物种。", "error_description": "漏词错误：「列」后面要加「为」，说「被列为濒危物种」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23c349f0-88a0-4b80-b2a7-c87fc75f0484') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13836, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "春天，蜂类在田野里花蜜。", "corrected_sentence": "春天，蜂类在田野里采花蜜。", "error_description": "动词缺失：「蜂类」后需要动词带宾语「花蜜」，应补出「采」，说「蜂类在田野里采花蜜」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23c349f0-88a0-4b80-b2a7-c87fc75f0484') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13837, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe26dd9b-faf1-438f-9994-6c26e7733765') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13837, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe26dd9b-faf1-438f-9994-6c26e7733765') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13837, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "某种活动持续平稳、不剧烈波动的状态", "primary_collocate": null, "pronunciation": "wěn dìng xìng", "ipa": "wən˨˩˦ tiŋ˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "从苹果、杏仁到咖啡与可可，这些人类饮食结构中的重要组成部分，其产量与质量皆深刻受制于蜂类活动的稳定性。", "target_word": "稳定性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "工厂每天用电很多，供电的稳定性很重要。", "target_word": "稳定性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛中运动员发挥的稳定性最难得。", "target_word": "稳定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "训练的稳定性很重要，每天都要坚持。", "target_word": "稳定性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络一会儿快一会儿慢，稳定性不够。", "target_word": "稳定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家工厂生产的稳定性，让客户很放心。", "target_word": "稳定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蜜蜂采蜜的稳定性会影响果树的产量。", "target_word": "稳定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经济增长的稳定性比速度更重要。", "target_word": "稳定性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位司机开车的稳定性很高，乘客不会头晕。", "target_word": "稳定性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机场很重视航班运行的稳定性。", "target_word": "稳定性", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "穩定性", "label": "繁体"}], "register": "书面", "sense_fingerprint": "活动或运行持续平稳、少有波动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '578294a7-0823-4619-bc2b-d5210b7acc13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13837, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”说事物的外观，不能用来说蜂类活动。"}, {"text": "稳定性", "is_correct": true, "explanation": "稳定性指活动持续平稳、少有波动，与“受制于蜂类活动”的语境相符。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”指人的性情，蜂类活动没有脾气，与句意不符。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人或动物身体的高矮，不能用于活动。"}], "explanations": {"颜色": "搭配：“颜色”说事物的外观，不能用来说蜂类活动。", "稳定性": "稳定性指活动持续平稳、少有波动，与“受制于蜂类活动”的语境相符。", "脾气": "语义：“脾气”指人的性情，蜂类活动没有脾气，与句意不符。", "身高": "体貌：“身高”指人或动物身体的高矮，不能用于活动。"}, "sentence_index": 0, "correct_answer": "稳定性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这一根稳定性很重要，每天都要坚持。", "explanation": "这里应该用〈种〉或不加量词。“根”用于细长的物体，稳定性是抽象性质，不能用“根”计量。"}, {"text": "这条路的稳定性很快，半小时就能到。", "explanation": "这里应该用〈速度〉。稳定性指活动持续平稳，不指快慢；“很快，半小时就能到”说的是速度。"}, {"text": "这个举重运动员的稳定性很大，身高一米九。", "explanation": "这里应该用〈身高〉。稳定性指活动持续平稳，不指身材高矮；“一米九”说的是身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe26dd9b-faf1-438f-9994-6c26e7733765') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13837, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "形状", "is_correct": false, "explanation": "语义：“形状”指物体的外形，采蜜活动没有形状，与句意不符。"}, {"text": "长度", "is_correct": false, "explanation": "搭配：“长度”多用于物体或距离，不能说采蜜的长度。"}, {"text": "稳定性", "is_correct": true, "explanation": "稳定性指采蜜活动持续平稳，与“会影响果树的产量”的语境相符。"}, {"text": "性格", "is_correct": false, "explanation": "语义：“性格”指人的性情，与采蜜这一活动无关，不能用于句中。"}], "explanations": {"形状": "语义：“形状”指物体的外形，采蜜活动没有形状，与句意不符。", "长度": "搭配：“长度”多用于物体或距离，不能说采蜜的长度。", "稳定性": "稳定性指采蜜活动持续平稳，与“会影响果树的产量”的语境相符。", "性格": "语义：“性格”指人的性情，与采蜜这一活动无关，不能用于句中。"}, "sentence_index": 6, "correct_answer": "稳定性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "机场很重视航班运行的一座稳定性。", "explanation": "这里应该用〈种〉或不加量词。“座”用于山、桥、建筑等，稳定性是抽象性质，不能用“座”计量。"}, {"text": "这款手机的稳定性有六英寸大。", "explanation": "这里应该用〈屏幕〉。稳定性指运行平稳，不指尺寸；“六英寸大”说的是屏幕。"}, {"text": "这条生产线的稳定性是蓝色的。", "explanation": "这里应该用〈颜色〉。稳定性指运行平稳，不指颜色；“是蓝色的”说的是颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe26dd9b-faf1-438f-9994-6c26e7733765') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13837, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家网站的运行稳定性好很，访问很少出错。", "corrected_sentence": "这家网站的运行稳定性很好，访问很少出错。", "error_description": "错误：“好很”。“很”应放在形容词前面，正确说法是“稳定性很好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe26dd9b-faf1-438f-9994-6c26e7733765') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13837, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条生产线得运行稳定性很高，产量每天都差不多。", "corrected_sentence": "这条生产线的运行稳定性很高，产量每天都差不多。", "error_description": "错误：“得”。“运行稳定性”前的定语应用“的”，不能用“得”。正确说法是“这条生产线的运行稳定性很高”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe26dd9b-faf1-438f-9994-6c26e7733765') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
