INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13838, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "运用现代科学技术、工业装备和先进管理方法进行生产的农业。", "primary_collocate": null, "pronunciation": "xiàn dài nóng yè", "ipa": "ɕjɛn˥˩ taɪ˥˩ nʊŋ˧˥ jɛ˥˩", "syllable_count": 4, "sentences": [{"text": "现代农业体系高度依赖单一作物的大规模种植，这种集约化农业模式虽然提升了短期产出效率，却对生物多样性的维持构成了严峻挑战。", "target_word": "现代农业", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "现代农业需要用机器代替人工。", "target_word": "现代农业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "发展现代农业可以让农民收入更高。", "target_word": "现代农业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个县正在大力发展现代农业。", "target_word": "现代农业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现代农业离不开科学技术的支持。", "target_word": "现代农业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "与传统农业相比，现代农业的产量高得多。", "target_word": "现代农业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无人机喷洒农药，是现代农业中常见的做法。", "target_word": "现代农业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人带着新技术回到家乡，投身现代农业。", "target_word": "现代农业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现代农业提高了粮食产量，也带来了环境问题。", "target_word": "现代农业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在现代农业中，农民可以用手机查看田里的温度。", "target_word": "现代农业", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "現代農業", "label": "繁体"}], "register": "书面", "sense_fingerprint": "运用现代科技、机械装备和先进管理的农业生产方式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5fc0a8-d4f8-4387-9171-1f1a55380ca6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13838, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "现代农业", "is_correct": true, "explanation": "正确：“现代农业体系”指运用现代科技与管理的农业，与“集约化农业模式”一致。"}, {"text": "有机农业", "is_correct": false, "explanation": "语义：有机农业强调少用化学投入、保持多样性，与“依赖单一作物的大规模种植”和“对生物多样性构成挑战”相矛盾。"}, {"text": "小农经济", "is_correct": false, "explanation": "语义：小农经济以分散的小规模经营为主，与句中的“大规模种植”相冲突。"}, {"text": "农活", "is_correct": false, "explanation": "搭配：“农活”指具体的田间劳动，不说“农活体系”。"}], "explanations": {"现代农业": "正确：“现代农业体系”指运用现代科技与管理的农业，与“集约化农业模式”一致。", "有机农业": "语义：有机农业强调少用化学投入、保持多样性，与“依赖单一作物的大规模种植”和“对生物多样性构成挑战”相矛盾。", "小农经济": "语义：小农经济以分散的小规模经营为主，与句中的“大规模种植”相冲突。", "农活": "搭配：“农活”指具体的田间劳动，不说“农活体系”。"}, "sentence_index": 0, "correct_answer": "现代农业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把现代农业放进冰箱里了。", "explanation": "这里应该用〈蔬菜〉。放进冰箱的是具体的东西，现代农业是生产方式。"}, {"text": "农民用现代农业收割了小麦。", "explanation": "这里应该用〈农业机械〉。收割要靠具体的机器，现代农业是生产方式，不能当工具用。"}, {"text": "他每天早上骑现代农业去上班。", "explanation": "这里应该用〈自行车〉。骑的是交通工具，现代农业是生产方式。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23c349f0-88a0-4b80-b2a7-c87fc75f0484') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13838, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "现代农业", "is_correct": true, "explanation": "正确：“现代农业中”指当代以机械和科技为特征的农业，无人机喷洒正属于这一类。"}, {"text": "传统农业", "is_correct": false, "explanation": "语义：传统农业不使用无人机等现代装备，与句中的无人机喷洒相矛盾。"}, {"text": "手工业", "is_correct": false, "explanation": "语义：手工业靠人力生产，与“无人机喷洒农药”所用的装备不符。"}, {"text": "渔业", "is_correct": false, "explanation": "搭配：“喷洒农药”针对的是农作物，渔业一般不这样用。"}], "explanations": {"现代农业": "正确：“现代农业中”指当代以机械和科技为特征的农业，无人机喷洒正属于这一类。", "传统农业": "语义：传统农业不使用无人机等现代装备，与句中的无人机喷洒相矛盾。", "手工业": "语义：手工业靠人力生产，与“无人机喷洒农药”所用的装备不符。", "渔业": "搭配：“喷洒农药”针对的是农作物，渔业一般不这样用。"}, "sentence_index": 6, "correct_answer": "现代农业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这所工厂的生产线已经实现了现代农业。", "explanation": "这里应该用〈现代化〉。“现代农业”专指农业生产方式，不能用于工厂的生产线。"}, {"text": "他毕业于现代农业，现在在研究所工作。", "explanation": "这里应该用〈农业大学〉。毕业于的是学校，现代农业是生产方式，不是学校。"}, {"text": "农民给庄稼喷了现代农业。", "explanation": "这里应该用〈农药〉。喷洒的是具体的物质，现代农业是生产方式，不能被喷。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23c349f0-88a0-4b80-b2a7-c87fc75f0484') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13838, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "现代农业依靠科学技术大大提高了。", "corrected_sentence": "现代农业依靠科学技术大大提高了产量。", "error_description": "漏词错误：「提高了」后面缺少宾语，要补上「产量」，说「大大提高了产量」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23c349f0-88a0-4b80-b2a7-c87fc75f0484') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13838, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个县大力现代农业，农民收入增加了。", "corrected_sentence": "这个县大力发展现代农业，农民收入增加了。", "error_description": "漏词错误：“大力”后需要动词，应补出“发展”，说“大力发展现代农业”。错句中缺少动词“发展”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23c349f0-88a0-4b80-b2a7-c87fc75f0484') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
