INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13842, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23c349f0-88a0-4b80-b2a7-c87fc75f0484') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13842, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指一定空间范围内同种生物的个体集合。", "primary_collocate": null, "pronunciation": "zhǒng qún", "ipa": "ʈʂʊŋ˨˩˦ tɕʰyn˧˥", "syllable_count": 2, "sentences": [{"text": "栖息地碎片化、农药滥用、气候变化以及外来物种入侵，正在协同加速蜜蜂种群的衰退，进而威胁整个陆地生态系统的功能完整性。", "target_word": "种群", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "生态学家近年来通过高分辨率遥感数据与基因追踪技术，对蜜蜂的觅食路径、种群遗传结构及其与植物网络的互动关系展开了系统性研究。", "target_word": "种群", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "蜜蜂在这一网络中扮演着“生态枢纽”的角色——它们穿梭于不同植物之间，促进基因流动，增强植物种群的适应潜力，从而提升整个生态系统的抗逆能力。", "target_word": "种群", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这片湖里的鲫鱼种群数量越来越少。", "target_word": "种群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保护区里，老虎的种群慢慢变大了。", "target_word": "种群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究人员每年都要数一数这种鸟的种群数量。", "target_word": "种群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "食物不够时，动物种群会变小。", "target_word": "种群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个种群里的个体越多，竞争就越激烈。", "target_word": "种群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种蝴蝶的种群只生活在山谷里。", "target_word": "种群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了保护大熊猫，科学家想让它们的种群变大。", "target_word": "种群", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种群数量", "label": "复合"}, {"form": "种群密度", "label": "复合"}], "register": "书面", "sense_fingerprint": "生态学术语：一定区域内同种生物个体的总和，可数数量、密度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5fc0a8-d4f8-4387-9171-1f1a55380ca6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13842, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "花朵", "is_correct": false, "explanation": "语义：句中说的是蜜蜂这一生物群体，花朵不是蜜蜂的群体，句意不通。"}, {"text": "种群", "is_correct": true, "explanation": "同种生物个体的总和，蜜蜂种群的衰退符合句意。"}, {"text": "语言", "is_correct": false, "explanation": "语义：语言可以衰退，但“蜜蜂语言”指不了蜜蜂群体，句中谈的是生态问题。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“衰退”多用于种群、人口、经济，价格下降要说下跌，不说衰退。"}], "explanations": {"花朵": "语义：句中说的是蜜蜂这一生物群体，花朵不是蜜蜂的群体，句意不通。", "种群": "同种生物个体的总和，蜜蜂种群的衰退符合句意。", "语言": "语义：语言可以衰退，但“蜜蜂语言”指不了蜜蜂群体，句中谈的是生态问题。", "价格": "搭配：“衰退”多用于种群、人口、经济，价格下降要说下跌，不说衰退。"}, "sentence_index": 0, "correct_answer": "种群"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这群工人组成了一个种群，一起工作。", "explanation": "这里应该用〈群体〉。种群指同种生物的集合，人的集合要说群体。"}, {"text": "一只老鼠就是一个种群，它的寿命很短。", "explanation": "这里应该用〈个体〉。种群是多个同种个体的集合，单独一只老鼠是个体。"}, {"text": "这条街上的种群很拥挤，我们走不动了。", "explanation": "这里应该用〈人群〉。种群指同种生物的集合，街上拥挤的行人要说人群。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23c349f0-88a0-4b80-b2a7-c87fc75f0484') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13842, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小说", "is_correct": false, "explanation": "语义：小说不会因为食物不够而变小，句中指的是动物群体的数量。"}, {"text": "种群", "is_correct": true, "explanation": "同种生物个体的总和，食物不够时动物种群变小，符合句意。"}, {"text": "工资", "is_correct": false, "explanation": "语义：动物没有工资，“动物工资”不成立；且工资不会因食物不够而变化，句中谈的是动物种群。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不会因食物不够而变小，这与句中的生态因果不符。"}], "explanations": {"小说": "语义：小说不会因为食物不够而变小，句中指的是动物群体的数量。", "种群": "同种生物个体的总和，食物不够时动物种群变小，符合句意。", "工资": "语义：动物没有工资，“动物工资”不成立；且工资不会因食物不够而变化，句中谈的是动物种群。", "歌曲": "语义：歌曲不会因食物不够而变小，这与句中的生态因果不符。"}, "sentence_index": 6, "correct_answer": "种群"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "车站里挤满了种群，大家都在排队。", "explanation": "这里应该用〈人群〉。种群指同种生物的集合，挤在车站的人要说人群。"}, {"text": "这个种群的人每周一起开会，选出了主席。", "explanation": "这里应该用〈社团〉。种群是生物学术语，指同种生物的集合，人的社团不能说种群。"}, {"text": "我们种群的人常常一起过节，关系很好。", "explanation": "这里应该用〈家族〉。种群是生物学术语，人的家族不能说种群。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23c349f0-88a0-4b80-b2a7-c87fc75f0484') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13842, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这片森林里的鸟种群们数量在增加。", "corrected_sentence": "这片森林里的鸟种群数量在增加。", "error_description": "错误形式：“种群们”；正确形式：“种群”。“种群”是同种生物的集合名词，表示整体，不能再加“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23c349f0-88a0-4b80-b2a7-c87fc75f0484') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13842, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这片森林里有一只很大的鹿种群。", "corrected_sentence": "这片森林里有一个很大的鹿种群。", "error_description": "错误形式：“一只……种群”；正确形式：“一个……种群”。“只”用于单个动物，种群是许多同种个体的集合，应使用量词“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23c349f0-88a0-4b80-b2a7-c87fc75f0484') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
