INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13843, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "繁荣", "is_correct": true, "explanation": "正确。“经济衰退”的反义是“经济繁荣”。"}, {"text": "安静", "is_correct": false, "explanation": "安静形容声音或环境平和，与“衰退”没有反义关系。"}, {"text": "紧张", "is_correct": false, "explanation": "紧张形容情绪或局势，与“衰退”不构成反义。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚形容是否明白或明显，与“衰退”的意义无关。"}], "correct_answer": "繁荣", "explanations": {"繁荣": "正确。“经济衰退”的反义是“经济繁荣”。", "安静": "安静形容声音或环境平和，与“衰退”没有反义关系。", "紧张": "紧张形容情绪或局势，与“衰退”不构成反义。", "清楚": "清楚形容是否明白或明显，与“衰退”的意义无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14229369-8d88-474c-876a-3e73a53b642a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13843, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指事物向较差、较低的水平发展，比如经济、健康或能力等逐渐下降。", "primary_collocate": null, "pronunciation": "shuāi tuì", "ipa": "ʂuai̯˥ tʰuei̯˥˩", "syllable_count": 2, "sentences": [{"text": "栖息地碎片化、农药滥用、气候变化以及外来物种入侵，正在协同加速蜜蜂种群的衰退，进而威胁整个陆地生态系统的功能完整性。", "target_word": "衰退", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "随着年龄增长，老人的记忆力逐渐衰退。", "target_word": "衰退", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的经济连续三年衰退，失业人数不断上升。", "target_word": "衰退", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长期熬夜会使人的体力和视力慢慢衰退。", "target_word": "衰退", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂搬走以后，这座小城的工业很快衰退了。", "target_word": "衰退", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古罗马帝国为什么会衰退？", "target_word": "衰退", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说，他的肾功能已经开始衰退。", "target_word": "衰退", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "气候变暖以后，这片湖边的渔业逐年衰退。", "target_word": "衰退", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的业绩持续衰退，老板决定调整方向。", "target_word": "衰退", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济衰退时，很多人不敢随便花钱。", "target_word": "衰退", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "衰退了", "label": "体标"}, {"form": "衰退过", "label": "体标"}, {"form": "衰退期", "label": "复合"}], "register": "书面", "sense_fingerprint": "衰退|动词|经济、健康、能力等向较差水平逐渐发展", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fed2657-c642-412b-9bc3-e34e316666ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13843, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "衰退", "is_correct": true, "explanation": "正确答案，shuāi tuì。"}, {"text": "摔碎", "is_correct": false, "explanation": "shuāi suì（碎）与 shuāi tuì 只有声母不同（s 与 t），意思是东西摔成碎片。"}, {"text": "摔腿", "is_correct": false, "explanation": "shuāi tuǐ（腿，第三声）与 shuāi tuì（第四声）只有第二个音节的声调不同，意思是摔伤了腿。"}, {"text": "甩腿", "is_correct": false, "explanation": "shuǎi tuǐ 与 shuāi tuì 两个音节的声调都不同，意思是挥动腿。"}], "explanations": {"衰退": "正确答案，shuāi tuì。", "摔碎": "shuāi suì（碎）与 shuāi tuì 只有声母不同（s 与 t），意思是东西摔成碎片。", "摔腿": "shuāi tuǐ（腿，第三声）与 shuāi tuì（第四声）只有第二个音节的声调不同，意思是摔伤了腿。", "甩腿": "shuǎi tuǐ 与 shuāi tuì 两个音节的声调都不同，意思是挥动腿。"}, "sentence_index": null, "correct_answer": "衰退"}, "level_3": {"options": [{"text": "衰退", "is_correct": true, "explanation": "正确。种群数量逐渐下降，才会威胁整个生态系统的完整性。"}, {"text": "恢复", "is_correct": false, "explanation": "语义：“恢复”表示回升，与后文“威胁整个陆地生态系统”的语义相矛盾。"}, {"text": "维持", "is_correct": false, "explanation": "搭配：“加速”表示促使变化，与“维持”意思相反，不能说“加速蜜蜂种群的维持”。"}, {"text": "保护", "is_correct": false, "explanation": "语义：“保护”是减少伤害的行为，与“威胁”的语义相反，句子不通。"}], "explanations": {"衰退": "正确。种群数量逐渐下降，才会威胁整个生态系统的完整性。", "恢复": "语义：“恢复”表示回升，与后文“威胁整个陆地生态系统”的语义相矛盾。", "维持": "搭配：“加速”表示促使变化，与“维持”意思相反，不能说“加速蜜蜂种群的维持”。", "保护": "语义：“保护”是减少伤害的行为，与“威胁”的语义相反，句子不通。"}, "sentence_index": 0, "correct_answer": "衰退"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天坚持锻炼，身体的各项功能慢慢衰退了。", "explanation": "这里应该用〈增强〉。衰退指向较差的水平发展，坚持锻炼后身体功能应当增强。"}, {"text": "夜里，敌军悄悄衰退了。", "explanation": "这里应该用〈撤退〉。衰退指水平或状态逐渐变差，不指军队离开阵地。"}, {"text": "经过三个月的治疗，他的肾功能不断衰退，身体好了很多。", "explanation": "这里应该用〈好转〉。衰退指向较差的水平发展，身体变好要说好转。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14229369-8d88-474c-876a-3e73a53b642a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13843, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "衰退", "is_correct": true, "explanation": "正确。肾功能逐渐变差，与“已经开始”相符。"}, {"text": "生长", "is_correct": false, "explanation": "搭配：“生长”用于生物的增长发育，成年人的肾功能不能说生长。"}, {"text": "繁殖", "is_correct": false, "explanation": "语义：“繁殖”指生物增加个体数量，与器官功能无关。"}, {"text": "发芽", "is_correct": false, "explanation": "语义：“发芽”指植物的种子长出新芽，与人体器官的变化不符。"}], "explanations": {"衰退": "正确。肾功能逐渐变差，与“已经开始”相符。", "生长": "搭配：“生长”用于生物的增长发育，成年人的肾功能不能说生长。", "繁殖": "语义：“繁殖”指生物增加个体数量，与器官功能无关。", "发芽": "语义：“发芽”指植物的种子长出新芽，与人体器官的变化不符。"}, "sentence_index": 6, "correct_answer": "衰退"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "士兵向后衰退了三步。", "explanation": "这里应该用〈后退〉。衰退指水平或状态变差，不表示位置的移动。"}, {"text": "他每次练习都比上次衰退，技术越来越好。", "explanation": "这里应该用〈进步〉。衰退指向较差的水平发展，技术越来越好要说进步。"}, {"text": "这棵树的枝叶衰退得很茂盛。", "explanation": "这里应该用〈生长〉。衰退指向较差的水平发展，不能用来形容枝叶茂盛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14229369-8d88-474c-876a-3e73a53b642a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13843, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "长期不运动，身体的功能会逐渐被衰退。", "corrected_sentence": "长期不运动，身体的功能会逐渐衰退。", "error_description": "“衰退”是不及物动词，不能用“被”字句。正确形式是“功能会逐渐衰退”，去掉“被”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14229369-8d88-474c-876a-3e73a53b642a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13843, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医生说，这种药吃久了，肝脏的功能衰退的很厉害。", "corrected_sentence": "医生说，这种药吃久了，肝脏的功能衰退得很厉害。", "error_description": "“衰退”作程度补语时要用“得”，不能用“的”。句中“的”应改为“得”，即“衰退得很厉害”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14229369-8d88-474c-876a-3e73a53b642a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
