INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13846, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指动物寻找食物。", "primary_collocate": null, "pronunciation": "mì shí", "ipa": "mi˥˩ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "生态学家近年来通过高分辨率遥感数据与基因追踪技术，对蜜蜂的觅食路径、种群遗传结构及其与植物网络的互动关系展开了系统性研究。", "target_word": "觅食", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "清晨，小鸟飞到草地上觅食。", "target_word": "觅食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天雪很大，野兔很难出来觅食。", "target_word": "觅食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "母鸡带着小鸡在院子里觅食。", "target_word": "觅食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里，狐狸常常出来觅食。", "target_word": "觅食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "燕子飞得很低，正在河边觅食。", "target_word": "觅食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大熊猫每天要用很多时间觅食。", "target_word": "觅食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海鸥跟着渔船，在海面上觅食。", "target_word": "觅食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蚂蚁成群结队地出去觅食。", "target_word": "觅食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑以前，鸭子们都在河里觅食。", "target_word": "觅食", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "觅食了", "label": "体标"}, {"form": "觅食过", "label": "体标"}], "register": "中性", "sense_fingerprint": "动物寻找食物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fed2657-c642-412b-9bc3-e34e316666ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13846, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "觅食", "is_correct": true, "explanation": "正确：觅食（mì shí），指动物寻找食物。"}, {"text": "密室", "is_correct": false, "explanation": "mì shì（第四声）与 mì shí（第二声）声调不同，意思是秘密的房间。"}, {"text": "迷失", "is_correct": false, "explanation": "mí shī（第二、第一声）与 mì shí（第四、第二声）声调不同，意思是迷路、找不到。"}, {"text": "米食", "is_correct": false, "explanation": "mǐ shí（第三声）与 mì shí（第四声）声调不同，意思是用米做的食物。"}], "explanations": {"觅食": "正确：觅食（mì shí），指动物寻找食物。", "密室": "mì shì（第四声）与 mì shí（第二声）声调不同，意思是秘密的房间。", "迷失": "mí shī（第二、第一声）与 mì shí（第四、第二声）声调不同，意思是迷路、找不到。", "米食": "mǐ shí（第三声）与 mì shí（第四声）声调不同，意思是用米做的食物。"}, "sentence_index": null, "correct_answer": "觅食"}, "level_3": {"options": [{"text": "冬眠", "is_correct": false, "explanation": "语义：“冬眠”是动物越冬时的休眠，与“路径”无关。"}, {"text": "觅食", "is_correct": true, "explanation": "正确：修饰“路径”，指蜜蜂寻找食物的路线。"}, {"text": "织网", "is_correct": false, "explanation": "语义：织网是蜘蛛的行为，蜜蜂不织网，“织网路径”说不通。"}, {"text": "唱歌", "is_correct": false, "explanation": "搭配：“唱歌”不用来修饰“路径”，二者不搭配。"}], "explanations": {"冬眠": "语义：“冬眠”是动物越冬时的休眠，与“路径”无关。", "觅食": "正确：修饰“路径”，指蜜蜂寻找食物的路线。", "织网": "语义：织网是蜘蛛的行为，蜜蜂不织网，“织网路径”说不通。", "唱歌": "搭配：“唱歌”不用来修饰“路径”，二者不搭配。"}, "sentence_index": 0, "correct_answer": "觅食"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医院里的病人每天都在觅食。", "explanation": "这里应该用〈进食〉。觅食只说动物寻找食物，人吃东西用〈进食〉或〈吃饭〉。"}, {"text": "这株玉米每天都在地里觅食，长得很快。", "explanation": "这里应该用〈吸收养分〉。觅食只指动物寻找食物，植物靠根吸收养分。"}, {"text": "这台洗衣机每天都在厨房里觅食。", "explanation": "这里应该用〈运转〉。洗衣机不会寻找食物，觅食只指动物寻找食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14229369-8d88-474c-876a-3e73a53b642a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13846, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "写作业", "is_correct": false, "explanation": "语义：大熊猫不写作业，这与动物寻找食物的日常行为不符。"}, {"text": "觅食", "is_correct": true, "explanation": "正确：作谓语，说明大熊猫每天花很多时间寻找食物。"}, {"text": "开会", "is_correct": false, "explanation": "语义：大熊猫不会开会，与动物的日常行为不符。"}, {"text": "演讲", "is_correct": false, "explanation": "语义：大熊猫不会演讲，与“用很多时间”的日常行为不符。"}], "explanations": {"写作业": "语义：大熊猫不写作业，这与动物寻找食物的日常行为不符。", "觅食": "正确：作谓语，说明大熊猫每天花很多时间寻找食物。", "开会": "语义：大熊猫不会开会，与动物的日常行为不符。", "演讲": "语义：大熊猫不会演讲，与“用很多时间”的日常行为不符。"}, "sentence_index": 6, "correct_answer": "觅食"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆汽车在路边觅食，等了很久。", "explanation": "这里应该用〈停靠〉。觅食只指动物寻找食物，汽车停在路边要说停靠。"}, {"text": "警察在山里觅食失踪的孩子。", "explanation": "这里应该用〈搜寻〉。搜寻用于寻找失踪的人或物，觅食只指动物找吃的。"}, {"text": "这座桥在河上觅食了几十年。", "explanation": "这里应该用〈矗立〉。觅食只指动物寻找食物，桥只能说矗立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14229369-8d88-474c-876a-3e73a53b642a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13846, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只狐狸在林子里在觅食了一整夜。", "corrected_sentence": "那只狐狸在林子里觅食了一整夜。", "error_description": "错误在多加了一个“在”：“在林子里”已表示地点，动词“觅食”前不应再加“在”，应为“在林子里觅食了一整夜”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14229369-8d88-474c-876a-3e73a53b642a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13846, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小狐狸跟着妈妈去河边在觅食。", "corrected_sentence": "小狐狸跟着妈妈去河边觅食。", "error_description": "错误在多加了一个“在”：“去河边”已表示去向和地点，动词“觅食”前不应再加“在”，应为“去河边觅食”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14229369-8d88-474c-876a-3e73a53b642a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
