INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13847, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "生物体的基因和性状通过繁殖传递给后代的过程。", "primary_collocate": null, "pronunciation": "yí chuán", "ipa": "i˧˥ ʈʂʰwan˧˥", "syllable_count": 2, "sentences": [{"text": "生态学家近年来通过高分辨率遥感数据与基因追踪技术，对蜜蜂的觅食路径、种群遗传结构及其与植物网络的互动关系展开了系统性研究。", "target_word": "遗传", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "身高与遗传有关。", "target_word": "遗传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遗传和环境都会影响孩子的身高。", "target_word": "遗传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家研究遗传已经一百多年了。", "target_word": "遗传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种病和遗传有很大关系。", "target_word": "遗传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "豌豆实验帮助人们认识了遗传的规律。", "target_word": "遗传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遗传决定了眼睛的颜色。", "target_word": "遗传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遗传信息都保存在基因里。", "target_word": "遗传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遗传与变异是生物的两个特点。", "target_word": "遗传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的好嗓子来自遗传。", "target_word": "遗传", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "遗传病", "label": "复合"}, {"form": "遗传学", "label": "复合"}], "register": "书面", "sense_fingerprint": "生物基因性状传给后代的过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fed2657-c642-412b-9bc3-e34e316666ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13847, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "经济", "is_correct": false, "explanation": "语义：“经济结构”指社会经济的构成，用于种群的生物学研究不合语境。"}, {"text": "遗传", "is_correct": true, "explanation": "正确。“种群遗传结构”指种群中基因传递形成的结构特征，与句中的生物学研究语境一致。"}, {"text": "钢铁", "is_correct": false, "explanation": "搭配：“钢铁结构”是工程用语，不能与“种群”搭配。"}, {"text": "八卦", "is_correct": false, "explanation": "语域：“八卦”是口语词，与这篇书面、科学的叙述语域不符。"}], "explanations": {"经济": "语义：“经济结构”指社会经济的构成，用于种群的生物学研究不合语境。", "遗传": "正确。“种群遗传结构”指种群中基因传递形成的结构特征，与句中的生物学研究语境一致。", "钢铁": "搭配：“钢铁结构”是工程用语，不能与“种群”搭配。", "八卦": "语域：“八卦”是口语词，与这篇书面、科学的叙述语域不符。"}, "sentence_index": 0, "correct_answer": "遗传"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把这家公司遗传给了侄子。", "explanation": "这里应该用〈继承〉。企业、财产的承接用继承；遗传只用于生物性状的代代传递，不能用来说公司。"}, {"text": "这条新闻很快遗传到了全国。", "explanation": "这里应该用〈传播〉。消息、思想的扩散用传播；遗传只用于生物性状的代代传递，不能用来说新闻。"}, {"text": "老师把自己的经验遗传给了学生。", "explanation": "这里应该用〈传授〉。知识、经验的传递用传授；遗传只用于生物性状的代代传递。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14229369-8d88-474c-876a-3e73a53b642a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13847, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：天气是环境因素，不能决定眼睛的颜色。"}, {"text": "遗传", "is_correct": true, "explanation": "正确。遗传决定生物性状，眼睛颜色属于遗传性状，句意成立。"}, {"text": "发型", "is_correct": false, "explanation": "体貌：发型属于外在装扮，不是决定眼睛颜色的身体特征。"}, {"text": "运气", "is_correct": false, "explanation": "语义：运气与生物性状无关，不能决定眼睛的颜色。"}], "explanations": {"天气": "语义：天气是环境因素，不能决定眼睛的颜色。", "遗传": "正确。遗传决定生物性状，眼睛颜色属于遗传性状，句意成立。", "发型": "体貌：发型属于外在装扮，不是决定眼睛颜色的身体特征。", "运气": "语义：运气与生物性状无关，不能决定眼睛的颜色。"}, "sentence_index": 6, "correct_answer": "遗传"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种流感会通过飞沫遗传。", "explanation": "这里应该用〈传染〉。流感靠飞沫传播是传染；遗传指基因传给后代，不能通过空气传递。"}, {"text": "我们的友谊已经遗传了二十年。", "explanation": "这里应该用〈延续〉。友谊的持续用延续；遗传只用于生物性状的代代传递。"}, {"text": "这首老歌在村里遗传了几百年。", "explanation": "这里应该用〈流传〉。歌曲、故事在人群中传下来用流传；遗传只用于生物性状的代代传递。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14229369-8d88-474c-876a-3e73a53b642a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13847, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种病的遗传了原因还没有查清。", "corrected_sentence": "这种病的遗传原因还没有查清。", "error_description": "错误：“遗传”作定语修饰“原因”时不能带“了”，应为“遗传原因”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14229369-8d88-474c-876a-3e73a53b642a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13847, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条遗传病需要尽早检查。", "corrected_sentence": "这种遗传病需要尽早检查。", "error_description": "错误：“遗传病”前应用量词“种”，写成“条”不对；“条”用于细长的事物，不用于疾病。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14229369-8d88-474c-876a-3e73a53b642a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
