INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13850, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "开始大规模、详细地进行讨论、调查、分析或研究等活动。", "primary_collocate": null, "pronunciation": "zhǎn kāi", "ipa": "ʈʂan˨˩˦ kʰaɪ˥˥", "syllable_count": 2, "sentences": [{"text": "大家对这个问题展开了讨论。", "target_word": "展开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察对这件事展开调查。", "target_word": "展开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们明天展开详细的研究。", "target_word": "展开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们展开了热烈的讨论。", "target_word": "展开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司对新产品展开了分析。", "target_word": "展开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师和同学对这个问题展开了深入的分析。", "target_word": "展开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们对环境问题展开研究。", "target_word": "展开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生对病人的病情展开了详细的研究。", "target_word": "展开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家对这种新材料展开了详细的研究。", "target_word": "展开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报社对这起事故展开了调查。", "target_word": "展开", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "展开了", "label": "完成体"}, {"form": "展开着", "label": "持续体"}, {"form": "展开过", "label": "经历体"}], "register": "书面", "sense_fingerprint": "开始大规模、详细地进行讨论、调查、研究等活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4f8477c-c623-4811-8372-e8a5d9f6c5fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13850, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "展开", "is_correct": true, "explanation": "正确答案。“展开了讨论”指开始进行讨论，与“对这个问题”搭配。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“讨论”搭配。"}, {"text": "穿", "is_correct": false, "explanation": "语义：“穿”的对象是衣物，不能用于“讨论”。"}, {"text": "出售", "is_correct": false, "explanation": "语义：“出售”的对象是商品，不能用于“讨论”。"}], "explanations": {"展开": "正确答案。“展开了讨论”指开始进行讨论，与“对这个问题”搭配。", "吃": "搭配：“吃”不能与“讨论”搭配。", "穿": "语义：“穿”的对象是衣物，不能用于“讨论”。", "出售": "语义：“出售”的对象是商品，不能用于“讨论”。"}, "sentence_index": 0, "correct_answer": "展开"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校展开了一次教师大会。", "explanation": "这里应该用〈召开〉。会议要说召开，展开多用于讨论、调查、研究等活动。"}, {"text": "他展开了自己的错误，向大家道了歉。", "explanation": "这里应该用〈承认〉。错误要说承认，展开用于讨论、调查、研究等活动。"}, {"text": "他展开了嘴，却一句话也没说。", "explanation": "这里应该用〈张开〉。嘴要说张开，展开不用于嘴的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b6de39-9b1c-4462-afcd-62cb8c028ff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13850, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "展开", "is_correct": true, "explanation": "正确答案。“展开研究”指开始详细地进行研究，符合语境。"}, {"text": "陷入", "is_correct": false, "explanation": "配价：“陷入”需接困境、状态一类的宾语，不接“研究”。"}, {"text": "理发", "is_correct": false, "explanation": "语义：理发指剪头发，与“研究环境问题”无关。"}, {"text": "散步", "is_correct": false, "explanation": "语义：散步指走动，不能用来研究问题。"}], "explanations": {"展开": "正确答案。“展开研究”指开始详细地进行研究，符合语境。", "陷入": "配价：“陷入”需接困境、状态一类的宾语，不接“研究”。", "理发": "语义：理发指剪头发，与“研究环境问题”无关。", "散步": "语义：散步指走动，不能用来研究问题。"}, "sentence_index": 6, "correct_answer": "展开"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校展开了一场演唱会。", "explanation": "这里应该用〈举办〉。演唱会要说举办，展开多用于调查、讨论等活动。"}, {"text": "两家公司展开了一份合同，双方都很满意。", "explanation": "这里应该用〈签订〉。合同要说签订，展开用于调查、讨论、研究等活动。"}, {"text": "他展开了这项责任。", "explanation": "这里应该用〈承担〉。责任要说承担，展开不能用于责任。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b6de39-9b1c-4462-afcd-62cb8c028ff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13850, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校对这件事了展开调查。", "corrected_sentence": "学校对这件事展开调查。", "error_description": "体标位置错误：“了”放在动词“展开”之前是错误的，应删去。“对这件事展开调查”不带“了”即可成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b6de39-9b1c-4462-afcd-62cb8c028ff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13850, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们曾对这一现象展开了过研究。", "corrected_sentence": "我们曾对这一现象展开过研究。", "error_description": "体标错误：表示经历要用“展开过”，“了”与“过”不能同用，应删去“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b6de39-9b1c-4462-afcd-62cb8c028ff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
