INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13852, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一片具有特定生态特征的地理空间", "primary_collocate": null, "pronunciation": "qū yù", "ipa": "tɕʰy˥ y˥˩", "syllable_count": 2, "sentences": [{"text": "这片区域有很多珍稀的鸟。", "target_word": "区域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湿地区域是候鸟的家。", "target_word": "区域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙漠区域的雨水很少。", "target_word": "区域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个保护区域不能随便打猎。", "target_word": "区域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的区域有很多海草。", "target_word": "区域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高山区域的空气很干净，植物也很多。", "target_word": "区域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个区域的气候湿润，适合很多植物生长。", "target_word": "区域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "热带雨林区域里住着各种动物。", "target_word": "区域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家在河流区域发现了一种小鱼。", "target_word": "区域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北极区域的冬天特别冷。", "target_word": "区域", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "區域", "label": "繁体"}], "register": "中性", "sense_fingerprint": "区域：具有特定生态特征的一片地理空间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f024bdf7-0d89-40d8-a324-f9e3513e83de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13852, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "时代", "is_correct": false, "explanation": "搭配：量词「片」不搭配「时代」，「这片时代」不成立。"}, {"text": "区域", "is_correct": true, "explanation": "区域指一片具有特定自然特征的地理空间，「这片区域」有珍稀的鸟，与语境相符。"}, {"text": "人口", "is_correct": false, "explanation": "语义：人口指人的总数，不能用来指有珍稀鸟类的自然地带。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干是食品，不能是有珍稀鸟类的自然地带，句意不通。"}], "explanations": {"时代": "搭配：量词「片」不搭配「时代」，「这片时代」不成立。", "区域": "区域指一片具有特定自然特征的地理空间，「这片区域」有珍稀的鸟，与语境相符。", "人口": "语义：人口指人的总数，不能用来指有珍稀鸟类的自然地带。", "饼干": "语义：饼干是食品，不能是有珍稀鸟类的自然地带，句意不通。"}, "sentence_index": 0, "correct_answer": "区域"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这片湿地的区域会游泳。", "explanation": "这里应该用〈鸭子〉（或〈鱼〉）。区域是地理空间，不会游泳；会游泳的是动物，要说“鸭子”或“鱼”。"}, {"text": "这片林子的区域很弱，草很少。", "explanation": "这里应该用〈光照〉。区域指地理空间，描述光线强弱要用光照，不能说「区域很弱」。"}, {"text": "这片区域今天很生气，一直在下雨。", "explanation": "这里应该用〈天气〉。区域是地理空间，不会生气；说下雨的情况要用天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9636749-a4b0-4b87-a16b-1e4ae020946e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13852, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "学生", "is_correct": false, "explanation": "语义：学生是人，没有「气候」，「这个学生的气候湿润」说不通。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是书籍，不能有气候，句子语义不通。"}, {"text": "区域", "is_correct": true, "explanation": "区域指一定范围的地理空间，「这个区域的气候湿润」指该地的气候，适合植物生长，与语境相符。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包是食物，没有气候，“这个面包的气候湿润”说不通。"}], "explanations": {"学生": "语义：学生是人，没有「气候」，「这个学生的气候湿润」说不通。", "课本": "语义：课本是书籍，不能有气候，句子语义不通。", "区域": "区域指一定范围的地理空间，「这个区域的气候湿润」指该地的气候，适合植物生长，与语境相符。", "面包": "语义：面包是食物，没有气候，“这个面包的气候湿润”说不通。"}, "sentence_index": 6, "correct_answer": "区域"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座雪山的区域很高。", "explanation": "这里应该用〈海拔〉。区域指空间范围，说高低要用海拔。"}, {"text": "这片草原的区域很茂盛，草有一米高。", "explanation": "这里应该用〈植被〉。区域指空间，植物生长茂盛要用植被，不能说「区域很茂盛」。"}, {"text": "这片森林的区域长得很绿。", "explanation": "这里应该用〈树木〉。区域是空间范围，不会生长；长得很绿的是树木。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9636749-a4b0-4b87-a16b-1e4ae020946e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13852, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "保护区里划出了一只区域给候鸟。", "corrected_sentence": "保护区里划出了一片区域给候鸟。", "error_description": "量词错误：「区域」应用「片」「个」等量词，「只」多用于动物或成对的东西，不能用于区域。正确说法是「一片区域」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9636749-a4b0-4b87-a16b-1e4ae020946e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13852, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "科学家划定了两保护区域。", "corrected_sentence": "科学家划定了两片保护区域。", "error_description": "量词缺失：数词「两」后面要加量词，应说「两片保护区域」，不能直接说「两保护区域」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9636749-a4b0-4b87-a16b-1e4ae020946e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
