INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13853, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "丰度指在某一体系中某种元素或同位素所占的相对比例或含量。", "primary_collocate": null, "pronunciation": "fēng dù", "ipa": "fəŋ˥ tu˥˩", "syllable_count": 2, "sentences": [{"text": "这些研究揭示了一个值得警惕的现象：当某一地层中放射性同位素的丰度下降时，依据其衰变规律推算出的岩石年龄便会出现明显偏差，进而动摇整个地质年代序列的可靠性。", "target_word": "丰度", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "地壳中氧元素的丰度最高。", "target_word": "丰度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家测量了这种同位素的丰度。", "target_word": "丰度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海水里这种元素的丰度很低。", "target_word": "丰度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这颗星星上氢的丰度比太阳高。", "target_word": "丰度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "岩石样品中铁元素的丰度不同。", "target_word": "丰度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "研究者比较了两种矿石的元素丰度。", "target_word": "丰度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "宇宙中氢元素的丰度远远高于其他元素。", "target_word": "丰度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同位素丰度可以帮助我们判断石头的年龄。", "target_word": "丰度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月球样品中某些元素的丰度和地球相近。", "target_word": "丰度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "豐度", "label": "繁体"}], "register": "书面", "sense_fingerprint": "元素或同位素在体系中所占的相对比例或含量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18462fa8-6019-40c1-b9b3-2f552a608b56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13853, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "丰度", "is_correct": true, "explanation": "丰度（fēng dù）即本词，指某种元素或同位素在体系中所占的相对比例。"}, {"text": "蜂毒", "is_correct": false, "explanation": "dú（第二声）与 dù（第四声）声调不同，意思是蜜蜂的毒液。"}, {"text": "分度", "is_correct": false, "explanation": "fēn 与 fēng 韵尾不同（n 与 ng），意思是把刻度分成若干等份。"}, {"text": "封堵", "is_correct": false, "explanation": "dǔ（第三声）与 dù（第四声）声调不同，意思是堵住、阻塞。"}], "explanations": {"丰度": "丰度（fēng dù）即本词，指某种元素或同位素在体系中所占的相对比例。", "蜂毒": "dú（第二声）与 dù（第四声）声调不同，意思是蜜蜂的毒液。", "分度": "fēn 与 fēng 韵尾不同（n 与 ng），意思是把刻度分成若干等份。", "封堵": "dǔ（第三声）与 dù（第四声）声调不同，意思是堵住、阻塞。"}, "sentence_index": null, "correct_answer": "丰度"}, "level_3": {"options": [{"text": "丰度", "is_correct": true, "explanation": "正确。「丰度」指某种同位素在地层中所占的相对比例，与「下降」搭配，符合句意。"}, {"text": "分布", "is_correct": false, "explanation": "搭配：「分布」指空间上的分散状况，不能说「同位素的分布下降」。"}, {"text": "体型", "is_correct": false, "explanation": "体貌：「体型」指身体的形状和大小，不能说同位素的「体型下降」。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色没有升降，与同位素比例的变化无关。"}], "explanations": {"丰度": "正确。「丰度」指某种同位素在地层中所占的相对比例，与「下降」搭配，符合句意。", "分布": "搭配：「分布」指空间上的分散状况，不能说「同位素的分布下降」。", "体型": "体貌：「体型」指身体的形状和大小，不能说同位素的「体型下降」。", "颜色": "语义：颜色没有升降，与同位素比例的变化无关。"}, "sentence_index": 0, "correct_answer": "丰度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块石头的丰度是十公斤。", "explanation": "这里应该用〈重量〉。丰度表示某种元素在体系中所占的相对比例，没有单位，不能用“公斤”计量。"}, {"text": "他的英语丰度很高。", "explanation": "这里应该用〈水平〉。丰度指元素或同位素在某体系中所占的相对比例，是含量概念，不用来形容人的语言能力；说语言能力要用“水平”。"}, {"text": "这块地的丰度很大。", "explanation": "这里应该用〈面积〉。丰度是相对比例，不表示土地的大小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ef5f69c-3831-4753-a13e-0e4d59efd68f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13853, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "丰度", "is_correct": true, "explanation": "丰度（fēng dù）即本词，指某种元素或同位素在体系中所占的相对比例。"}, {"text": "丰都", "is_correct": false, "explanation": "dū（第一声）与 dù（第四声）声调不同，丰都是重庆的一个县名，与元素含量无关。"}, {"text": "风土", "is_correct": false, "explanation": "tǔ 与 dù 声母和声调都不同（t 与 d，第三声与第四声），意思是一个地方的自然环境和风俗习惯。"}, {"text": "风速", "is_correct": false, "explanation": "sù 与 dù 声母不同（s 与 d），意思是风的快慢。"}], "explanations": {"丰度": "丰度（fēng dù）即本词，指某种元素或同位素在体系中所占的相对比例。", "丰都": "dū（第一声）与 dù（第四声）声调不同，丰都是重庆的一个县名，与元素含量无关。", "风土": "tǔ 与 dù 声母和声调都不同（t 与 d，第三声与第四声），意思是一个地方的自然环境和风俗习惯。", "风速": "sù 与 dù 声母不同（s 与 d），意思是风的快慢。"}, "sentence_index": null, "correct_answer": "丰度"}, "level_3": {"options": [{"text": "丰度", "is_correct": true, "explanation": "丰度指元素在矿石中的相对比例，与“比较”搭配，符合句意。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：矿石和元素没有脾气，句子比较的是元素的比例。"}, {"text": "个头", "is_correct": false, "explanation": "语域：“个头”是口语，与这里的书面研究语境不符，也不用于说元素的大小。"}, {"text": "味道", "is_correct": false, "explanation": "语义：元素没有味道可以比较，句子比较的是元素的比例。"}], "explanations": {"丰度": "丰度指元素在矿石中的相对比例，与“比较”搭配，符合句意。", "脾气": "语义：矿石和元素没有脾气，句子比较的是元素的比例。", "个头": "语域：“个头”是口语，与这里的书面研究语境不符，也不用于说元素的大小。", "味道": "语义：元素没有味道可以比较，句子比较的是元素的比例。"}, "sentence_index": 6, "correct_answer": "丰度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个班的丰度很多。", "explanation": "这里应该用〈人数〉。丰度是相对比例，不用来说班里有多少人。"}, {"text": "今年小麦的丰度很高。", "explanation": "这里应该用〈产量〉。丰度表示某物质在体系中的相对比例，不是作物的收获数量。"}, {"text": "这本小说的丰度很精彩。", "explanation": "这里应该用〈内容〉。丰度是元素或同位素的相对比例，不用来评价书的内容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ef5f69c-3831-4753-a13e-0e4d59efd68f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13853, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这颗行星上氦的一只丰度比地球低。", "corrected_sentence": "这颗行星上氦的丰度比地球低。", "error_description": "量词用错：“丰度”是抽象名词，不能用“只”（“只”用于动物等具体事物）。应去掉“一只”，写作“这颗行星上氦的丰度比地球低”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ef5f69c-3831-4753-a13e-0e4d59efd68f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13853, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "冥王星表面氮的丰度了远低于地球。", "corrected_sentence": "冥王星表面氮的丰度远低于地球。", "error_description": "“了”用错：“丰度”是名词，不能直接带“了”。应去掉“了”，写作“冥王星表面氮的丰度远低于地球”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ef5f69c-3831-4753-a13e-0e4d59efd68f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
