INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13858, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "身体里有脊柱（脊梁骨）的动物，包括鱼类、两栖类、爬行类、鸟类和哺乳类。", "primary_collocate": null, "pronunciation": "jǐ zhuī dòng wù", "ipa": "tɕi˨˩ ʈʂweɪ˥ tʊŋ˥˩ wu˥˩", "syllable_count": 4, "sentences": [{"text": "研究人员在一片湿地中调查发现，鱼类、两栖类和鸟类等生物都是脊椎动物，它们的身体里都有脊柱，因而被归为同一大类，在生态系统中占据重要位置。", "target_word": "脊椎动物", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "鱼、鸟和人都是脊椎动物。", "target_word": "脊椎动物", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "脊椎动物的身体里都有脊柱。", "target_word": "脊椎动物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "青蛙属于两栖类，是一种脊椎动物。", "target_word": "脊椎动物", "complexity_tier": "T3", "furigana": "qīng wā shǔ yú liǎng qī lèi, shì yī zhǒng jǐ zhuī dòng wù。", "sentence_source": "generated"}, {"text": "脊椎动物分为鱼类、两栖类、爬行类、鸟类和哺乳类。", "target_word": "脊椎动物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜘蛛不是脊椎动物，因为它没有脊柱。", "target_word": "脊椎动物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "鲸是海里最大的脊椎动物。", "target_word": "脊椎动物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位老师带学生观察池塘里的脊椎动物。", "target_word": "脊椎动物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昆虫的骨骼在体外，脊椎动物的骨骼在体内。", "target_word": "脊椎动物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种脊椎动物生活在水里，用鳃呼吸。", "target_word": "脊椎动物", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "无脊椎动物", "label": "复合"}, {"form": "脊椎動物", "label": "繁体"}], "register": "书面", "sense_fingerprint": "身体里有脊柱的动物的总称，含鱼、两栖、爬行、鸟、哺乳五类", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f50129e-3400-4b77-b079-c3bc4a5b6d48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13858, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "脊椎动物", "is_correct": true, "explanation": "正确。鱼类、两栖类和鸟类的身体里都有脊柱，同属“脊椎动物”这一大类。"}, {"text": "植物", "is_correct": false, "explanation": "语义：植物不是动物，无法概括鱼类、两栖类和鸟类。"}, {"text": "昆虫", "is_correct": false, "explanation": "语义：昆虫没有脊柱，属于无脊椎动物，不能概括有脊柱的鱼类、两栖类和鸟类。"}, {"text": "岩石", "is_correct": false, "explanation": "语义：岩石不是生物，无法概括鱼类、两栖类和鸟类。"}], "explanations": {"脊椎动物": "正确。鱼类、两栖类和鸟类的身体里都有脊柱，同属“脊椎动物”这一大类。", "植物": "语义：植物不是动物，无法概括鱼类、两栖类和鸟类。", "昆虫": "语义：昆虫没有脊柱，属于无脊椎动物，不能概括有脊柱的鱼类、两栖类和鸟类。", "岩石": "语义：岩石不是生物，无法概括鱼类、两栖类和鸟类。"}, "sentence_index": 0, "correct_answer": "脊椎动物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的脊椎动物受伤了，今天得去医院拍片。", "explanation": "用错义项：这里指人的脊柱，但“脊椎动物”是动物类群的名称，不能用来指身体的部位。"}, {"text": "这座池塘里住着一座脊椎动物。", "explanation": "量词用错：“座”用于山、楼等大型固定物，不能用来数动物。“脊椎动物”作类别时量词用“种”。"}, {"text": "这只蜘蛛没有脊柱，属于脊椎动物。", "explanation": "这里应该用〈无脊椎动物〉。脊椎动物有脊柱，蜘蛛没有脊柱，不能归入这一类。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e55e79e-b446-4340-b8e9-1c05af53956a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13858, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脊椎动物", "is_correct": true, "explanation": "正确。鲸有脊柱，是海里最大的脊椎动物。"}, {"text": "岛屿", "is_correct": false, "explanation": "语义：鲸是动物，不是岛屿，句中指的是海里的生物。"}, {"text": "建筑", "is_correct": false, "explanation": "语义：鲸是动物，不是建筑物，无法说“海里最大的建筑”。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”不是可以比较大小的具体事物，不能说“海里最大的天气”。"}], "explanations": {"脊椎动物": "正确。鲸有脊柱，是海里最大的脊椎动物。", "岛屿": "语义：鲸是动物，不是岛屿，句中指的是海里的生物。", "建筑": "语义：鲸是动物，不是建筑物，无法说“海里最大的建筑”。", "天气": "搭配：“天气”不是可以比较大小的具体事物，不能说“海里最大的天气”。"}, "sentence_index": 6, "correct_answer": "脊椎动物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "蜜蜂是一种脊椎动物，身体有六条腿。", "explanation": "这里应该用〈昆虫〉。脊椎动物有脊柱，蜜蜂没有脊柱，不能归入这一类。"}, {"text": "这家宠物店卖了三朵脊椎动物。", "explanation": "量词用错：“朵”用于花，不能用来数动物。脊椎动物作为类别，量词要用“种”。"}, {"text": "他的脊椎动物疼得厉害，只能躺着。", "explanation": "用错义项：这里指人的脊柱，但“脊椎动物”是动物类群，不能用来指身体的部位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e55e79e-b446-4340-b8e9-1c05af53956a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13858, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "蛇是一座脊椎动物。", "corrected_sentence": "蛇是一种脊椎动物。", "error_description": "量词错误：应把“座”改为“种”。“座”用于大型固定物，不能数动物；表示“脊椎动物”这一类时要用“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e55e79e-b446-4340-b8e9-1c05af53956a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13858, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "鲸是海里最大的一条脊椎动物。", "corrected_sentence": "鲸是海里最大的一种脊椎动物。", "error_description": "量词错误：应把“条”改为“种”。“条”可以用于鱼、蛇等具体动物，但“脊椎动物”指一整类动物，计量这一类时要用“种”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e55e79e-b446-4340-b8e9-1c05af53956a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
