INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13859, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e55e79e-b446-4340-b8e9-1c05af53956a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13859, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容事物像瀑布一样连续地、层层相连地发生或连接。", "primary_collocate": null, "pronunciation": "jí lián", "ipa": "tɕi˧˥ ljɛn˧˥", "syllable_count": 2, "sentences": [{"text": "研究人员发现，一种授粉昆虫减少后，植物结实率随之下降，依赖这些植物的鸟类和哺乳动物也受到影响，这种影响一环接一环地传下去，形成级联的变化。", "target_word": "级联", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "这个系统的反应是级联的。", "target_word": "级联", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "森林里的变化是级联的，一个接着一个。", "target_word": "级联", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种级联的影响会越来越大。", "target_word": "级联", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水池是级联的，水从上面流到下面。", "target_word": "级联", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这几个电路是级联的，信号一级传给一级。", "target_word": "级联", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一个小错误引发了级联的变化。", "target_word": "级联", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座山上的瀑布是级联的，一层接着一层。", "target_word": "级联", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "专家担心，这里的生态变化会呈级联态势。", "target_word": "级联", "complexity_tier": "T3", "furigana": "zhuān jiā dān xīn, zhè lǐ de shēng tài biàn huà huì chéng jí lián tài shì。", "sentence_source": "generated"}, {"text": "他把三个小水箱设计成级联的。", "target_word": "级联", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "级联式", "label": "复合"}, {"form": "级联反应", "label": "复合"}, {"form": "级联效应", "label": "复合"}, {"form": "級聯", "label": "繁体"}], "register": "书面", "sense_fingerprint": "形容事物像瀑布一样层层相连、接连发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f50129e-3400-4b77-b079-c3bc4a5b6d48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13859, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "级联", "is_correct": true, "explanation": "正确。“一环接一环地传下去”描述层层相连的变化，应填“级联”。"}, {"text": "分散", "is_correct": false, "explanation": "语义：句中强调影响一环接一环地传递，“分散”与之矛盾。"}, {"text": "孤立", "is_correct": false, "explanation": "语义：“孤立”与“一环接一环地传下去”的描述矛盾。"}, {"text": "静止", "is_correct": false, "explanation": "语义：句中描述的是变化层层传递，“静止”与之矛盾。"}], "explanations": {"级联": "正确。“一环接一环地传下去”描述层层相连的变化，应填“级联”。", "分散": "语义：句中强调影响一环接一环地传递，“分散”与之矛盾。", "孤立": "语义：“孤立”与“一环接一环地传下去”的描述矛盾。", "静止": "语义：句中描述的是变化层层传递，“静止”与之矛盾。"}, "sentence_index": 0, "correct_answer": "级联"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场雨级联下了三天。", "explanation": "这里应该用〈连续〉。级联形容事物像瀑布一样层层相连，不用来说持续的时间。"}, {"text": "他听到这个消息，心情很级联。", "explanation": "用错义项：级联形容事物层层相连的样子，不用来形容人的心情。"}, {"text": "这个学生的成绩很级联，每次都是第一名。", "explanation": "用错对象：级联只形容事物的结构或变化方式，不用来评价成绩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e55e79e-b446-4340-b8e9-1c05af53956a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13859, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "级联", "is_correct": true, "explanation": "正确。“引发”后的变化是一环接一环的，用“级联”。"}, {"text": "独立", "is_correct": false, "explanation": "语义：“引发”说明变化由前一个错误导致，变化不会是独立的。"}, {"text": "平静", "is_correct": false, "explanation": "搭配：“平静”多形容心情或环境，不用来说“引发的变化”。"}, {"text": "无关", "is_correct": false, "explanation": "语义：“引发”说明两者有因果关系，“无关”与之矛盾。"}], "explanations": {"级联": "正确。“引发”后的变化是一环接一环的，用“级联”。", "独立": "语义：“引发”说明变化由前一个错误导致，变化不会是独立的。", "平静": "搭配：“平静”多形容心情或环境，不用来说“引发的变化”。", "无关": "语义：“引发”说明两者有因果关系，“无关”与之矛盾。"}, "sentence_index": 6, "correct_answer": "级联"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这三个选项是级联的，可以同时选。", "explanation": "这里应该用〈并列〉。级联强调一层接一层地相连，不表示并排平等。"}, {"text": "我的心情很级联，一会儿高兴，一会儿难过。", "explanation": "用错义项：级联形容事物的连接方式，不用来形容心情。"}, {"text": "这块石头很级联，形状非常圆。", "explanation": "用错义项：级联不形容物体的形状，只形容层层相连的样子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e55e79e-b446-4340-b8e9-1c05af53956a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13859, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次故障的影响是级联地，一步一步扩大。", "corrected_sentence": "这次故障的影响是级联的，一步一步扩大。", "error_description": "“地”用错：“级联”作表语时要用“的”，“地”只修饰动词，不能修饰“是”后的形容词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e55e79e-b446-4340-b8e9-1c05af53956a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13859, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几个池子是级联，水一层层往下流。", "corrected_sentence": "这几个池子是级联的，水一层层往下流。", "error_description": "“的”漏掉：“是”后作表语的形容词要加“的”，应为“级联的”，不能直接说“是级联”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e55e79e-b446-4340-b8e9-1c05af53956a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
