INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13870, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "形容来往频繁，像梭子一样来回穿行。", "primary_collocate": null, "pronunciation": "chuān suō", "ipa": "tʂʰwan˥ swo˥", "syllable_count": 2, "sentences": [{"text": "蜜蜂在这一网络中扮演着“生态枢纽”的角色——它们穿梭于不同植物之间，促进基因流动，增强植物种群的适应潜力，从而提升整个生态系统的抗逆能力。", "target_word": "穿梭", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "孩子们在人群里穿梭着玩游戏。", "target_word": "穿梭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末的地铁站里，人们匆匆穿梭。", "target_word": "穿梭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小船在河面上来回穿梭。", "target_word": "穿梭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "服务员在餐桌之间穿梭，忙着上菜。", "target_word": "穿梭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天穿梭于家和公司之间。", "target_word": "穿梭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马路上，汽车穿梭不停。", "target_word": "穿梭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里，萤火虫在草丛中穿梭。", "target_word": "穿梭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快递员穿梭在大街小巷，把包裹送到每家。", "target_word": "穿梭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客们在老街的小店之间穿梭。", "target_word": "穿梭", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "穿梭了", "label": "体标（了）"}, {"form": "穿梭着", "label": "体标（着）"}, {"form": "穿梭过", "label": "体标（过）"}, {"form": "穿梭机", "label": "复合词"}, {"form": "穿梭巴士", "label": "复合词"}], "register": "通用", "sense_fingerprint": "像梭子一样在人或物之间频繁来回穿行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c117361b-798a-4a43-83e2-632764919ae4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13870, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "穿梭", "is_correct": true, "explanation": "正确：穿梭指往来频繁地穿行，与蜜蜂在植物之间促进流动的枢纽作用相合。"}, {"text": "扎根", "is_correct": false, "explanation": "语义：扎根指固定生长于一处，与蜜蜂往来穿行的意思相反。"}, {"text": "停滞", "is_correct": false, "explanation": "语义：停滞指不再流动，与促进基因流动的作用相反。"}, {"text": "生长", "is_correct": false, "explanation": "语义：生长指植物或生物自身长大，不能描述蜜蜂在不同植物之间往来。"}], "explanations": {"穿梭": "正确：穿梭指往来频繁地穿行，与蜜蜂在植物之间促进流动的枢纽作用相合。", "扎根": "语义：扎根指固定生长于一处，与蜜蜂往来穿行的意思相反。", "停滞": "语义：停滞指不再流动，与促进基因流动的作用相反。", "生长": "语义：生长指植物或生物自身长大，不能描述蜜蜂在不同植物之间往来。"}, "sentence_index": 0, "correct_answer": "穿梭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他穿梭于两座楼之间，只跑了一趟就把文件送到。", "explanation": "这里应该用〈穿过〉。穿梭强调来回往复，只跑一趟的单向通过应说穿过。"}, {"text": "汽车穿梭到了隧道另一头，一路再没有掉头。", "explanation": "这里应该用〈驶过〉。穿梭指来回往复，一路朝前、不再折返的通过应说驶过。"}, {"text": "线穿梭进针孔，一下子就对准了。", "explanation": "这里应该用〈穿〉。穿梭是来回往复的穿行，线一次穿入针孔应说穿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '754b4d02-52a0-4a9b-a662-6693fb895906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13870, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "穿梭", "is_correct": true, "explanation": "正确：穿梭指往返穿行，与马路上汽车来回不停的画面相合。"}, {"text": "停靠", "is_correct": false, "explanation": "语义：停靠指车辆停下靠边，与“不停”直接矛盾。"}, {"text": "静候", "is_correct": false, "explanation": "搭配：静候多指等待人或事情，不说汽车在马路上静候。"}, {"text": "漂浮", "is_correct": false, "explanation": "搭配：漂浮用于水面或空中，不说汽车在马路上漂浮。"}], "explanations": {"穿梭": "正确：穿梭指往返穿行，与马路上汽车来回不停的画面相合。", "停靠": "语义：停靠指车辆停下靠边，与“不停”直接矛盾。", "静候": "搭配：静候多指等待人或事情，不说汽车在马路上静候。", "漂浮": "搭配：漂浮用于水面或空中，不说汽车在马路上漂浮。"}, "sentence_index": 6, "correct_answer": "穿梭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在门口穿梭，不敢进去。", "explanation": "这里应该用〈徘徊〉。穿梭指在多处之间往返穿行，原地来回迟疑时要用徘徊。"}, {"text": "他一进教室就穿梭，直接坐下休息了。", "explanation": "这里应该用〈就座〉。穿梭是来回走动，进门后直接坐下应说就座。"}, {"text": "这座桥穿梭在河面上，连通两岸。", "explanation": "这里应该用〈横跨〉。桥梁固定不动，只有来回往复的移动才叫穿梭，横跨河面应说横跨。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '754b4d02-52a0-4a9b-a662-6693fb895906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13870, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "地铁站里，乘客们闸机之间穿梭。", "corrected_sentence": "地铁站里，乘客们在闸机之间穿梭。", "error_description": "错误形式：“乘客们闸机之间穿梭”，处所“闸机之间”前面缺少引出处所的介词“在”，句子结构不完整。正确形式：“在闸机之间穿梭”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '754b4d02-52a0-4a9b-a662-6693fb895906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13870, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学生们在教学楼之间被穿梭，去上课。", "corrected_sentence": "学生们在教学楼之间穿梭，去上课。", "error_description": "错误形式：“被穿梭”，给不及物动词穿梭加上被字。正确形式：“穿梭”直接作谓语。穿梭没有被动用法，句中不需要被。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '754b4d02-52a0-4a9b-a662-6693fb895906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
