INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13872, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "将一组数值相加后除以数值的个数所得的结果，表示这组数据的中间水平。", "primary_collocate": null, "pronunciation": "píng jūn", "ipa": "pʰiŋ˧˥ tɕyn˥", "syllable_count": 2, "sentences": [{"text": "我们班的平均成绩是八十五分。", "target_word": "平均", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的平均气温是十八度。", "target_word": "平均", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们家的平均年龄很大。", "target_word": "平均", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司员工的平均工资不低。", "target_word": "平均", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国人的平均寿命越来越长。", "target_word": "平均", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全班同学的平均身高是一米六。", "target_word": "平均", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试的平均分比上次高。", "target_word": "平均", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本月每天的平均睡眠时间是七小时。", "target_word": "平均", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "平均气温上升了两度。", "target_word": "平均", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路的平均车速只有二十公里。", "target_word": "平均", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "平均数", "label": "复合词"}, {"form": "平均值", "label": "复合词"}, {"form": "平均分", "label": "复合词"}], "register": "通用", "sense_fingerprint": "表示一组数据的平均值、中间水平，多作定语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c117361b-798a-4a43-83e2-632764919ae4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13872, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "平均", "is_correct": true, "explanation": "平均修饰“成绩”，指一组成绩相加再除以人数所得的中间水平，与八十五分相符。"}, {"text": "差", "is_correct": false, "explanation": "语义：“差成绩”指分数低，而八十五分是较高的分数，句意矛盾。"}, {"text": "低", "is_correct": false, "explanation": "语义：“低成绩”指分数低，与八十五分这一较高的分数矛盾。"}, {"text": "随机", "is_correct": false, "explanation": "搭配：“随机”说的是抽取方式，不用来修饰“成绩”。"}], "explanations": {"平均": "平均修饰“成绩”，指一组成绩相加再除以人数所得的中间水平，与八十五分相符。", "差": "语义：“差成绩”指分数低，而八十五分是较高的分数，句意矛盾。", "低": "语义：“低成绩”指分数低，与八十五分这一较高的分数矛盾。", "随机": "搭配：“随机”说的是抽取方式，不用来修饰“成绩”。"}, "sentence_index": 0, "correct_answer": "平均"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一个平均的工人。", "explanation": "这里应该用〈普通〉。平均表示数值的中间水平，不能用来形容人的一般状况。"}, {"text": "他在银行做平均的工作。", "explanation": "这里应该用〈平凡〉。平均只指数值的中间水平，不能用来形容工作的普通程度。"}, {"text": "这本书的故事很平均，没什么意思。", "explanation": "这里应该用〈平淡〉。平均指一组数值的中间水平，不能用来形容故事内容没有起伏、没意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '754b4d02-52a0-4a9b-a662-6693fb895906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13872, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "平均", "is_correct": true, "explanation": "平均修饰“分”，指各次成绩相加后除以个数所得的中间水平，与“比上次高”相符。"}, {"text": "差", "is_correct": false, "explanation": "语义：“差分”指分数低，与“比上次高”的正向比较矛盾。"}, {"text": "满意", "is_correct": false, "explanation": "搭配：“满意”形容人的感受，不能修饰“分”，“满意分”不成词。"}, {"text": "失望", "is_correct": false, "explanation": "搭配：“失望”描述心情，不用来修饰“分”。"}], "explanations": {"平均": "平均修饰“分”，指各次成绩相加后除以个数所得的中间水平，与“比上次高”相符。", "差": "语义：“差分”指分数低，与“比上次高”的正向比较矛盾。", "满意": "搭配：“满意”形容人的感受，不能修饰“分”，“满意分”不成词。", "失望": "搭配：“失望”描述心情，不用来修饰“分”。"}, "sentence_index": 6, "correct_answer": "平均"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种现象很平均。", "explanation": "这里应该用〈普遍〉。平均指数值的中间水平或均等分配，不能用来说现象的常见程度。"}, {"text": "这只是一件平均的小事。", "explanation": "这里应该用〈寻常〉。平均表示数值的中间水平，不能用来形容事情的平常程度。"}, {"text": "我的平均年龄有二十岁，比哥哥小。", "explanation": "这里应该用〈实际〉。平均要对一组数求得，只有一个人的年龄不能说“平均年龄”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '754b4d02-52a0-4a9b-a662-6693fb895906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13872, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这一周很平均气温是二十度。", "corrected_sentence": "这一周的平均气温是二十度。", "error_description": "错误形式：“很平均气温”；正确形式：“的平均气温”。“平均”作定语修饰“气温”时要接结构助词“的”，“很”不能放在这个定语位置。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '754b4d02-52a0-4a9b-a662-6693fb895906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13872, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次测验很平均成绩是七十三分。", "corrected_sentence": "这次测验的平均成绩是七十三分。", "error_description": "错误形式：“很平均成绩”；正确形式：“的平均成绩”。“平均”修饰“成绩”时要用“的”连接，“很”不能用在这个定语位置。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '754b4d02-52a0-4a9b-a662-6693fb895906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
