INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13873, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "被正式归入某一保护或危险类别", "primary_collocate": null, "pronunciation": "liè wéi", "ipa": "li̯e˥˩ weɪ̯˧˥", "syllable_count": 2, "sentences": [{"text": "然而，当前全球平均每三年就有一种野生蜂类被列为濒危物种，这一速度是自然灭绝率的数百倍。", "target_word": "列为", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "大熊猫列为国家一级保护动物。", "target_word": "列为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种鱼已经列为濒危物种了。", "target_word": "列为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府把这片森林列为保护区。", "target_word": "列为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座山列为国家级自然保护区。", "target_word": "列为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种花因为太少，列为保护植物。", "target_word": "列为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家把这个地方列为危险区。", "target_word": "列为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老虎很少了，国家把它列为保护动物。", "target_word": "列为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥有问题，已经列为危险建筑。", "target_word": "列为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那种鸟现在列为濒危动物。", "target_word": "列为", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "列為", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "正式归入保护或危险的类别", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '666c4209-724f-4fd6-b02e-7caaa973cf90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13873, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "列为", "is_correct": true, "explanation": "正确答案。列为（liè wéi）：正式归入某一保护或危险类别。"}, {"text": "略为", "is_correct": false, "explanation": "lüè（第四声）与 liè（第四声）的韵母不同（ü 与 i），意思是稍微、略微。"}, {"text": "列位", "is_correct": false, "explanation": "声调混淆：liè wèi（第四声）与 liè wéi（第二声）。“列位”指诸位，非归入之义。"}, {"text": "立为", "is_correct": false, "explanation": "lì（第四声）与 liè 的韵母不同（i 与 ie），意思是设立为。"}], "explanations": {"列为": "正确答案。列为（liè wéi）：正式归入某一保护或危险类别。", "略为": "lüè（第四声）与 liè（第四声）的韵母不同（ü 与 i），意思是稍微、略微。", "列位": "声调混淆：liè wèi（第四声）与 liè wéi（第二声）。“列位”指诸位，非归入之义。", "立为": "lì（第四声）与 liè 的韵母不同（i 与 ie），意思是设立为。"}, "sentence_index": null, "correct_answer": "列为"}, "level_3": {"options": [{"text": "列为", "is_correct": true, "explanation": "“列为”表示正式归入某类，此处指被归入濒危物种。"}, {"text": "删除", "is_correct": false, "explanation": "语义：“删除”是去掉、除名，与“被归入濒危物种”的句意相反。"}, {"text": "放大", "is_correct": false, "explanation": "语义：“放大”指扩大，与“被归入濒危类别”的语义无关。"}, {"text": "提拔", "is_correct": false, "explanation": "搭配：“提拔”用于人的职位，不能说“提拔为濒危物种”。"}], "explanations": {"列为": "“列为”表示正式归入某类，此处指被归入濒危物种。", "删除": "语义：“删除”是去掉、除名，与“被归入濒危物种”的句意相反。", "放大": "语义：“放大”指扩大，与“被归入濒危类别”的语义无关。", "提拔": "搭配：“提拔”用于人的职位，不能说“提拔为濒危物种”。"}, "sentence_index": 0, "correct_answer": "列为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把自己列为保护动物。", "explanation": "这里应该用〈自称〉。“列为”是正式归入保护或危险类别，对象要能归类，“他”是人，不能被列为动物，应说“他自称是保护动物”。"}, {"text": "他把这次比赛列为危险区。", "explanation": "这里应该用〈视为〉。“列为”归入地点类别时，对象必须是地点；“比赛”是活动，不是地点，应说“把这次比赛视为危险活动”。"}, {"text": "这些学生已列为名册，大家都能看到。", "explanation": "这里应该用〈列入〉。“列为”后接类别，“名册”不是类别，应说“列入名册”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae487f50-7559-4720-aef5-53c5c49c45f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13873, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "列为", "is_correct": true, "explanation": "正确答案。列为（liè wéi）：正式归入某一保护或危险类别。"}, {"text": "列位", "is_correct": false, "explanation": "声调混淆：liè wèi（第四声）与 liè wéi（第二声）。「列位」指诸位，非归入之义。"}, {"text": "连为", "is_correct": false, "explanation": "lián（第二声）与 liè（第四声）韵母不同（ian 与 ie），意思是连接成为一体。"}, {"text": "立委", "is_correct": false, "explanation": "lì（第四声）与 liè 韵母不同（i 与 ie），wěi 与 wéi 声调也不同，“立委”指立法委员。"}], "explanations": {"列为": "正确答案。列为（liè wéi）：正式归入某一保护或危险类别。", "列位": "声调混淆：liè wèi（第四声）与 liè wéi（第二声）。「列位」指诸位，非归入之义。", "连为": "lián（第二声）与 liè（第四声）韵母不同（ian 与 ie），意思是连接成为一体。", "立委": "lì（第四声）与 liè 韵母不同（i 与 ie），wěi 与 wéi 声调也不同，“立委”指立法委员。"}, "sentence_index": null, "correct_answer": "列为"}, "level_3": {"options": [{"text": "列为", "is_correct": true, "explanation": "“列为”表示正式归入某类，此处指把这个地方归入危险区。"}, {"text": "粉碎", "is_correct": false, "explanation": "语义：“粉碎”是打碎成块，与“归入危险区”的语义无关。"}, {"text": "放弃", "is_correct": false, "explanation": "搭配：“放弃”不能带“为”引出类别，“放弃为危险区”不成立。"}, {"text": "烧毁", "is_correct": false, "explanation": "语义：“烧毁”指烧坏，与“被划为危险区”的句意不合。"}], "explanations": {"列为": "“列为”表示正式归入某类，此处指把这个地方归入危险区。", "粉碎": "语义：“粉碎”是打碎成块，与“归入危险区”的语义无关。", "放弃": "搭配：“放弃”不能带“为”引出类别，“放弃为危险区”不成立。", "烧毁": "语义：“烧毁”指烧坏，与“被划为危险区”的句意不合。"}, "sentence_index": 6, "correct_answer": "列为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座石桥已被列为濒危动物。", "explanation": "这里应该用〈划为〉。“列为”归入的是保护或危险类别，“石桥”不是动物，不能归入“濒危动物”，应说“划为危险建筑”。"}, {"text": "这个想法被列为危险区，大家都很紧张。", "explanation": "这里应该用〈看作〉。“列为危险区”要求对象是地点，“想法”不是地点，应说“把这个想法看作危险”。"}, {"text": "他的成绩已被列为危险。", "explanation": "这里应该用〈评为〉。“列为”归入的是保护或危险类别，“成绩”不能归入，“危险”也不是类别，应说“成绩被评为优秀”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae487f50-7559-4720-aef5-53c5c49c45f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13873, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种海龟已被列为。", "corrected_sentence": "这种海龟已被列为濒危动物。", "error_description": "漏了“列为”的类别宾语。“列为”后要接所归入的类别，应说“被列为濒危动物”，不能只说“被列为”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae487f50-7559-4720-aef5-53c5c49c45f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13873, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条河已被列为成危险水域。", "corrected_sentence": "这条河已被列为危险水域。", "error_description": "多出了“成”。“列为”已表示归入某类，后面不能再接“成”，应说“被列为危险水域”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae487f50-7559-4720-aef5-53c5c49c45f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
