INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13874, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指物种或事物面临灭绝或消亡的危险状态。", "primary_collocate": null, "pronunciation": "bīn wēi", "ipa": "pin˥ wei˥", "syllable_count": 2, "sentences": [{"text": "然而，当前全球平均每三年就有一种野生蜂类被列为濒危物种，这一速度是自然灭绝率的数百倍。", "target_word": "濒危", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "大熊猫曾经是濒危动物。", "target_word": "濒危", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种鸟现在非常濒危。", "target_word": "濒危", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里有很多濒危的植物。", "target_word": "濒危", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保护濒危物种，是每个人的责任。", "target_word": "濒危", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老虎已经濒危，我们要保护它们。", "target_word": "濒危", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "由于过度捕捞，这个湖里的鱼类很濒危。", "target_word": "濒危", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在研究一种濒危的蝴蝶。", "target_word": "濒危", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为森林变少，这些动物越来越濒危。", "target_word": "濒危", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里有一本讲濒危动物的书。", "target_word": "濒危", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "濒危物种", "label": "复合词"}, {"form": "濒危动物", "label": "复合词"}], "register": "书面", "sense_fingerprint": "物种面临灭绝危险的状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c117361b-798a-4a43-83e2-632764919ae4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13874, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "濒危", "is_correct": true, "explanation": "濒危修饰“物种”，指面临灭绝的危险，与句中的灭绝率相符。"}, {"text": "繁盛", "is_correct": false, "explanation": "语义：“繁盛”指兴旺，与句中的灭绝率形成矛盾。"}, {"text": "健康", "is_correct": false, "explanation": "搭配：“健康”形容个体的身体状态，不用来修饰“物种”。"}, {"text": "普通", "is_correct": false, "explanation": "语义：“普通”指常见、不稀少，不能说明物种被列入保护名录。"}], "explanations": {"濒危": "濒危修饰“物种”，指面临灭绝的危险，与句中的灭绝率相符。", "繁盛": "语义：“繁盛”指兴旺，与句中的灭绝率形成矛盾。", "健康": "搭配：“健康”形容个体的身体状态，不用来修饰“物种”。", "普通": "语义：“普通”指常见、不稀少，不能说明物种被列入保护名录。"}, "sentence_index": 0, "correct_answer": "濒危"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条路很濒危。", "explanation": "这里应该用〈危险〉。濒危指面临灭绝或消亡，用于物种或事物，不能用来形容路况的险要。"}, {"text": "这颗星星的光芒越来越濒危。", "explanation": "这里应该用〈暗淡〉。濒危指物种或事物面临灭绝，光芒只是变弱，不能用“濒危”来形容。"}, {"text": "我们班的成绩很濒危，需要努力。", "explanation": "这里应该用〈落后〉。濒危只用于面临灭绝或消亡的物种或事物，成绩不会“灭绝”，不能这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '754b4d02-52a0-4a9b-a662-6693fb895906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13874, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "濒危", "is_correct": true, "explanation": "濒危作谓语，描述鱼类面临灭绝的状态，与句意相符。"}, {"text": "懒惰", "is_correct": false, "explanation": "语义：鱼类不能用“懒惰”来形容，句子语义不通。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”形容人或动物的智力，不适用于描述鱼类的种群状况。"}, {"text": "生疏", "is_correct": false, "explanation": "搭配：“生疏”描述人对事物不熟悉，不用来描述鱼类的状态。"}], "explanations": {"濒危": "濒危作谓语，描述鱼类面临灭绝的状态，与句意相符。", "懒惰": "语义：鱼类不能用“懒惰”来形容，句子语义不通。", "聪明": "语义：“聪明”形容人或动物的智力，不适用于描述鱼类的种群状况。", "生疏": "搭配：“生疏”描述人对事物不熟悉，不用来描述鱼类的状态。"}, "sentence_index": 6, "correct_answer": "濒危"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次比赛的情况很濒危，我们要加油。", "explanation": "这里应该用〈危急〉。濒危专指物种或事物面临灭绝或消亡，不用来形容比赛的局势。"}, {"text": "他在河边捡到一个濒危的皮球。", "explanation": "这里应该用〈破旧〉。濒危指面临灭绝的物种或事物，皮球不会“灭绝”，应说“破旧”。"}, {"text": "这部电影很濒危，观众都走了。", "explanation": "这里应该用〈乏味〉。濒危指物种或事物面临灭绝，电影的内容不会“灭绝”，形容内容枯燥应说“乏味”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '754b4d02-52a0-4a9b-a662-6693fb895906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13874, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种蝴蝶被濒危了。", "corrected_sentence": "这种蝴蝶已经濒危了。", "error_description": "错误形式：“被濒危了”；正确形式：“已经濒危了”。“濒危”是形容词，表示状态，不能用“被”构成被动式，应把“被”改为副词“已经”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '754b4d02-52a0-4a9b-a662-6693fb895906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13874, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种鸟已经濒危着了。", "corrected_sentence": "这种鸟已经濒危了。", "error_description": "错误形式：“濒危着了”；正确形式：“濒危了”。“濒危”是形容词，后面不能加动态助词“着”，应去掉“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '754b4d02-52a0-4a9b-a662-6693fb895906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
