INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13875, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指某种生物或事物完全消失，不再存在。", "primary_collocate": null, "pronunciation": "miè jué", "ipa": "mjɛ˥˩ tɕɥɛ˧˥", "syllable_count": 2, "sentences": [{"text": "研究人员警告，若这片湿地继续被开发，许多依赖它生存的物种可能在数十年内彻底灭绝。", "target_word": "灭绝", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "恐龙在很久以前就灭绝了。", "target_word": "灭绝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种鸟已经灭绝了几十年。", "target_word": "灭绝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人类的活动让很多动物灭绝。", "target_word": "灭绝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不保护，这种鱼就会灭绝。", "target_word": "灭绝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家说，猛犸象一万年前灭绝。", "target_word": "灭绝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为什么恐龙会灭绝？", "target_word": "灭绝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种老虎在中国已经灭绝。", "target_word": "灭绝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灭绝的动物不会再回来。", "target_word": "灭绝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写了一本关于灭绝动物的书。", "target_word": "灭绝", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "灭绝了", "label": "体标"}, {"form": "灭绝过", "label": "体标"}, {"form": "灭绝率", "label": "复合"}], "register": "书面", "sense_fingerprint": "生物或事物完全消失不再存在", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c117361b-798a-4a43-83e2-632764919ae4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13875, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "灭绝", "is_correct": true, "explanation": "正确：灭绝指物种彻底消失，与“彻底”搭配，符合濒危物种可能全部消失的警示语境。"}, {"text": "复活", "is_correct": false, "explanation": "语义：复活指死而重新活过来，与栖地被开发、物种面临消失的警示语境相反。"}, {"text": "栖息", "is_correct": false, "explanation": "语义：栖息指动物停留在某处生活，“彻底栖息”意义不通，也不符合威胁语境。"}, {"text": "繁衍", "is_correct": false, "explanation": "语义：繁衍指生物繁殖后代，与物种面临彻底消失的警示语境相反。"}], "explanations": {"灭绝": "正确：灭绝指物种彻底消失，与“彻底”搭配，符合濒危物种可能全部消失的警示语境。", "复活": "语义：复活指死而重新活过来，与栖地被开发、物种面临消失的警示语境相反。", "栖息": "语义：栖息指动物停留在某处生活，“彻底栖息”意义不通，也不符合威胁语境。", "繁衍": "语义：繁衍指生物繁殖后代，与物种面临彻底消失的警示语境相反。"}, "sentence_index": 0, "correct_answer": "灭绝"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他灭绝了三天，大家都很着急。", "explanation": "这里应该用〈失踪〉。“灭绝”指物种或事物整体不再存在，人暂时不见不能用，应说“失踪”。"}, {"text": "这次实验灭绝了，我们只好重新做。", "explanation": "这里应该用〈失败〉。实验没有成功应说“失败”，“灭绝”只指生物或事物彻底消失。"}, {"text": "这种药吃了以后就灭绝了。", "explanation": "这里应该用〈失效〉。药物不再起作用应说“失效”，药并没有消失，不能说“灭绝”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '754b4d02-52a0-4a9b-a662-6693fb895906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13875, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "灭绝", "is_correct": true, "explanation": "正确：这里说恐龙整个种类不复存在，“为什么恐龙会灭绝”是合理的问法。"}, {"text": "森林", "is_correct": false, "explanation": "词性：森林是名词，不能放在能愿动词“会”后面作谓语。"}, {"text": "颜色", "is_correct": false, "explanation": "词性：颜色是名词，“恐龙会颜色”不成句。"}, {"text": "骨头", "is_correct": false, "explanation": "词性：骨头是名词，不能受“会”修饰作谓语。"}], "explanations": {"灭绝": "正确：这里说恐龙整个种类不复存在，“为什么恐龙会灭绝”是合理的问法。", "森林": "词性：森林是名词，不能放在能愿动词“会”后面作谓语。", "颜色": "词性：颜色是名词，“恐龙会颜色”不成句。", "骨头": "词性：骨头是名词，不能受“会”修饰作谓语。"}, "sentence_index": 6, "correct_answer": "灭绝"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家的猫昨天灭绝了。", "explanation": "这里应该用〈走失〉。一只猫走丢只是个体不见了，“灭绝”指整个种类不复存在，应说“走失”。"}, {"text": "他的成绩这次彻底灭绝了。", "explanation": "这里应该用〈下降〉。成绩变差应说“下降”，“灭绝”只指生物或事物彻底消失。"}, {"text": "夏天到了，气温一直在灭绝。", "explanation": "这里应该用〈升高〉。气温上升应说“升高”，“灭绝”不能用于气温这类数值。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '754b4d02-52a0-4a9b-a662-6693fb895906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13875, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种蝴蝶已经很灭绝了。", "corrected_sentence": "这种蝴蝶已经灭绝了。", "error_description": "错误在“灭绝”前多加了程度副词“很”。“灭绝”是动词，不能受“很”修饰，应改为“这种蝴蝶已经灭绝了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '754b4d02-52a0-4a9b-a662-6693fb895906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13875, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种鸟已经灭绝着。", "corrected_sentence": "这种鸟已经灭绝了。", "error_description": "错误形式：“灭绝着”。“灭绝”表示已经完成的变化，不能带表示持续的“着”，应改为“灭绝了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '754b4d02-52a0-4a9b-a662-6693fb895906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
