INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13876, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指事物最初就有的、非人工加工或移植的本来状态。", "primary_collocate": null, "pronunciation": "yuán shēng", "ipa": "ɥɛn˧˥ ʂɤŋ˥˥", "syllable_count": 2, "sentences": [{"text": "部分前沿研究指出，建立生态廊道、恢复原生植被、实施精准农业管理以及制定跨区域的授粉保护政策，可能是缓解危机的有效路径。", "target_word": "原生", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这片山上有很多原生树木。", "target_word": "原生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "原生森林对小动物很重要。", "target_word": "原生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想保护这里的原生环境。", "target_word": "原生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种花是原生植物，只分布在这一带。", "target_word": "原生", "complexity_tier": "T3", "furigana": "zhè zhǒng huā shì yuán shēng zhí wù, zhǐ fēn bù zài zhè yí dài.", "sentence_source": "generated"}, {"text": "公园里种着一些原生花草。", "target_word": "原生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "原生植物比外来植物更适合这里。", "target_word": "原生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的原生鸟类越来越少了。", "target_word": "原生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们找出原生的树。", "target_word": "原生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河边还有原生的湿地。", "target_word": "原生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "原生植物", "label": "复合"}, {"form": "原生态", "label": "复合"}], "register": "书面", "sense_fingerprint": "最初就有、非人工移植的本来状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c117361b-798a-4a43-83e2-632764919ae4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13876, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "原生", "is_correct": true, "explanation": "正确：句子说恢复本来就有的植被，“原生植被”指原本生长在当地的植被，语境正合。"}, {"text": "陌生", "is_correct": false, "explanation": "语义：陌生指不熟悉，与“恢复”所表示的回到原来状态相矛盾。"}, {"text": "稀少", "is_correct": false, "explanation": "语义：稀少指数量很少，与恢复植被的目标（重新茂盛）正好相反。"}, {"text": "整洁", "is_correct": false, "explanation": "搭配：整洁多用来形容环境或物品，不能说“恢复整洁植被”。"}], "explanations": {"原生": "正确：句子说恢复本来就有的植被，“原生植被”指原本生长在当地的植被，语境正合。", "陌生": "语义：陌生指不熟悉，与“恢复”所表示的回到原来状态相矛盾。", "稀少": "语义：稀少指数量很少，与恢复植被的目标（重新茂盛）正好相反。", "整洁": "搭配：整洁多用来形容环境或物品，不能说“恢复整洁植被”。"}, "sentence_index": 0, "correct_answer": "原生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这些花是原生培育的。", "explanation": "这里应该用〈人工〉。“原生”指本来的状态、非人工加工，不能修饰“培育”，应说“人工培育”。"}, {"text": "他有原生的音乐天赋。", "explanation": "这里应该用〈先天〉。“原生”只说事物本来的状态，不用于说人的天赋，应说“先天的音乐天赋”。"}, {"text": "这种鸟是原生的，人们把它从国外带进来。", "explanation": "这里应该用〈外来〉。“原生”指本来就在当地，从国外带进来的鸟应说“外来”，两者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '754b4d02-52a0-4a9b-a662-6693fb895906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13876, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "原生", "is_correct": true, "explanation": "正确：比较的是本地本来就有的植物与外来植物，“原生植物”正合句意。"}, {"text": "外来", "is_correct": false, "explanation": "语义：前后都用“外来”，比较的双方自相矛盾，“外来植物比外来植物”说不通。"}, {"text": "幼稚", "is_correct": false, "explanation": "搭配：幼稚通常用来形容人的想法或行为，不能用来修饰植物。"}, {"text": "荒凉", "is_correct": false, "explanation": "语义：荒凉指没有生机的环境，与“更适合这里”所表达的适应性相矛盾。"}], "explanations": {"原生": "正确：比较的是本地本来就有的植物与外来植物，“原生植物”正合句意。", "外来": "语义：前后都用“外来”，比较的双方自相矛盾，“外来植物比外来植物”说不通。", "幼稚": "搭配：幼稚通常用来形容人的想法或行为，不能用来修饰植物。", "荒凉": "语义：荒凉指没有生机的环境，与“更适合这里”所表达的适应性相矛盾。"}, "sentence_index": 6, "correct_answer": "原生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座楼是原生建成的。", "explanation": "这里应该用〈新〉。楼房是人工建造的，“原生”只指非人工的本来状态，应说“这座楼是新建成的”。"}, {"text": "这只羊是原生克隆出来的。", "explanation": "这里应该用〈人工〉。克隆出的羊是人工复制的，“原生”指本来的状态、非人工加工，不能修饰“克隆”。"}, {"text": "这只碗是原生手工做的。", "explanation": "这里不该用〈原生〉。碗是人工制作的，“原生”指本来的状态、非人工加工，与“人工制作”矛盾，应去掉“原生”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '754b4d02-52a0-4a9b-a662-6693fb895906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13876, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座岛上的原生森林都是人工种植的。", "corrected_sentence": "这座岛上的原生森林都是自然生长的。", "error_description": "错误在“原生”与“人工种植”相矛盾：原生指本来就有、非人工加工或移植，森林不能既是原生的又是人工种植的。应改为“自然生长的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '754b4d02-52a0-4a9b-a662-6693fb895906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13876, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条河边有一片原生的湿地，是从外地移植过来的。", "corrected_sentence": "这条河边有一片原生的湿地，是本来就长在这里的。", "error_description": "错误在“原生”与“移植”相矛盾：原生指非人工移植的本来状态，句中却说是从外地移植来的。应改为“本来就长在这里的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '754b4d02-52a0-4a9b-a662-6693fb895906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13877, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48db653b-5390-420d-858d-9c25a581ed1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13877, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48db653b-5390-420d-858d-9c25a581ed1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13877, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "保护区是为保护自然环境、野生动物或生态系统而划定的特殊区域。", "primary_collocate": null, "pronunciation": "bǎo hù qū", "ipa": "paʊ˨˩ xu˥˩ tɕʰy˥", "syllable_count": 3, "sentences": [{"text": "某些国家已启动“授粉者保护区”计划，通过立法限制特定神经毒性农药的使用，并鼓励农场主采用生态友好型耕作方式。", "target_word": "保护区", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这片森林是国家建立的自然保护区。", "target_word": "保护区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保护区里有很多珍贵的野生动物。", "target_word": "保护区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府划定了新的保护区，禁止人们打猎。", "target_word": "保护区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客不能随便进入保护区的核心地带。", "target_word": "保护区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个保护区主要保护大熊猫的栖息地。", "target_word": "保护区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在保护区工作了十年，负责监测鸟类。", "target_word": "保护区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了保护湿地，当地建了一个保护区。", "target_word": "保护区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保护区内严禁砍树和捕鱼。", "target_word": "保护区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家在保护区里发现了一种新植物。", "target_word": "保护区", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "自然保护区", "label": "复合"}, {"form": "国家级保护区", "label": "复合"}], "register": "中性", "sense_fingerprint": "为保护生态和野生动物而划定的区域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b4ede4-b5c5-47ad-9967-6cec6e48f26b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13877, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "保护区", "is_correct": true, "explanation": "正确。“授粉者保护区”指为保护授粉昆虫而划定的区域，与后文“限制农药使用”的语境相符。"}, {"text": "农药", "is_correct": false, "explanation": "语义：“授粉者农药计划”与前句“限制农药的使用”自相矛盾，计划的对象不能是农药。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：工厂与“生态友好型耕作”和保护授粉者的目标相反，句意不通。"}, {"text": "银行", "is_correct": false, "explanation": "搭配：“授粉者银行”不成词，“启动计划”的对象应是保护性的区域，不能是银行。"}], "explanations": {"保护区": "正确。“授粉者保护区”指为保护授粉昆虫而划定的区域，与后文“限制农药使用”的语境相符。", "农药": "语义：“授粉者农药计划”与前句“限制农药的使用”自相矛盾，计划的对象不能是农药。", "工厂": "语义：工厂与“生态友好型耕作”和保护授粉者的目标相反，句意不通。", "银行": "搭配：“授粉者银行”不成词，“启动计划”的对象应是保护性的区域，不能是银行。"}, "sentence_index": 0, "correct_answer": "保护区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只保护区很大，我们走了一天。", "explanation": "量词错误：〈只〉用于动物，保护区是地方，应用〈个〉或〈片〉。"}, {"text": "这个保护区每天处理几百吨垃圾。", "explanation": "这里应该用〈垃圾站〉。保护区是为保护生态而划定的区域，不负责处理垃圾。"}, {"text": "妈妈把钱放在保护区里。", "explanation": "这里应该用〈保险柜〉。保护区是为保护生态而划定的区域，不是存放钱财的器具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48db653b-5390-420d-858d-9c25a581ed1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13877, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "保护区", "is_correct": true, "explanation": "正确。“他在保护区工作”指在生态保护地从事监测工作，与“监测鸟类”相符。"}, {"text": "餐厅", "is_correct": false, "explanation": "语义：餐厅与“监测鸟类”无关，鸟类监测需要野外或研究场所。"}, {"text": "超市", "is_correct": false, "explanation": "搭配：“监测鸟类”不与超市搭配，超市里没有需要监测的野生鸟类。"}, {"text": "商场", "is_correct": false, "explanation": "语义：商场不是开展生态监测的场所，句意不通。"}], "explanations": {"保护区": "正确。“他在保护区工作”指在生态保护地从事监测工作，与“监测鸟类”相符。", "餐厅": "语义：餐厅与“监测鸟类”无关，鸟类监测需要野外或研究场所。", "超市": "搭配：“监测鸟类”不与超市搭配，超市里没有需要监测的野生鸟类。", "商场": "语义：商场不是开展生态监测的场所，句意不通。"}, "sentence_index": 6, "correct_answer": "保护区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "保护区里住着很多病人。", "explanation": "这里应该用〈医院〉。保护区是生态保护地，不收治病人。"}, {"text": "我们参观了一位保护区。", "explanation": "量词错误：〈位〉用于人，保护区是地方，应用〈个〉或〈片〉。"}, {"text": "他是我们学校最好的保护区。", "explanation": "这里应该用〈人才〉。保护区是生态保护地，不能用来指优秀的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48db653b-5390-420d-858d-9c25a581ed1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13877, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府在山区设立了一只保护区。", "corrected_sentence": "政府在山区设立了一个保护区。", "error_description": "量词错误：“只”用于动物，保护区是地方，应改为“个”，说“一个保护区”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48db653b-5390-420d-858d-9c25a581ed1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13877, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这片草原已经被划为一本保护区了。", "corrected_sentence": "这片草原已经被划为一个保护区了。", "error_description": "量词错误：“本”用于书册，保护区是地方，应改为“个”，说“一个保护区”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48db653b-5390-420d-858d-9c25a581ed1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
