INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13881, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指为了探索自然规律、发现新知识而进行的系统观察、实验和分析活动。", "primary_collocate": null, "pronunciation": "kē xué yán jiū", "ipa": "kʰɤ˥ ɕɥɛ˧˥ jɛn˧˥ tɕjoʊ˥", "syllable_count": 4, "sentences": [{"text": "值得注意的是，蜜蜂的社会性结构本身亦为科学研究提供了宝贵模型。", "target_word": "科学研究", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这项科学研究需要很多年的时间。", "target_word": "科学研究", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她从小就想做科学研究。", "target_word": "科学研究", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学研究需要认真观察和反复实验。", "target_word": "科学研究", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院开展了新的科学研究。", "target_word": "科学研究", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家们为这次科学研究准备了很久。", "target_word": "科学研究", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做科学研究不能怕失败。", "target_word": "科学研究", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国家每年给科学研究提供很多钱。", "target_word": "科学研究", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把一生都用在科学研究上。", "target_word": "科学研究", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所大学的科学研究很有名。", "target_word": "科学研究", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一项科学研究", "label": "量词"}], "register": "书面语", "sense_fingerprint": "为探索规律、发现新知识而进行的系统观察、实验与分析活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2f8d72d-01b8-470d-9c8d-ddfe701976a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13881, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "科学研究", "is_correct": true, "explanation": "正确：“为……提供宝贵模型”的对象是探索规律的科学活动，句意完整。"}, {"text": "蜂蜜", "is_correct": false, "explanation": "语义：蜂蜜是食物，不是可以被“提供宝贵模型”的研究活动。"}, {"text": "资金", "is_correct": false, "explanation": "搭配：“提供模型”的对象应是活动或领域，“资金”不能这样被提供模型。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是产品，句中的模型是给探索自然规律的活动参考的，手机不符。"}], "explanations": {"科学研究": "正确：“为……提供宝贵模型”的对象是探索规律的科学活动，句意完整。", "蜂蜜": "语义：蜂蜜是食物，不是可以被“提供宝贵模型”的研究活动。", "资金": "搭配：“提供模型”的对象应是活动或领域，“资金”不能这样被提供模型。", "手机": "语义：手机是产品，句中的模型是给探索自然规律的活动参考的，手机不符。"}, "sentence_index": 0, "correct_answer": "科学研究"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一名科学研究。", "explanation": "这里应该用〈科学家〉。科学研究指探索规律的活动，不指人；指人要说科学家。"}, {"text": "我把科学研究放进了书包。", "explanation": "这里应该用〈书〉。科学研究是一种活动，不是东西，不能放进书包；能放进书包的是书。"}, {"text": "科学研究正在招聘新员工。", "explanation": "这里应该用〈研究所〉。科学研究是活动，不能招聘员工；招聘的是研究所这类机构。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94806ba5-fdd3-4ab9-a20c-1bf54e573444') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13881, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "科学研究", "is_correct": true, "explanation": "正确：作“做”的宾语，指探索规律的活动，与“不能怕失败”的语境相符。"}, {"text": "大海", "is_correct": false, "explanation": "搭配：“做”不能带“大海”作宾语，句中无法理解为“做大海”。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮是天体，不是可以“做”的对象，句意不通。"}, {"text": "雷声", "is_correct": false, "explanation": "语义：雷声不能被“做”，也与“怕失败”无关。"}], "explanations": {"科学研究": "正确：作“做”的宾语，指探索规律的活动，与“不能怕失败”的语境相符。", "大海": "搭配：“做”不能带“大海”作宾语，句中无法理解为“做大海”。", "月亮": "语义：月亮是天体，不是可以“做”的对象，句意不通。", "雷声": "语义：雷声不能被“做”，也与“怕失败”无关。"}, "sentence_index": 6, "correct_answer": "科学研究"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位科学研究每天读书写论文。", "explanation": "这里应该用〈学者〉。科学研究指活动，不指人；指人要说学者或研究人员。"}, {"text": "孩子们喜欢吃科学研究。", "explanation": "这里应该用〈糖果〉。科学研究是活动，不能吃；孩子们吃的是糖果。"}, {"text": "科学研究每天都要上课。", "explanation": "这里应该用〈研究生〉。科学研究是活动，不能去上课；指人的要用研究生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94806ba5-fdd3-4ab9-a20c-1bf54e573444') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13881, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个团队正在进行一只科学研究，需要三年时间。", "corrected_sentence": "这个团队正在进行一项科学研究，需要三年时间。", "error_description": "量词错误：“科学研究”是抽象活动，应用“项”；“只”用于动物等，不能说“一只科学研究”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94806ba5-fdd3-4ab9-a20c-1bf54e573444') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13881, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她当了三年科学研究，成绩很好。", "corrected_sentence": "她做了三年科学研究，成绩很好。", "error_description": "搭配错误：“科学研究”应搭配“做”，说“做了三年科学研究”；“当”后接身份或职业，不能说“当科学研究”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94806ba5-fdd3-4ab9-a20c-1bf54e573444') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
