INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13882, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "由多人共同参与、通过讨论或投票等方式做出决定的过程。", "primary_collocate": null, "pronunciation": "qún tǐ jué cè", "ipa": "tɕʰyn˧˥ tʰi˨˩˦ tɕɥe˧˥ tsʰɤ˥˩", "syllable_count": 4, "sentences": [{"text": "其群体决策机制、信息传递方式（如摇摆舞）以及分工协作的自组织特性，已被应用于算法设计、物流优化乃至人工智能领域的模拟研究。", "target_word": "群体决策", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "公司的重要事情要靠群体决策。", "target_word": "群体决策", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "群体决策需要大家一起讨论。", "target_word": "群体决策", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "群体决策有时比个人决定更慢。", "target_word": "群体决策", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们班用投票的方式进行群体决策。", "target_word": "群体决策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "群体决策可以减少一个人的错误。", "target_word": "群体决策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个委员会的群体决策很公平。", "target_word": "群体决策", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经过群体决策，学校决定建新图书馆。", "target_word": "群体决策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "群体决策时，每个人都能说出想法。", "target_word": "群体决策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的群体决策要听不同的意见。", "target_word": "群体决策", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一次群体决策", "label": "量词"}], "register": "书面语", "sense_fingerprint": "多人通过讨论或投票共同做出决定的过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2f8d72d-01b8-470d-9c8d-ddfe701976a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13882, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "群体决策", "is_correct": true, "explanation": "正确：指多人共同讨论或投票做决定的过程，可以接“机制”。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，与讲决策机制和分工协作的语境不符。"}, {"text": "乒乓球", "is_correct": false, "explanation": "语义：乒乓球是体育项目，与信息传递、分工协作无关。"}, {"text": "糖果", "is_correct": false, "explanation": "搭配：“机制”指组织或系统的运作方式，不能说“糖果机制”。"}], "explanations": {"群体决策": "正确：指多人共同讨论或投票做决定的过程，可以接“机制”。", "冰箱": "语义：冰箱是家电，与讲决策机制和分工协作的语境不符。", "乒乓球": "语义：乒乓球是体育项目，与信息传递、分工协作无关。", "糖果": "搭配：“机制”指组织或系统的运作方式，不能说“糖果机制”。"}, "sentence_index": 0, "correct_answer": "群体决策"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位群体决策很热情，经常帮助我。", "explanation": "这里应该用〈老师〉。群体决策指做决定的过程，不指人；指人要说老师。"}, {"text": "妈妈在厨房里做群体决策当晚饭。", "explanation": "这里应该用〈米饭〉。群体决策是做决定的过程，不能当饭吃；做晚饭用的是米饭等食物。"}, {"text": "群体决策明天要去超市买菜。", "explanation": "这里应该用〈大家〉。群体决策是做决定的过程，不能去超市；指人的要说大家。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94806ba5-fdd3-4ab9-a20c-1bf54e573444') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13882, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "群体决策", "is_correct": true, "explanation": "正确：作主语，指多人一起决定的过程，可以“很公平”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是物体，不能是“公平”的，句意不通。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：鞋子是物品，不是决策过程，句意不通。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“公平”多形容决定、制度，“窗户”不搭。"}], "explanations": {"群体决策": "正确：作主语，指多人一起决定的过程，可以“很公平”。", "石头": "语义：石头是物体，不能是“公平”的，句意不通。", "鞋子": "语义：鞋子是物品，不是决策过程，句意不通。", "窗户": "搭配：“公平”多形容决定、制度，“窗户”不搭。"}, "sentence_index": 6, "correct_answer": "群体决策"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们班的群体决策唱得很好听。", "explanation": "这里应该用〈合唱团〉。群体决策是做决定的过程，不会唱歌；唱歌的是合唱团。"}, {"text": "我们班买了一台群体决策。", "explanation": "这里应该用〈次〉。“台”用于机器，群体决策是过程，应说一次群体决策。"}, {"text": "孩子们在操场上踢群体决策。", "explanation": "这里应该用〈足球〉。群体决策是做决定的过程，不能踢；踢的是足球。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94806ba5-fdd3-4ab9-a20c-1bf54e573444') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13882, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班昨天做着一次群体决策，大家都很满意。", "corrected_sentence": "我们班昨天做了一次群体决策，大家都很满意。", "error_description": "体标错误：“昨天”指已完成的过去，“着”表示持续或状态，与一次性完成的事件不搭配，应说“做了一次群体决策”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94806ba5-fdd3-4ab9-a20c-1bf54e573444') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13882, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个委员会进行了一位群体决策，结果很公平。", "corrected_sentence": "这个委员会进行了一次群体决策，结果很公平。", "error_description": "量词错误：群体决策是过程，应用“次”计量；“位”只用于人，不能用来计量过程。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94806ba5-fdd3-4ab9-a20c-1bf54e573444') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
