INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13884, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "指不同的人或小组各自承担不同的任务，相互配合，共同完成工作。", "primary_collocate": null, "pronunciation": "fēn gōng xié zuò", "ipa": "fən˥˥ kʊŋ˥˥ ɕjɛ˧˥ tswɔ˥˩", "syllable_count": 4, "sentences": [{"text": "其群体决策机制、信息传递方式（如摇摆舞）以及分工协作的自组织特性，已被应用于算法设计、物流优化乃至人工智能领域的模拟研究。", "target_word": "分工协作", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这个项目需要大家分工协作。", "target_word": "分工协作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蚂蚁靠分工协作搬运食物。", "target_word": "分工协作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分工协作能让工作更快完成。", "target_word": "分工协作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们小组分工协作，一天就做完了。", "target_word": "分工协作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司里每个部门都要分工协作。", "target_word": "分工协作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的团队离不开分工协作。", "target_word": "分工协作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们分工协作，很快就盖好了房子。", "target_word": "分工协作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师要求同学们分工协作完成作业。", "target_word": "分工协作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分工协作让我们的效率提高了很多。", "target_word": "分工协作", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分工合作", "label": "近义复合"}], "register": "通用", "sense_fingerprint": "各人承担不同任务并相互配合完成工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b4ede4-b5c5-47ad-9967-6cec6e48f26b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13884, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分工协作", "is_correct": true, "explanation": "正确：“分工协作”与“群体决策机制”“信息传递方式”并列，指群体的协作分工，与句意相合。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是群体协作的行为，不能谈“自组织特性”。"}, {"text": "算术", "is_correct": false, "explanation": "语义：算术是数学运算，与群体的自组织机制无关。"}, {"text": "午餐", "is_correct": false, "explanation": "搭配：“自组织特性”不与“午餐”搭配，句意不通。"}], "explanations": {"分工协作": "正确：“分工协作”与“群体决策机制”“信息传递方式”并列，指群体的协作分工，与句意相合。", "颜色": "语义：颜色不是群体协作的行为，不能谈“自组织特性”。", "算术": "语义：算术是数学运算，与群体的自组织机制无关。", "午餐": "搭配：“自组织特性”不与“午餐”搭配，句意不通。"}, "sentence_index": 0, "correct_answer": "分工协作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和妹妹经常分工协作，一起去逛街。", "explanation": "这里应该用〈结伴〉。分工协作指为完成工作而分担任务，逛街不是需要分工的工作。"}, {"text": "他分工协作完成了全部工作。", "explanation": "这里应该用〈独自〉。分工协作需要多人各负其责，一个人完成工作不能用它。"}, {"text": "两队在赛场上分工协作，想尽办法压倒对方。", "explanation": "这里应该用〈竞争〉。分工协作是互相配合，与“压倒对方”的意思相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48db653b-5390-420d-858d-9c25a581ed1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13884, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分工协作", "is_correct": true, "explanation": "正确：好的团队需要分工协作，与“离不开”搭配，句意相合。"}, {"text": "独裁", "is_correct": false, "explanation": "语义：好的团队靠互相配合，不可能“离不开独裁”，句意不通。"}, {"text": "谣言", "is_correct": false, "explanation": "语义：谣言会破坏团队，好的团队不可能“离不开”它。"}, {"text": "猜疑", "is_correct": false, "explanation": "语义：猜疑会破坏信任，与“好的团队”的特点相反。"}], "explanations": {"分工协作": "正确：好的团队需要分工协作，与“离不开”搭配，句意相合。", "独裁": "语义：好的团队靠互相配合，不可能“离不开独裁”，句意不通。", "谣言": "语义：谣言会破坏团队，好的团队不可能“离不开”它。", "猜疑": "语义：猜疑会破坏信任，与“好的团队”的特点相反。"}, "sentence_index": 6, "correct_answer": "分工协作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们俩一见面就分工协作，吵个不停。", "explanation": "这里应该用〈吵架〉。分工协作是互相配合，与“吵个不停”的意思相反。"}, {"text": "周末我们去公园散步，还分工协作散步。", "explanation": "这里应该用〈一起〉。散步是随意的活动，不需要分工协作，只能说一起散步。"}, {"text": "他在屋里分工协作，一个人玩游戏。", "explanation": "这里应该用〈独自〉。一个人玩游戏不需要分工，不能说分工协作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48db653b-5390-420d-858d-9c25a581ed1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13884, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大家正在分工协作过。", "corrected_sentence": "大家正在分工协作。", "error_description": "用法错误：“正在”表示动作正在进行，“过”表示经历，两者不能同用。应说“大家正在分工协作”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48db653b-5390-420d-858d-9c25a581ed1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13884, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们分工协作这个项目。", "corrected_sentence": "我们分工协作，完成了这个项目。", "error_description": "用法错误：“分工协作”不能直接带宾语，应加上动词，说“我们分工协作，完成了这个项目”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48db653b-5390-420d-858d-9c25a581ed1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
