INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13885, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从某处吸收或取得（有益的东西）。", "primary_collocate": null, "pronunciation": "jí qǔ", "ipa": "tɕi˧˥ tɕʰy˨˩˦", "syllable_count": 2, "sentences": [{"text": "这种从自然智慧中汲取灵感的跨学科探索，进一步凸显了保护昆虫多样性的深远意义。", "target_word": "汲取", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我们要从失败中汲取教训。", "target_word": "汲取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从书里汲取了很多知识。", "target_word": "汲取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "植物的根从土里汲取水分和养分。", "target_word": "汲取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人应该向前辈汲取经验。", "target_word": "汲取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她从旅行中汲取灵感，写了一首歌。", "target_word": "汲取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司从过去的错误中汲取了经验。", "target_word": "汲取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "艺术家常常从大自然汲取灵感。", "target_word": "汲取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要汲取历史的教训。", "target_word": "汲取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们正汲取着知识的营养。", "target_word": "汲取", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "汲取了", "label": "体标"}, {"form": "汲取过", "label": "体标"}, {"form": "汲取着", "label": "体标"}], "register": "书面语", "sense_fingerprint": "从某处吸收、获取有益的东西，如经验、教训、养分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2f8d72d-01b8-470d-9c8d-ddfe701976a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13885, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "汲取", "is_correct": true, "explanation": "jí qǔ，意思是从某处吸收有益的东西。"}, {"text": "截取", "is_correct": false, "explanation": "jié 与 jí 韵母不同（多一个 e），意思是截下一段，不是吸收有益的东西。"}, {"text": "计取", "is_correct": false, "explanation": "jì 与 jí 声调不同（第四声与第二声），意思是按标准计算后收取。"}, {"text": "极区", "is_correct": false, "explanation": "jí qū 与 jí qǔ 的第二音节声调不同（qū 为第一声），意思是南北极附近的地区。"}], "explanations": {"汲取": "jí qǔ，意思是从某处吸收有益的东西。", "截取": "jié 与 jí 韵母不同（多一个 e），意思是截下一段，不是吸收有益的东西。", "计取": "jì 与 jí 声调不同（第四声与第二声），意思是按标准计算后收取。", "极区": "jí qū 与 jí qǔ 的第二音节声调不同（qū 为第一声），意思是南北极附近的地区。"}, "sentence_index": null, "correct_answer": "汲取"}, "level_3": {"options": [{"text": "排放", "is_correct": false, "explanation": "语义：“排放”指向外排出废气、废水，与“灵感”的获得无关。"}, {"text": "汲取", "is_correct": true, "explanation": "汲取：从自然智慧中吸收有益的内容，与“灵感”搭配，句意通顺。"}, {"text": "倾倒", "is_correct": false, "explanation": "搭配：“倾倒”说的是把液体倒出，不能说从智慧中倾倒灵感。"}, {"text": "吞食", "is_correct": false, "explanation": "语义：“吞食”指把食物咽下，用在抽象的灵感上不合道理。"}], "explanations": {"排放": "语义：“排放”指向外排出废气、废水，与“灵感”的获得无关。", "汲取": "汲取：从自然智慧中吸收有益的内容，与“灵感”搭配，句意通顺。", "倾倒": "搭配：“倾倒”说的是把液体倒出，不能说从智慧中倾倒灵感。", "吞食": "语义：“吞食”指把食物咽下，用在抽象的灵感上不合道理。"}, "sentence_index": 0, "correct_answer": "汲取"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生从病人的手臂上汲取了一管血液做化验。", "explanation": "这里应该用〈抽取〉。汲取 指吸收有益的东西，抽血样本要用“抽取”，不能说“汲取”。"}, {"text": "他通过考试汲取了入学资格。", "explanation": "这里应该用〈获取〉。汲取 的对象是知识、经验、养分这类可以吸收的内容，资格要用“获取”。"}, {"text": "敌军汲取了这座城市。", "explanation": "这里应该用〈夺取〉。汲取 是吸收有益之物，强行占有城市要用“夺取”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94806ba5-fdd3-4ab9-a20c-1bf54e573444') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13885, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "收割", "is_correct": false, "explanation": "语义：“收割”指割取庄稼，用在经验上不合。"}, {"text": "擦拭", "is_correct": false, "explanation": "搭配：“擦拭”针对桌面、玻璃等表面，不能用于经验，与“经验”不搭。"}, {"text": "汲取", "is_correct": true, "explanation": "汲取：从错误中吸收有益的经验，与“经验”搭配，句意通顺。"}, {"text": "点燃", "is_correct": false, "explanation": "搭配：“点燃”多用于火、热情等，不能用于经验。"}], "explanations": {"收割": "语义：“收割”指割取庄稼，用在经验上不合。", "擦拭": "搭配：“擦拭”针对桌面、玻璃等表面，不能用于经验，与“经验”不搭。", "汲取": "汲取：从错误中吸收有益的经验，与“经验”搭配，句意通顺。", "点燃": "搭配：“点燃”多用于火、热情等，不能用于经验。"}, "sentence_index": 6, "correct_answer": "汲取"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他这次考试汲取了一个好成绩，老师很高兴。", "explanation": "这里应该用〈取得〉。汲取 指吸收有益的内容，考试成绩要说“取得”，不能说“汲取”。"}, {"text": "学校向每位学生汲取了一笔学费。", "explanation": "这里应该用〈收取〉。汲取 指吸收有益的内容，向学生收费要用“收取”，不能说“汲取”。"}, {"text": "这家餐厅汲取了很多顾客的好评。", "explanation": "这里应该用〈赢得〉。汲取 指吸收有益的内容，好评是别人给予的，要用“赢得”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94806ba5-fdd3-4ab9-a20c-1bf54e573444') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
